const bank=[{"id": "VM-Y10-ARE-001", "skill": "Composite area", "difficulty": "easy", "question": "A 9 m by 6 m courtyard has a 2 m by 3 m garden removed. Find paved area.", "answer": "48 m²", "solution": "9 × 6 − 2 × 3 = 48.", "topic": "are"}, {"id": "VM-Y10-ARE-002", "skill": "Faces", "difficulty": "easy", "question": "How many rectangular lateral faces does a right pentagonal prism have?", "answer": "5", "solution": "Each edge of the pentagonal base corresponds to one lateral face.", "topic": "are"}, {"id": "VM-Y10-ARE-003", "skill": "Nets", "difficulty": "medium", "question": "A proposed cube net consists of six squares in a single straight row. Explain why it fails.", "answer": "Faces overlap when folded.", "solution": "Four consecutive squares wrap around the cube; the remaining squares cannot close the two ends.", "topic": "are"}, {"id": "VM-Y10-ARE-004", "skill": "Prism surface", "difficulty": "medium", "question": "A right triangular prism has a 3–4–5 cm triangular base and length 10 cm. Find total surface area.", "answer": "132 cm²", "solution": "Two triangles total 12; lateral area = (3+4+5)×10 = 120.", "topic": "are"}, {"id": "VM-Y10-ARE-005", "skill": "Cylinder", "difficulty": "medium", "question": "Find the curved surface area of a cylinder of radius 4 cm and height 7 cm, exactly.", "answer": "56π cm²", "solution": "Unroll the curved face: width 8π, height 7.", "topic": "are"}, {"id": "VM-Y10-ARE-006", "skill": "Open solid", "difficulty": "hard", "question": "A cylindrical container has radius 5 cm and height 12 cm, with no lid. Find material area exactly.", "answer": "145π cm²", "solution": "Base = 25π; curved surface = 120π.", "topic": "are"}, {"id": "VM-Y10-ARE-007", "skill": "Units", "difficulty": "easy", "question": "Convert 0.35 m² to cm².", "answer": "3500 cm²", "solution": "1 m² = 10000 cm².", "topic": "are"}, {"id": "VM-Y10-ARE-008", "skill": "Shared face", "difficulty": "medium", "question": "Two 4 cm cubes are joined face to face. Find the exposed surface area.", "answer": "160 cm²", "solution": "Ten exposed square faces × 16.", "topic": "are"}, {"id": "VM-Y10-ARE-009", "skill": "Sector area", "difficulty": "medium", "question": "Find the exact area of a quarter-circle of radius 8 cm.", "answer": "16π cm²", "solution": "π × 8² ÷ 4.", "topic": "are"}, {"id": "VM-Y10-ARE-010", "skill": "Annulus", "difficulty": "medium", "question": "A circular mat has outer radius 7 cm and a central hole of radius 3 cm. Find its exact area.", "answer": "40π cm²", "solution": "π(49 − 9).", "topic": "are"}, {"id": "VM-Y10-ARE-011", "skill": "Reverse reasoning", "difficulty": "hard", "question": "A closed cylinder has radius 3 cm and total surface area 54π cm². Find its height.", "answer": "6 cm", "solution": "18π + 6πh = 54π.", "topic": "are"}, {"id": "VM-Y10-ARE-012", "skill": "Net dimensions", "difficulty": "medium", "question": "Give the dimensions of the rectangle in the net of a cylinder of diameter 10 cm and height 8 cm.", "answer": "10π cm by 8 cm", "solution": "The rectangle wraps around the circumference.", "topic": "are"}, {"id": "VM-Y10-ARE-013", "skill": "Painting", "difficulty": "hard", "question": "A room is 5 m long, 4 m wide and 3 m high. Paint four walls, excluding a 2 m² door and 3 m² window. Find painted area.", "answer": "49 m²", "solution": "2(5+4)×3 − 2 − 3 = 49.", "topic": "are"}, {"id": "VM-Y10-ARE-014", "skill": "Scaling", "difficulty": "medium", "question": "All dimensions of a prism triple. By what factor is its surface area multiplied?", "answer": "9", "solution": "Every face area scales by 3².", "topic": "are"}, {"id": "VM-Y10-ARE-015", "skill": "Error analysis", "difficulty": "medium", "question": "A student calculates the surface area of a closed cylinder using only 2πrh. What is missing?", "answer": "Both circular ends.", "solution": "Add 2πr².", "topic": "are"}, {"id": "VM-Y10-ARE-016", "skill": "Composite surface", "difficulty": "hard", "question": "A 2 cm cube is attached centrally to the top of a 6 cm cube. Find exposed surface area.", "answer": "232 cm²", "solution": "216 + 24 − 2×4 = 232.", "topic": "are"}, {"id": "VM-Y10-ARE-017", "skill": "Material optimisation", "difficulty": "hard", "question": "A closed cylinder has radius 2 cm and height 6 cm. Compare its surface area with a closed cylinder of radius 3 cm and height 8/3 cm.", "answer": "32π cm² versus 34π cm²", "solution": "Both volumes are 24π. Surface areas are 2πr² + 2πrh: 32π and 34π.", "topic": "are"}, {"id": "VM-Y10-ARE-018", "skill": "Sector composite", "difficulty": "hard", "question": "A window consists of a 4 m wide, 3 m high rectangle topped by a semicircle. Find its area exactly.", "answer": "12 + 2π m²", "solution": "Rectangle area 12; semicircle radius 2 gives area 2π.", "topic": "are"}, {"id": "VM-Y10-ARE-019", "skill": "Net reasoning", "difficulty": "medium", "question": "A triangular prism has base edges 5, 5 and 6 cm and length 9 cm. List the lateral rectangle dimensions. Assume a right prism.", "answer": "5 by 9, 5 by 9, 6 by 9 cm", "solution": "Each lateral face pairs one base edge with prism length.", "topic": "are"}, {"id": "VM-Y10-ARE-020", "skill": "Cost estimate", "difficulty": "hard", "question": "A 2 m by 3 m panel needs paint on both faces. One tin covers 5 m². How many tins are needed? Ignore the edges.", "answer": "3", "solution": "Area = 12 m²; 12 ÷ 5 = 2.4, round up.", "topic": "are"}, {"id": "VM-Y10-ARE-021", "skill": "Reverse composite", "difficulty": "hard", "question": "A rectangular frame has outer dimensions 12 by 10 cm and a uniform 1 cm border. Find the border area.", "answer": "40 cm²", "solution": "Inner dimensions 10 by 8; subtract 80 from 120.", "topic": "are"}, {"id": "VM-Y10-ARE-022", "skill": "Unit reasoning", "difficulty": "hard", "question": "A student converts 2 m² to 200 cm². Explain the mistake.", "answer": "2 m² = 20000 cm²", "solution": "Both dimensions scale by 100, so area scales by 10000.", "topic": "are"}, {"id": "VM-Y10-ARE-023", "skill": "Net recognition", "difficulty": "easy", "question": "A proposed triangular prism net has two congruent triangles and only two rectangles. Is it complete?", "answer": "No", "solution": "A triangular prism needs three rectangular lateral faces.", "topic": "are"}, {"id": "VM-Y10-ARE-024", "skill": "Composite floor", "difficulty": "medium", "question": "A rectangular floor is 8 m by 5 m. A triangular alcove with base 4 m and perpendicular height 2 m is added outside it. Find total area.", "answer": "44 m²", "solution": "8 × 5 + 4 × 2 ÷ 2 = 44.", "topic": "are"}, {"id": "VM-Y10-ARE-025", "skill": "Net construction", "difficulty": "hard", "question": "Draw two different valid nets for a right prism with a 3–4–5 cm triangular cross-section and length 8 cm. Label all edge lengths.", "answer": "Two valid arrangements of three rectangles and two matching triangles.", "solution": "Draw a strip of rectangles 3 × 8, 4 × 8 and 5 × 8 cm joined along their 8 cm edges. Attach a 3–4–5 triangle to a matching edge at each opposite end of the strip. For a second net, attach the triangles to different rectangles at opposite ends. Check that the ends close without overlap.", "topic": "are"}, {"id": "VM-Y10-ARE-026", "skill": "Face counting", "difficulty": "easy", "question": "How many rectangular lateral faces does a right hexagonal prism have?", "answer": "6", "solution": "Each of the six base edges generates one lateral face.", "topic": "are"}, {"id": "VM-Y10-ARE-027", "skill": "Prism surface reasoning", "difficulty": "challenge", "question": "Two right prisms have equal base areas and equal lengths but different base perimeters. Must their surface areas be equal?", "answer": "No", "solution": "Surface area = 2 × base area + base perimeter × length.", "topic": "are"}, {"id": "VM-Y10-ARE-028", "skill": "Material allowance", "difficulty": "medium", "question": "A sign consists of a 4 m by 2 m rectangle topped by a triangle of base 4 m and height 1 m. How much material is needed including 10% extra?", "answer": "11 m²", "solution": "Area = 8 + 2 = 10; multiply by 1.1.", "topic": "are"}, {"id": "VM-Y10-ARE-029", "skill": "Exposed faces", "difficulty": "easy", "question": "A cube rests flat on a table. How many faces are exposed if its bottom face is completely covered? The cube rests on one complete face.", "answer": "5", "solution": "One of six faces is covered.", "topic": "are"}, {"id": "VM-Y10-ARE-030", "skill": "Units", "difficulty": "easy", "question": "Convert 0.03 m² to square centimetres.", "answer": "300 cm²", "solution": "Multiply by 100² = 10,000.", "topic": "are"}, {"id": "VM-Y10-ARE-031", "skill": "Joined solids", "difficulty": "challenge", "question": "Two cubes of side 4 cm are glued together along a complete face. What percentage of their original combined surface area is hidden?", "answer": "16⅔%", "solution": "Original area = 12 × 16; hidden area = 2 × 16; fraction = 1/6.", "topic": "are"}, {"id": "VM-Y10-ARE-032", "skill": "Cylinder reasoning", "difficulty": "challenge", "question": "A closed cylinder has radius r and height 2r. What fraction of its surface area is curved?", "answer": "2/3", "solution": "Curved area = 4πr²; total = 6πr².", "topic": "are"}, {"id": "VM-Y10-ARE-033", "skill": "Plan view", "difficulty": "easy", "question": "A rectangular courtyard measures 8 m by 5 m. A 2 m by 2 m square garden occupies one corner. Find the paved area.", "answer": "36 m²", "solution": "8 × 5 − 2 × 2 = 36.", "topic": "are"}, {"id": "VM-Y10-ARE-034", "skill": "Net dimensions", "difficulty": "medium", "question": "An open rectangular box has base 12 cm by 8 cm and height 5 cm. List the five rectangles in its net and find their total area.", "answer": "12×8, two 12×5, two 8×5; 296 cm²", "solution": "96 + 120 + 80 = 296.", "topic": "are"}, {"id": "VM-Y10-ARE-035", "skill": "Cut-out panel", "difficulty": "hard", "question": "A 1.2 m by 0.8 m panel has two circular holes of radius 0.1 m. Find the area of one remaining face to three decimal places. The holes are non-overlapping and entirely within the panel.", "answer": "0.897 m²", "solution": "1.2 × 0.8 − 2π(0.1)² ≈ 0.897.", "topic": "are"}, {"id": "VM-Y10-ARE-036", "skill": "Coating joined solids", "difficulty": "challenge", "question": "Eight identical cubes are arranged into a solid 2 by 2 by 2 cube. What percentage of their original combined surface area is hidden?", "answer": "50%", "solution": "Originally 48 small faces; the assembled cube exposes 6 × 4 = 24. Half are hidden.", "topic": "are"}, {"id": "VM-Y10-ARE-037", "skill": "Purchase allowance", "difficulty": "medium", "question": "A 5 m by 4 m floor has a 1 m by 2 m untiled recess. Tiles are sold in boxes covering 1.5 m². How many boxes are needed including 10% extra area?", "answer": "14 boxes", "solution": "Area = 20 − 2 = 18; with allowance 19.8. Divide by 1.5 = 13.2 and round up.", "topic": "are"}, {"id": "VM-Y10-ARE-038", "skill": "Material comparison", "difficulty": "hard", "question": "Two closed boxes have dimensions 2 × 3 × 8 cm and 4 × 4 × 3 cm. Both hold 48 cm³. Which uses less surface material and by how much?", "answer": "Second box; 12 cm² less", "solution": "First surface = 2(6 + 16 + 24) = 92; second = 2(16 + 12 + 12) = 80.", "topic": "are"}, {"id": "VM-Y10-ARE-039", "skill": "Coating budget", "difficulty": "hard", "question": "A closed cylinder of radius 0.5 m and height 2 m needs two coats of paint. One litre covers 4 m². Is a 3 L tin enough?", "answer": "No", "solution": "Surface = 2π(0.5)² + 2π(0.5)(2) = 2.5π m². Two coats need 5π/4 ≈ 3.93 L.", "topic": "are"}, {"id": "VM-Y10-ARE-040", "skill": "Shared boundary reasoning", "difficulty": "challenge", "question": "Eight identical unit cubes form a solid 2 × 2 × 2 cube. A corner cube is removed. Explain why the surface area stays unchanged.", "answer": "Three faces lost and three exposed", "solution": "The removed corner had three exterior faces; its three neighbouring faces become exposed. Net change is zero.", "topic": "are"}, {"id": "VM-Y10-ARE-041", "skill": "Face area", "difficulty": "easy", "question": "A rectangular prism has a square end of side 6 cm. Find the area of one end.", "answer": "36 cm²", "solution": "Multiply 6 by 6.", "topic": "are"}, {"id": "VM-Y10-ARE-042", "skill": "Curved surface identification", "difficulty": "easy", "question": "A closed cylinder is wrapped around its curved side only. Are either of the circular ends included in the wrapping area?", "answer": "No", "solution": "The curved surface excludes both circular ends.", "topic": "are"}, {"id": "VM-Y10-ARE-043", "skill": "Missing rectangle", "difficulty": "medium", "question": "An L-shaped floor fits inside a 9 m by 7 m rectangle with a 3 m by 2 m corner removed. Find its area.", "answer": "57 m²", "solution": "Subtract the missing area: 63 − 6 = 57.", "topic": "are"}, {"id": "VM-Y10-ARE-044", "skill": "Label overlap", "difficulty": "medium", "question": "A cylindrical tin has circumference 24 cm and height 11 cm. A rectangular label covers the curved surface and overlaps by 1 cm along its width. Find the label area.", "answer": "275 cm²", "solution": "Label width is 25 cm; area is 25 × 11.", "topic": "are"}, {"id": "VM-Y10-ARE-045", "skill": "Exposed faces", "difficulty": "easy", "question": "A cube rests flat on a table. Each face has area 9 cm². Find the area of its exposed faces.", "answer": "45 cm²", "solution": "Five faces are exposed: 5 × 9.", "topic": "are"}, {"id": "VM-Y10-ARE-046", "skill": "Material allowance", "difficulty": "medium", "question": "A rectangular panel measures 2 m by 1.5 m. Both sides are painted. Paint covers 4 m² per litre. How much paint is required, ignoring edges?", "answer": "1.5 L", "solution": "Painted area = 2 × 2 × 1.5 = 6 m²; divide by 4.", "topic": "are"}, {"id": "VM-Y10-ARE-047", "skill": "Joined solids", "difficulty": "hard", "question": "Two cubes of side 4 cm are glued along one complete face. Find the external surface area.", "answer": "160 cm²", "solution": "There are 12 original faces, of which 2 are hidden. 10 × 16 = 160.", "topic": "are"}, {"id": "VM-Y10-ARE-048", "skill": "Design comparison", "difficulty": "challenge", "question": "Two closed rectangular boxes have dimensions 1 × 4 × 4 cm and 2 × 2 × 4 cm. Which uses less material, and by how much?", "answer": "Second box by 8 cm²", "solution": "First area = 2(4+4+16)=48; second = 2(4+8+8)=40.", "topic": "are"}, {"id": "VM-Y10-ARE-049", "skill": "Area conversion", "difficulty": "easy", "question": "A panel has area 0.35 m². Express it in cm².", "answer": "3500 cm²", "solution": "One square metre equals 10000 square centimetres.", "topic": "are"}, {"id": "VM-Y10-ARE-050", "skill": "Seam comparison", "difficulty": "medium", "question": "Two 8 cm by 5 cm rectangles are joined along an entire 5 cm edge. Find the perimeter of the resulting rectangle. The rectangles do not overlap.", "answer": "42 cm", "solution": "The joined rectangle is 16 cm by 5 cm; perimeter = 2(16 + 5).", "topic": "are"}, {"id": "VM-Y10-ARE-051", "skill": "Hidden surface", "difficulty": "hard", "question": "A cube of side 6 cm has a square hole of side 2 cm drilled straight through opposite faces. Find its total exposed surface area. The tunnel is perpendicular to the opposite faces and lies entirely within them.", "answer": "256 cm²", "solution": "Original area = 216. Remove two openings of area 4 each and add four tunnel walls of area 12 each: 216 − 8 + 48 = 256.", "topic": "are"}, {"id": "VM-Y10-ARE-052", "skill": "Fixed area", "difficulty": "challenge", "question": "A closed rectangular box has dimensions 2 cm, 3 cm and h cm. Its surface area equals that of a cube of side 4 cm. Find h.", "answer": "8.4 cm", "solution": "Cube area = 96. Box area = 2(6 + 2h + 3h) = 12 + 10h. Equate and solve.", "topic": "are"}, {"id": "VM-Y10-ARE-053", "skill": "Cylinder ends", "difficulty": "easy", "question": "A cylindrical tube is open at both ends. Which part of its surface is counted if wall thickness is ignored? Count a single idealised curved surface.", "answer": "Curved surface only.", "solution": "There are no circular end faces; the curved area is 2πrh.", "topic": "are"}, {"id": "VM-Y10-ARE-054", "skill": "Corner removal", "difficulty": "medium", "question": "A 12 cm by 8 cm rectangle has a 3 cm by 2 cm rectangle cut from one corner. Find the remaining area and perimeter.", "answer": "90 cm²; 40 cm", "solution": "Area = 96−6. The removed outer edges are replaced by equal-length inner edges, so perimeter remains 2(12+8).", "topic": "are"}, {"id": "VM-Y10-ARE-055", "skill": "Face coverage", "difficulty": "hard", "question": "A 6 cm cube is cut into eight identical smaller cubes. Find the total surface area of all eight cubes.", "answer": "432 cm²", "solution": "Each small cube has side 3 cm and area 6×9=54 cm². Multiply by 8.", "topic": "are"}, {"id": "VM-Y10-ARE-056", "skill": "Net comparison", "difficulty": "challenge", "question": "A closed rectangular box has square ends of side 4 cm and length L cm. A closed cube of side 6 cm uses the same surface area. Find L.", "answer": "11.5 cm", "solution": "Box area = 32+16L. Cube area = 216. Hence L=(216−32)÷16.", "topic": "are"}, {"id": "VM-Y10-ARE-057", "skill": "Area of remaining sheet", "difficulty": "easy", "question": "A 10 cm by 8 cm sheet has a circular hole of radius 2 cm. Write its remaining area exactly.", "answer": "(80 − 4π) cm²", "solution": "Rectangle area 80 minus circle area π × 2².", "topic": "are"}, {"id": "VM-Y10-ARE-058", "skill": "Prism end faces", "difficulty": "medium", "question": "A closed triangular prism has two triangular ends of area 18 cm² each. Its three rectangular faces total 90 cm². Find its surface area.", "answer": "126 cm²", "solution": "Add both ends: 90 + 2 × 18 = 126.", "topic": "are"}, {"id": "VM-Y10-ARE-059", "skill": "Open cylinder comparison", "difficulty": "hard", "question": "Two cylinders have radius 3 cm and height 8 cm. One has both ends closed; the other has neither end. Find the difference in surface area exactly. Ignore wall thickness and count one curved surface per cylinder.", "answer": "18π cm²", "solution": "Curved surfaces cancel; two circular ends contribute 2π × 3².", "topic": "are"}, {"id": "VM-Y10-ARE-060", "skill": "Joining orientation", "difficulty": "challenge", "question": "Two identical 2 cm by 3 cm by 5 cm rectangular blocks are joined along entire matching faces. Which face dimensions minimise the exposed surface area, and what is that area?", "answer": "3 cm by 5 cm; 94 cm²", "solution": "Each block has area 2(6+10+15)=62. Joining the largest face removes 30 from 124, leaving 94.", "topic": "are"}, {"id": "VM-Y10-ARE-061", "skill": "Net inventory", "difficulty": "easy", "question": "A closed triangular prism has triangular ends and rectangular side faces. How many of each face must its net contain?", "answer": "2 triangles and 3 rectangles", "solution": "Each triangle edge corresponds to one rectangular side face.", "topic": "are"}, {"id": "VM-Y10-ARE-062", "skill": "Sheet utilisation", "difficulty": "medium", "question": "A 60 cm by 40 cm sheet has two non-overlapping circular holes of radius 5 cm. Find the remaining area exactly. Both holes lie entirely within the sheet.", "answer": "2400 − 50π cm²", "solution": "Subtract two areas of π × 5² from 60 × 40.", "topic": "are"}, {"id": "VM-Y10-ARE-063", "skill": "Coating exclusions", "difficulty": "hard", "question": "A closed cylinder of radius 4 cm and height 12 cm rests on one circular end. Only the exposed surfaces are painted. Find the painted area exactly.", "answer": "112π cm²", "solution": "Curved area = 2π × 4 × 12 = 96π. Add the top area 16π.", "topic": "are"}, {"id": "VM-Y10-ARE-064", "skill": "Net feasibility", "difficulty": "challenge", "question": "A rectangular box measures 8 cm by 5 cm by 3 cm. A proposed net has two 8 by 5 rectangles, two 8 by 3 rectangles and two 5 by 3 rectangles. Is the face inventory alone enough to prove the net folds correctly?", "answer": "No", "solution": "The inventory is necessary but the arrangement also matters. Faces may overlap after folding or fail to meet along matching edges.", "topic": "are"}, {"id": "VM-Y10-ARE-065", "skill": "Surface units", "difficulty": "easy", "question": "A net has total area 0.06 m². Express this in cm².", "answer": "600 cm²", "solution": "1 m² = 10,000 cm², so multiply by 10,000.", "topic": "are"}, {"id": "VM-Y10-ARE-066", "skill": "Folded tray", "difficulty": "medium", "question": "A 20 cm by 14 cm sheet has a 3 cm square removed from each corner before folding into an open tray. Find the area of material remaining.", "answer": "244 cm²", "solution": "Original area = 280; four removed squares total 36; remaining area = 244.", "topic": "are"}, {"id": "VM-Y10-ARE-067", "skill": "Prism seam reasoning", "difficulty": "hard", "question": "A triangular prism has cross-section sides 5, 5 and 6 cm and length 12 cm. A sleeve covers only its three rectangular faces. Find the sleeve area. Assume a right prism.", "answer": "192 cm²", "solution": "The sleeve unfolds to a rectangle of width 5+5+6 = 16 cm and length 12 cm.", "topic": "are"}, {"id": "VM-Y10-ARE-068", "skill": "Cylinder label constraint", "difficulty": "challenge", "question": "A cylindrical tin has radius 4 cm and height 15 cm. A label covers the curved surface except for a 2 cm high band at each end, with 1 cm overlap around the circumference. Find the rectangular label area to one decimal place.", "answer": "287.5 cm²", "solution": "Label height = 11 cm; width = 8π+1 cm. Area = 11(8π+1) ≈ 287.5.", "topic": "are"}, {"id": "VM-Y10-ARE-069", "skill": "Exposed faces", "difficulty": "easy", "question": "Two identical cubes are glued face to face. How many square faces of the original cubes remain exposed?", "answer": "10", "solution": "There were 12 faces; the two glued faces are hidden.", "topic": "are"}, {"id": "VM-Y10-ARE-070", "skill": "Sector area", "difficulty": "medium", "question": "A circular sign of radius 12 cm has a 90° sector removed. Find the remaining area in terms of π.", "answer": "108π cm²", "solution": "Remaining fraction = 3/4; area = 3/4 × π × 144 = 108π.", "topic": "are"}, {"id": "VM-Y10-ARE-071", "skill": "Coating allowance", "difficulty": "hard", "question": "A closed cylinder has radius 4 cm and height 10 cm. A coating covers only the curved surface and one circular end. Find the coated area exactly.", "answer": "96π cm²", "solution": "Curved area = 2π × 4 × 10 = 80π; one end = 16π.", "topic": "are"}, {"id": "VM-Y10-ARE-072", "skill": "Cutting surface", "difficulty": "challenge", "question": "A 6 cm cube is cut into two equal rectangular prisms by a plane parallel to a face. By how much does their combined surface area increase?", "answer": "72 cm²", "solution": "The cut creates two new 6 × 6 faces; increase = 72.", "topic": "are"}, {"id": "VM-Y10-ARE-073", "skill": "Net components", "difficulty": "easy", "question": "A closed right hexagonal prism has how many faces altogether?", "answer": "8", "solution": "Two hexagonal ends and six rectangular lateral faces.", "topic": "are"}, {"id": "VM-Y10-ARE-074", "skill": "Annular area", "difficulty": "medium", "question": "A circular mat has outer radius 9 cm and a central circular hole of radius 3 cm. Find its area exactly.", "answer": "72π cm²", "solution": "π(9² − 3²) = 72π.", "topic": "are"}, {"id": "VM-Y10-ARE-075", "skill": "Missing face", "difficulty": "medium", "question": "A lidless rectangular tray measures 12 cm by 8 cm by 3 cm internally. Ignoring thickness, find the interior surface area.", "answer": "216 cm²", "solution": "12 × 8 + 2 × 12 × 3 + 2 × 8 × 3 = 216.", "topic": "are"}, {"id": "VM-Y10-ARE-076", "skill": "Joined cylinders", "difficulty": "hard", "question": "Two solid cylinders of radius 3 cm and heights 5 cm and 8 cm are joined along a circular end. Find the external surface area exactly.", "answer": "96π cm²", "solution": "Curved area = 2π × 3 × 13 = 78π; exposed ends = 18π.", "topic": "are"}, {"id": "VM-Y10-ARE-077", "skill": "Face classification", "difficulty": "easy", "question": "A closed cylinder has two flat faces. What shape are they?", "answer": "Circles", "solution": "The two ends are circular.", "topic": "are"}, {"id": "VM-Y10-ARE-078", "skill": "Material allowance", "difficulty": "medium", "question": "A rectangular sign measuring 80 cm by 50 cm is covered on both sides. How many square metres of film are required, ignoring edges?", "answer": "0.8 m²", "solution": "2 × 0.8 × 0.5 = 0.8.", "topic": "are"}, {"id": "VM-Y10-ARE-079", "skill": "Sector area", "difficulty": "medium", "question": "A circular garden of radius 6 m has a 120° sector planted with herbs. Find the herb area exactly.", "answer": "12π m²", "solution": "120/360 × π × 6² = 12π.", "topic": "are"}, {"id": "VM-Y10-ARE-080", "skill": "Exposed faces", "difficulty": "hard", "question": "Three 2 cm cubes form a straight row, joined face to face. Find the exposed surface area.", "answer": "56 cm²", "solution": "Three cubes have 72 cm² total; two joins hide four faces of 4 cm² each, leaving 56.", "topic": "are"}, {"id": "VM-Y10-ARE-081", "skill": "Face area", "difficulty": "easy", "question": "A triangular end of a prism has base 9 cm and perpendicular height 4 cm. Find its area.", "answer": "18 cm²", "solution": "Area = 9 × 4 ÷ 2 = 18.", "topic": "are"}, {"id": "VM-Y10-ARE-082", "skill": "Open cylinder", "difficulty": "medium", "question": "A cylindrical pencil holder has radius 4 cm and height 12 cm, with no lid. Find its external surface area ignoring thickness.", "answer": "112π cm²", "solution": "Curved area = 2π × 4 × 12 = 96π; base = 16π.", "topic": "are"}, {"id": "VM-Y10-ARE-083", "skill": "Material overlap", "difficulty": "medium", "question": "A rectangular panel measures 80 cm by 50 cm. A 5 cm-wide border runs around its inside edge. Find the area of the border.", "answer": "1200 cm²", "solution": "Outer area = 4000; inner area = 70 × 40 = 2800; difference = 1200.", "topic": "are"}, {"id": "VM-Y10-ARE-084", "skill": "Joined prisms", "difficulty": "hard", "question": "A 4 cm cube is glued centrally onto the top of a 10 cm by 8 cm by 3 cm rectangular prism. Find the exposed surface area.", "answer": "332 cm²", "solution": "Prism area = 2(80 + 30 + 24) = 268; cube area = 96; subtract two contact faces of 16 each: 332.", "topic": "are"}, {"skill": "Exposed faces", "difficulty": "easy", "question": "A cube is painted on all faces except two opposite faces. How many faces are painted?", "answer": "4", "solution": "A cube has six faces; subtract two.", "id": "VM-Y10-ARE-085", "topic": "are"}, {"skill": "Label overlap", "difficulty": "medium", "question": "A cylindrical jar has diameter 8 cm. A label wraps around it with 1 cm overlap and is 6 cm high. Find the label area in terms of π.", "answer": "(48π + 6) cm²", "solution": "Width = 8π + 1; multiply by 6.", "id": "VM-Y10-ARE-086", "topic": "are"}, {"skill": "Cutout area", "difficulty": "medium", "question": "A rectangular sign measuring 50 cm by 30 cm has four circular holes of radius 2 cm. Find its remaining front area in terms of π. The holes are non-overlapping and entirely within the sign.", "answer": "(1500 − 16π) cm²", "solution": "Subtract four areas of 4π from 1500.", "id": "VM-Y10-ARE-087", "topic": "are"}, {"skill": "Joined prisms", "difficulty": "hard", "question": "Two solid cubes of side 6 cm are joined so that a 3 cm by 6 cm rectangle of one face touches the other cube. Find the exposed surface area.", "answer": "396 cm²", "solution": "Separate areas total 432; subtract two contact areas of 18.", "id": "VM-Y10-ARE-088", "topic": "are"}, {"id": "VM-Y10-ARE-089", "skill": "Net matching", "difficulty": "easy", "question": "A net contains two congruent pentagons and five rectangles. Name the solid.", "answer": "Pentagonal prism", "solution": "The pentagons are the ends and the five rectangles join corresponding edges.", "topic": "are"}, {"id": "VM-Y10-ARE-090", "skill": "Annular face", "difficulty": "medium", "question": "A flat washer has outer diameter 12 cm and inner diameter 8 cm. Find the area of one flat face exactly.", "answer": "20π cm²", "solution": "π(6² − 4²) = 20π.", "topic": "are"}, {"id": "VM-Y10-ARE-091", "skill": "Cutting a cylinder", "difficulty": "hard", "question": "A solid cylinder of radius 4 cm and height 15 cm is cut lengthwise through its axis. Find the total surface area of one half exactly.", "answer": "(76π + 120) cm²", "solution": "Half the curved area is 60π; two semicircles total 16π; the cut rectangle is 8 × 15 = 120.", "topic": "are"}, {"id": "VM-Y10-ARE-092", "skill": "Sheet layout", "difficulty": "hard", "question": "A workshop needs six rectangular panels measuring 35 cm by 45 cm. Sheets measure 100 cm by 100 cm. Can one sheet suffice if panel edges must remain parallel to sheet edges (90° rotation allowed)? Justify.", "answer": "No", "solution": "Six panels require 9450 cm², but area alone is insufficient. For axis-aligned cuts, any horizontal line crosses at most two panels since 3 × 35 > 100. The sum of panel heights is at least 210 cm, exceeding the 200 cm available under that restriction. This conclusion assumes edges parallel to sheet edges.", "topic": "are"}, {"id": "VM-Y10-ARE-093", "skill": "Area conversion", "difficulty": "easy", "question": "A label covers 0.035 m². Express its area in square centimetres.", "answer": "350 cm²", "solution": "Multiply by 10 000.", "topic": "are"}, {"id": "VM-Y10-ARE-094", "skill": "Shared edge", "difficulty": "medium", "question": "Two identical 8 cm by 3 cm rectangles are joined along their 8 cm edges without overlap. Find the perimeter of the resulting rectangle.", "answer": "28 cm", "solution": "The combined rectangle is 8 by 6; perimeter = 2(8 + 6).", "topic": "are"}, {"id": "VM-Y10-ARE-095", "skill": "Net reasoning", "difficulty": "medium", "question": "A closed triangular prism has triangular ends of area 18 cm² each and three rectangular faces of areas 40, 50 and 60 cm². Find total surface area.", "answer": "186 cm²", "solution": "2 × 18 + 40 + 50 + 60 = 186.", "topic": "are"}, {"id": "VM-Y10-ARE-096", "skill": "Painted cylinder", "difficulty": "medium", "question": "A cylinder of radius 4 cm and height 9 cm is painted on its curved surface and one circular end only. Give the painted area exactly.", "answer": "88π cm²", "solution": "2π × 4 × 9 + π × 4² = 88π.", "topic": "are"}, {"id": "VM-Y10-ARE-097", "skill": "Removed corner", "difficulty": "hard", "question": "A 10 cm square has a rectangular notch 2 cm wide and 3 cm deep cut from the middle of one edge. Find its remaining area and perimeter.", "answer": "94 cm²; 46 cm", "solution": "Area = 100 − 6. The notch replaces a 2 cm edge with 2 + 3 + 3 cm, adding 6 to perimeter 40.", "topic": "are"}, {"id": "VM-Y10-ARE-098", "skill": "Surface area constraint", "difficulty": "hard", "question": "A closed rectangular box has base 5 cm by 8 cm and total surface area 210 cm². Find its height.", "answer": "5 cm", "solution": "80 + 2(5 + 8)h = 210; h = 5.", "topic": "are"}, {"id": "VM-Y10-ARE-099", "skill": "Area units", "difficulty": "easy", "question": "Convert 0.36 m² to cm².", "answer": "3600 cm²", "solution": "Multiply by 10000.", "topic": "are"}, {"id": "VM-Y10-ARE-100", "skill": "Net recognition", "difficulty": "easy", "question": "A right prism has seven rectangular lateral faces. What shape are its ends?", "answer": "Heptagons", "solution": "Each side of the end polygon corresponds to one lateral face.", "topic": "are"}, {"id": "VM-Y10-ARE-101", "skill": "Annular area", "difficulty": "medium", "question": "A circular mat of radius 9 cm has a central circular hole of radius 4 cm. Find its area exactly.", "answer": "65π cm²", "solution": "π(9² − 4²) = 65π.", "topic": "are"}, {"id": "VM-Y10-ARE-102", "skill": "Open prism", "difficulty": "medium", "question": "A rectangular tray has base 30 cm by 18 cm and vertical sides 4 cm high. Find its inside surface area, ignoring thickness.", "answer": "924 cm²", "solution": "540 + 2(30 × 4) + 2(18 × 4) = 924.", "topic": "are"}, {"id": "VM-Y10-ARE-103", "skill": "Equal surface areas", "difficulty": "hard", "question": "A cube has the same surface area as a closed rectangular box measuring 2 cm by 3 cm by 6 cm. Find the cube edge exactly.", "answer": "2√3 cm", "solution": "Box area = 2(6 + 12 + 18) = 72 cm²; 6s² = 72, so s = √12 = 2√3 cm.", "topic": "are"}, {"id": "VM-Y10-ARE-104", "skill": "Sector removal", "difficulty": "hard", "question": "A 90° sector is removed from a circular sheet of radius 8 cm. Find the perimeter of the remaining major sector exactly.", "answer": "12π + 16 cm", "solution": "Remaining arc is three quarters of 16π; add two radii.", "topic": "are"}, {"id": "VM-Y10-ARE-105", "skill": "Area scaling", "difficulty": "easy", "question": "A square tile has area 49 cm². A similar tile has twice its side length. Find its area.", "answer": "196 cm²", "solution": "Area scales by 2².", "topic": "are"}, {"id": "VM-Y10-ARE-106", "skill": "Cylinder net", "difficulty": "easy", "question": "A cylinder has radius 3 cm and height 11 cm. State the exact length of the rectangular net edge that wraps around its base.", "answer": "6π cm", "solution": "Circumference = 2πr.", "topic": "are"}, {"id": "VM-Y10-ARE-107", "skill": "Composite area", "difficulty": "medium", "question": "A 12 cm by 9 cm rectangle has a semicircle of diameter 12 cm attached externally along its long edge. Find total area exactly.", "answer": "108 + 18π cm²", "solution": "Rectangle area 108; semicircle area ½π(6²).", "topic": "are"}, {"id": "VM-Y10-ARE-108", "skill": "Coating", "difficulty": "medium", "question": "A closed cube of side 8 cm is painted except for one face. Find the painted area.", "answer": "320 cm²", "solution": "Five faces each have area 64.", "topic": "are"}, {"id": "VM-Y10-ARE-109", "skill": "Cylinder comparison", "difficulty": "hard", "question": "Two closed cylinders have equal radius 5 cm. Their heights differ by 7 cm. Find the exact difference in total surface area.", "answer": "70π cm²", "solution": "End areas cancel; curved area difference = 2π × 5 × 7.", "topic": "are"}, {"id": "VM-Y10-ARE-110", "skill": "Cutting solids", "difficulty": "hard", "question": "A 10 cm by 6 cm by 4 cm rectangular block is cut into two pieces by a plane parallel to its 6 cm by 4 cm face. Find the increase in combined surface area.", "answer": "48 cm²", "solution": "Two new faces of area 24 each are exposed.", "topic": "are"}, {"id": "VM-Y10-ARE-111", "skill": "Area units", "difficulty": "easy", "question": "A rectangular tile covers 750 cm². Express its area in m².", "answer": "0.075 m²", "solution": "Divide 750 by 10,000 to obtain 0.075 m².", "topic": "are"}, {"id": "VM-Y10-ARE-112", "skill": "Triangle height", "difficulty": "easy", "question": "A triangle has area 42 cm² and base 12 cm. Find its perpendicular height.", "answer": "7 cm", "solution": "Height = 2 × 42 ÷ 12.", "topic": "are"}, {"id": "VM-Y10-ARE-113", "skill": "Annular region", "difficulty": "medium", "question": "A circular mat of radius 9 cm has a circular hole of radius 4 cm. Find its remaining area exactly. The hole lies entirely within the mat.", "answer": "65π cm²", "solution": "π(81 − 16) = 65π.", "topic": "are"}, {"id": "VM-Y10-ARE-114", "skill": "Open prism", "difficulty": "medium", "question": "An open rectangular tray has base 24 cm by 15 cm and vertical sides 4 cm high. Find its internal surface area.", "answer": "672 cm²", "solution": "360 + 2 × 24 × 4 + 2 × 15 × 4 = 672.", "topic": "are"}, {"id": "VM-Y10-ARE-115", "skill": "Sector comparison", "difficulty": "hard", "question": "A sector of radius 12 cm and angle 80° has the same area as a sector of radius 8 cm. Find the second angle.", "answer": "180°", "solution": "80 × 144 = θ × 64; θ = 180.", "topic": "are"}, {"id": "VM-Y10-ARE-116", "skill": "Joined solids", "difficulty": "hard", "question": "Two identical closed cylinders of radius 3 cm and height 8 cm are joined along one circular face. Find the exposed surface area exactly.", "answer": "114π cm²", "solution": "Combined height 16; curved area 96π plus two ends 18π.", "topic": "are"}, {"id": "VM-Y10-ARE-117", "skill": "Area conversion", "difficulty": "easy", "question": "A square has side length 30 cm. Find its area in square metres.", "answer": "0.09 m²", "solution": "30 cm = 0.3 m; area = 0.3 × 0.3 = 0.09 m².", "topic": "are"}, {"id": "VM-Y10-ARE-118", "skill": "Exposed faces", "difficulty": "easy", "question": "A cube has six faces of area 25 cm² each. One face is painted blue and the rest yellow. Find the yellow area.", "answer": "125 cm²", "solution": "Five yellow faces each have area 25 cm².", "topic": "are"}, {"id": "VM-Y10-ARE-119", "skill": "Annulus", "difficulty": "medium", "question": "A circular coaster has radius 9 cm and a central circular hole of radius 2 cm. Find its area exactly.", "answer": "77π cm²", "solution": "π(9² − 2²) = 77π.", "topic": "are"}, {"id": "VM-Y10-ARE-120", "skill": "Prism lateral area", "difficulty": "medium", "question": "A triangular prism has end sides 5, 12 and 13 cm and length 9 cm. Find its lateral surface area. Assume a right prism.", "answer": "270 cm²", "solution": "(5 + 12 + 13) × 9 = 270.", "topic": "are"}, {"id": "VM-Y10-ARE-121", "skill": "Cylinder material", "difficulty": "hard", "question": "An open cylindrical container has radius 4 cm and height 11 cm. Find the exact area of material needed, ignoring seams.", "answer": "104π cm²", "solution": "Base plus curved area = 16π + 88π.", "topic": "are"}, {"id": "VM-Y10-ARE-122", "skill": "Area constraint", "difficulty": "hard", "question": "A rectangular courtyard is 18 m by 12 m. A uniform 1.5 m wide border is laid inside all four edges. Find the border area.", "answer": "81 m²", "solution": "216 − (15 × 9) = 81.", "topic": "are"}, {"id": "VM-Y10-ARE-123", "skill": "Surface area reasoning", "difficulty": "easy", "question": "A closed triangular prism has how many rectangular lateral faces? Assume a right prism.", "answer": "3", "solution": "Each of the three triangle edges corresponds to one lateral face.", "topic": "are"}, {"id": "VM-Y10-ARE-124", "skill": "Composite area", "difficulty": "medium", "question": "A circular pond of radius 3 m is surrounded by a path extending 1 m outward. Find the path area exactly.", "answer": "7π m²", "solution": "Subtract inner area 9π from outer area 16π.", "topic": "are"}, {"id": "VM-Y10-ARE-125", "skill": "Sector area", "difficulty": "medium", "question": "A circular fan covers 72° of a circle of radius 15 cm. Find its area exactly.", "answer": "45π cm²", "solution": "72/360 × π × 15² = 45π.", "topic": "are"}, {"id": "VM-Y10-ARE-126", "skill": "Surface area change", "difficulty": "hard", "question": "A closed cylinder of radius 4 cm and height 10 cm is cut horizontally into two cylinders. Find the increase in total surface area. The cut is parallel to the circular bases.", "answer": "32π cm²", "solution": "Two new circular faces appear, each with area 16π.", "topic": "are"}, {"id": "VM-Y10-ARE-127", "skill": "Material estimation", "difficulty": "hard", "question": "A 12 m by 8 m wall has three windows each 1.5 m by 2 m. Paint covers 9 m² per litre per coat. How many whole litres are needed for two coats?", "answer": "20 L", "solution": "Painted area = 96 − 9 = 87; two coats need 174/9 = 19.33… L; round up.", "topic": "are"}, {"id": "VM-Y10-ARE-128", "skill": "Area scaling", "difficulty": "medium", "question": "A poster is enlarged so each length is 150% of its original length. Its original area is 320 cm². Find its new area.", "answer": "720 cm²", "solution": "Area scale factor = 1.5² = 2.25; multiply by 320.", "topic": "are"}, {"id": "VM-Y10-ARE-129", "skill": "Area units", "difficulty": "easy", "question": "A label states that a sheet has area 600 mm². Express this area in cm².", "answer": "6 cm²", "solution": "Divide by 100 because 1 cm² = 100 mm².", "topic": "are"}, {"id": "VM-Y10-ARE-130", "skill": "Circle area", "difficulty": "easy", "question": "A circular coaster has diameter 14 cm. Give its exact area.", "answer": "49π cm²", "solution": "Radius 7; area π×7².", "topic": "are"}, {"id": "VM-Y10-ARE-131", "skill": "Surface area", "difficulty": "easy", "question": "A cube has edge 0.4 m. Find its total surface area.", "answer": "0.96 m²", "solution": "6×0.4²=0.96.", "topic": "are"}, {"id": "VM-Y10-ARE-132", "skill": "Composite area", "difficulty": "easy", "question": "A 12 m by 8 m lawn has a 3 m by 2 m flower bed removed. Find the grass area.", "answer": "90 m²", "solution": "96−6=90.", "topic": "are"}, {"id": "VM-Y10-ARE-133", "skill": "Sector area", "difficulty": "easy", "question": "What fraction of a circle's area belongs to a 135° sector?", "answer": "3/8", "solution": "135/360 simplifies to 3/8.", "topic": "are"}, {"id": "VM-Y10-ARE-134", "skill": "Surface area", "difficulty": "medium", "question": "A cylindrical sleeve has radius 4 cm and height 11 cm, with no ends. Find its exact material area.", "answer": "88π cm²", "solution": "Curved area 2πrh=88π.", "topic": "are"}, {"id": "VM-Y10-ARE-135", "skill": "Composite area", "difficulty": "medium", "question": "A semicircle of diameter 10 cm is attached externally along the 10 cm side of a 10 cm by 7 cm rectangle. Find exact total area.", "answer": "(70 + 12.5π) cm²", "solution": "Rectangle 70; semicircle π×25/2.", "topic": "are"}, {"id": "VM-Y10-ARE-136", "skill": "Area scale", "difficulty": "medium", "question": "A map uses scale 1:200. A garden occupies 18 cm² on the map. Find actual area in m².", "answer": "72 m²", "solution": "18×200² cm² = 720000 cm² =72 m².", "topic": "are"}, {"id": "VM-Y10-ARE-137", "skill": "Surface area", "difficulty": "medium", "question": "A closed rectangular box measures 9 cm by 6 cm by 4 cm. How much area is covered if every face except one 9 by 6 face is painted?", "answer": "174 cm²", "solution": "2(54+36+24)−54=174.", "topic": "are"}, {"id": "VM-Y10-ARE-138", "skill": "Sector area", "difficulty": "medium", "question": "A sector of radius 12 cm has area 24π cm². Find its central angle.", "answer": "60°", "solution": "Fraction 24/144=1/6; multiply by 360.", "topic": "are"}, {"id": "VM-Y10-ARE-139", "skill": "Composite area", "difficulty": "medium", "question": "A square tile of side 16 cm has a circular hole of radius 3 cm. Give exact remaining area. The hole lies entirely within the tile.", "answer": "256 − 9π cm²", "solution": "Subtract circle area from square area.", "topic": "are"}, {"id": "VM-Y10-ARE-140", "skill": "Surface area", "difficulty": "medium", "question": "A right triangular prism has triangular sides 5, 12 and 13 cm and length 8 cm. Find lateral surface area.", "answer": "240 cm²", "solution": "Perimeter 30 multiplied by length 8.", "topic": "are"}, {"id": "VM-Y10-ARE-141", "skill": "Area reasoning", "difficulty": "medium", "question": "A parallelogram has area 84 cm² and perpendicular height 7 cm. Its base is extended by 3 cm with height unchanged. Find new area.", "answer": "105 cm²", "solution": "Original base 12; new base 15; multiply by 7.", "topic": "are"}, {"id": "VM-Y10-ARE-142", "skill": "Composite area", "difficulty": "hard", "question": "A 12 m by 8 m lawn is surrounded externally by a uniform 2 m path. Find the path area.", "answer": "96 m²", "solution": "Outer dimensions 16 by 12; subtract lawn area: 192 − 96 = 96.", "topic": "are"}, {"id": "VM-Y10-ARE-143", "skill": "Surface area", "difficulty": "hard", "question": "A closed cylinder has radius 5 cm and total surface area 180π cm². Find height.", "answer": "13 cm", "solution": "180π=50π+10πh, so h=13.", "topic": "are"}, {"id": "VM-Y10-ARE-144", "skill": "Surface area", "difficulty": "hard", "question": "Two identical 8 by 5 by 3 cm boxes are joined along their 8 by 3 faces. Find external surface area.", "answer": "268 cm²", "solution": "Each area 2(40+24+15)=158; subtract 48 from 316.", "topic": "are"}, {"id": "VM-Y10-ARE-145", "skill": "Composite area", "difficulty": "hard", "question": "A circular track has outer diameter 30 m and inner diameter 24 m. Find exact track area.", "answer": "81π m²", "solution": "π(15²−12²)=81π.", "topic": "are"}, {"id": "VM-Y10-ARE-146", "skill": "Area scale", "difficulty": "hard", "question": "A solid's surface area increases from 96 cm² to 216 cm² under enlargement. Find the linear scale factor.", "answer": "1.5", "solution": "Square root of 216/96 =1.5.", "topic": "are"}, {"id": "VM-Y10-ARE-147", "skill": "Surface area", "difficulty": "hard", "question": "A closed rectangular box measures 10 cm by 8 cm by 6 cm. A coating covers all faces except the base (10 cm by 8 cm). Find the cost at $0.05 per cm².", "answer": "$14.80", "solution": "Area = 80 + 2(60 + 48) = 296 cm²; cost = 296 × 0.05.", "topic": "are"}, {"id": "VM-Y10-ARE-148", "skill": "Sector area", "difficulty": "hard", "question": "A 120° sector has radius 6 cm. Find the radius of a semicircle with equal area, in exact form.", "answer": "2√6 cm", "solution": "Sector area = 12π; semicircle area = πr²/2. Thus r² = 24.", "topic": "are"}, {"id": "VM-Y10-ARE-149", "skill": "Area optimisation", "difficulty": "challenge", "question": "A rectangle of perimeter 40 cm has a semicircle attached externally along a side of length w. The other side has length 20−w. Express combined area and find the side length w maximising it.", "answer": "A=20w−(1−π/8)w²; w=10/(1−π/8) cm", "solution": "Semicircle area πw²/8. Complete square; vertex width about 16.47, within 0<w<20.", "topic": "are"}, {"id": "VM-Y10-ARE-150", "skill": "Surface area reasoning", "difficulty": "challenge", "question": "A closed cylinder of radius r and height 4r has the same surface area as a cube of edge 10 cm. Find r exactly.", "answer": "√(60/π) cm", "solution": "Cylinder area 2πr²+8πr²=10πr²; cube area 600.", "topic": "are"}, {"id": "VM-Y10-DAT-001", "skill": "Variables", "difficulty": "easy", "question": "A researcher records each student’s height and arm span. Is this univariate or bivariate data?", "answer": "Bivariate", "solution": "Two numerical measurements are recorded for each student.", "topic": "dat"}, {"id": "VM-Y10-DAT-002", "skill": "Association", "difficulty": "medium", "question": "Ice cream sales and swimming attendance both increase on hot days. Does this establish that ice cream causes swimming?", "answer": "No", "solution": "Temperature may influence both variables; association alone does not establish causation.", "topic": "dat"}, {"id": "VM-Y10-DAT-003", "skill": "Variables", "difficulty": "medium", "question": "An experiment changes fertiliser amount and measures plant growth. Identify the independent and dependent variables.", "answer": "Fertiliser amount; plant growth", "solution": "The input is deliberately changed and growth is measured.", "topic": "dat"}, {"id": "VM-Y10-DAT-004", "skill": "Scatter plot", "difficulty": "medium", "question": "Plot the pairs (1,8), (2,6), (3,5), (4,3). Describe the association.", "answer": "Negative association", "solution": "As x increases, y generally decreases.", "topic": "dat"}, {"id": "VM-Y10-DAT-005", "skill": "Prediction", "difficulty": "medium", "question": "A fitted line is y = 4x + 10 for observed x-values 1 to 8. Predict y at x = 5.", "answer": "30", "solution": "Substitute 5: 4×5+10 = 30.", "topic": "dat"}, {"id": "VM-Y10-DAT-006", "skill": "Extrapolation", "difficulty": "hard", "question": "Explain why using that same fitted line to predict at x = 100 may be unreliable when observed x-values are 1 to 8.", "answer": "It is extrapolation far outside the data range.", "solution": "The observed relationship may not continue beyond the measured range.", "topic": "dat"}, {"id": "VM-Y10-DAT-007", "skill": "Association", "difficulty": "easy", "question": "As the age of used cars increases, their resale price generally falls. Describe the direction of association.", "answer": "Negative", "solution": "Larger age tends to accompany lower price.", "topic": "dat"}, {"id": "VM-Y10-DAT-008", "skill": "Outlier", "difficulty": "medium", "question": "The pairs (1,2), (2,4), (3,6), (4,8), (5,1) are plotted. Identify the point that departs most from the main pattern.", "answer": "(5,1)", "solution": "The first four follow y = 2x; the last does not.", "topic": "dat"}, {"id": "VM-Y10-DAT-009", "skill": "Interpolation", "difficulty": "medium", "question": "A fitted model uses observations from 10 to 30 minutes. Is a prediction at 18 minutes interpolation or extrapolation?", "answer": "Interpolation", "solution": "18 is inside the observed range.", "topic": "dat"}, {"id": "VM-Y10-DAT-010", "skill": "Strength", "difficulty": "medium", "question": "Two scatter plots have positive trends. One has points tightly clustered around a line and the other is widely scattered. Which shows stronger linear association?", "answer": "The tightly clustered plot.", "solution": "Less scatter around the line indicates stronger linear association.", "topic": "dat"}, {"id": "VM-Y10-DAT-011", "skill": "Confounding", "difficulty": "hard", "question": "Schools with more library books tend to have more students achieving high marks. Suggest a possible confounding variable.", "answer": "School size, for example.", "solution": "Larger schools may have more books and more high-achieving students simply because they have more students.", "topic": "dat"}, {"id": "VM-Y10-DAT-012", "skill": "Residual", "difficulty": "medium", "question": "A fitted line predicts 18 for a point whose observed value is 21. Find observed minus predicted.", "answer": "3", "solution": "21 − 18 = 3.", "topic": "dat"}, {"id": "VM-Y10-DAT-013", "skill": "Data design", "difficulty": "medium", "question": "Design a paired-data investigation of whether study time is associated with quiz score.", "answer": "Record study time and quiz score for each participant.", "solution": "Keep each participant’s measurements paired and use comparable quiz conditions.", "topic": "dat"}, {"id": "VM-Y10-DAT-014", "skill": "Graph choice", "difficulty": "easy", "question": "Which graph is most appropriate for investigating association between rainfall and daily temperature measured on the same days?", "answer": "Scatter plot", "solution": "Each day supplies a pair of numerical measurements.", "topic": "dat"}, {"id": "VM-Y10-DAT-015", "skill": "Nonlinear pattern", "difficulty": "hard", "question": "A scatter plot forms a clear U shape. Does the absence of a strong straight-line trend mean there is no relationship?", "answer": "No", "solution": "A nonlinear association may be strong even when a straight line fits poorly.", "topic": "dat"}, {"id": "VM-Y10-DAT-016", "skill": "Model interpretation", "difficulty": "medium", "question": "A fitted model for weekly cost is C = 12 + 3n, where n is the number of visits. Interpret the slope.", "answer": "Predicted cost increases by $3 per additional visit.", "solution": "The coefficient of n is the predicted rate of change.", "topic": "dat"}, {"id": "VM-Y10-DAT-017", "skill": "Scatter construction", "difficulty": "medium", "question": "Plot (1,2), (2,5), (3,4), (4,8), (5,9). Describe direction and whether association is perfect.", "answer": "Positive, not perfect", "solution": "Outputs generally rise but the points are not collinear.", "topic": "dat"}, {"id": "VM-Y10-DAT-018", "skill": "Outlier reasoning", "difficulty": "hard", "question": "A scatter plot of age and height for children includes one adult. Why might analysing the adult separately be sensible?", "answer": "The adult may belong to a different population", "solution": "Growth patterns differ by life stage; the point may distort the fitted trend.", "topic": "dat"}, {"id": "VM-Y10-DAT-019", "skill": "Model comparison", "difficulty": "hard", "question": "At x = 4, an observed value is 11. Models y = 2x+2 and y = 3x predict different values. Which is closer at this point?", "answer": "Neither; both equally close", "solution": "Predictions 10 and 12 each differ by 1.", "topic": "dat"}, {"id": "VM-Y10-DAT-020", "skill": "Data collection", "difficulty": "hard", "question": "Collect paired screen-time and sleep-duration data from at least five consenting volunteers for the same day. State units, plot the pairs and explain one way to improve consistency.", "answer": "Answers vary; paired numerical observations, labelled scatter plot and consistent measurement method.", "solution": "Record each person’s screen time and sleep in hours for the same 24-hour period. Plot one point per person with labelled axes. Use the same measurement method and time window for everyone; do not record names.", "topic": "dat"}, {"id": "VM-Y10-DAT-021", "skill": "Causation reasoning", "difficulty": "hard", "question": "A school finds students who attend tutoring have lower average marks. Does this prove tutoring harms marks?", "answer": "No", "solution": "Students needing help may be more likely to attend; prior achievement is a possible confounder.", "topic": "dat"}, {"id": "VM-Y10-DAT-022", "skill": "Prediction limits", "difficulty": "hard", "question": "A fitted model predicts a negative travel time for a short journey. What does this suggest?", "answer": "The model is unsuitable for that input", "solution": "Travel time cannot be negative; a fitted relationship has practical domain limits.", "topic": "dat"}, {"id": "VM-Y10-DAT-023", "skill": "Variable selection", "difficulty": "easy", "question": "To investigate whether shoe size relates to height, should you collect one or two numerical measurements per person?", "answer": "Two", "solution": "Paired shoe size and height are required.", "topic": "dat"}, {"id": "VM-Y10-DAT-024", "skill": "Association direction", "difficulty": "easy", "question": "A scatter plot generally falls from left to right. Describe its association.", "answer": "Negative", "solution": "Larger x-values tend to accompany smaller y-values.", "topic": "dat"}, {"id": "VM-Y10-DAT-025", "skill": "Best fit by eye", "difficulty": "medium", "question": "Plot (1,3), (2,5), (3,7), (4,8), (5,11). Sketch a reasonable line of best fit and estimate y at x = 3.5.", "answer": "Approximately 8", "solution": "A reasonable visual line is y ≈ 2x + 1, giving 8; other close estimates are acceptable.", "topic": "dat"}, {"id": "VM-Y10-DAT-026", "skill": "Causal investigation", "difficulty": "hard", "question": "Students who attend tutoring have lower average marks than those who do not. Explain why this does not establish that tutoring lowers marks.", "answer": "Selection bias is possible", "solution": "Students already struggling may be more likely to seek tutoring.", "topic": "dat"}, {"id": "VM-Y10-DAT-027", "skill": "Prediction range", "difficulty": "medium", "question": "A scatter plot uses ages 12–16. Is predicting at age 14 interpolation or extrapolation?", "answer": "Interpolation", "solution": "14 lies within the observed range.", "topic": "dat"}, {"id": "VM-Y10-DAT-028", "skill": "Data quality", "difficulty": "challenge", "question": "A survey records height in centimetres for most students but metres for five. What should happen before fitting a line against arm span?", "answer": "Convert to consistent units", "solution": "Mixed units distort the numerical scale and may create artificial outliers.", "topic": "dat"}, {"id": "VM-Y10-DAT-029", "skill": "Variables", "difficulty": "easy", "question": "A scatter plot compares hours of sleep with reaction time. Name the two measured variables.", "answer": "Hours of sleep and reaction time", "solution": "Each plotted point records one value of each variable.", "topic": "dat"}, {"id": "VM-Y10-DAT-030", "skill": "Association", "difficulty": "easy", "question": "As outdoor temperature increases, heater use generally decreases. Describe the direction of association.", "answer": "Negative", "solution": "One variable tends to decrease as the other increases.", "topic": "dat"}, {"id": "VM-Y10-DAT-031", "skill": "Sampling critique", "difficulty": "challenge", "question": "A school surveys only students attending lunchtime sport to study the relationship between exercise and sleep across the school. Identify a sampling problem.", "answer": "Selection bias", "solution": "Students attending sport may differ systematically from other students in exercise habits.", "topic": "dat"}, {"id": "VM-Y10-DAT-032", "skill": "Prediction critique", "difficulty": "challenge", "question": "A trend line based on ages 12–16 predicts a value at age 40. Explain why the prediction is unreliable even if the observed association is strong.", "answer": "It is extrapolation far outside the observed range.", "solution": "The relationship may change beyond the sampled ages.", "topic": "dat"}, {"id": "VM-Y10-DAT-033", "skill": "Scatter coordinates", "difficulty": "easy", "question": "A scatter plot uses hours studied on the horizontal axis and marks on the vertical axis. Interpret the point (3, 72).", "answer": "A student studied 3 hours and scored 72 marks.", "solution": "Read the explanatory variable first and the response second.", "topic": "dat"}, {"id": "VM-Y10-DAT-034", "skill": "Scatter comparison", "difficulty": "medium", "question": "Plot (1,2), (2,4), (3,6), (4,8) and (1,8), (2,6), (3,4), (4,2) as separate datasets. Compare their associations.", "answer": "First perfect positive; second perfect negative.", "solution": "The first lies on y = 2x; the second on y = 10 − 2x.", "topic": "dat"}, {"id": "VM-Y10-DAT-035", "skill": "Prediction residual", "difficulty": "hard", "question": "A line of best fit predicts a 65 mark score for a student who studied 4 hours. The actual score is 58. Is the point above or below the line, and by how much?", "answer": "7 marks below", "solution": "Actual − predicted = 58 − 65 = −7.", "topic": "dat"}, {"id": "VM-Y10-DAT-036", "skill": "Grouped scatter", "difficulty": "challenge", "question": "A scatter plot combining two year groups shows a positive association between height and test score. Within each year group there is no clear association. Explain why the combined pattern may mislead.", "answer": "Year group may confound the association.", "solution": "Older students may be taller and score higher on the test; the combined trend need not hold within either group or imply causation.", "topic": "dat"}, {"id": "VM-Y10-DAT-037", "skill": "Prediction decision", "difficulty": "medium", "question": "A line of best fit for study time x hours and score y is y = 5x + 45. Predict the score for 6 hours and explain why it is not guaranteed.", "answer": "75; individual variation", "solution": "Substitute x = 6 to get 75. A trend line estimates typical values, not exact individual outcomes.", "topic": "dat"}, {"id": "VM-Y10-DAT-038", "skill": "Data collection bias", "difficulty": "hard", "question": "A school surveys only students attending a lunchtime sports club to investigate exercise and sleep across the whole school. Identify a likely sampling problem and suggest a fix.", "answer": "Selection bias; sample across the school", "solution": "Club members may exercise more than other students. Randomly sample students from multiple year groups, including non-members.", "topic": "dat"}, {"id": "VM-Y10-DAT-039", "skill": "Influential observation", "difficulty": "hard", "question": "A scatter plot contains (1,2), (2,4), (3,6), (4,8) and (10,1). Explain how the last point affects interpretation.", "answer": "It weakens the overall positive association", "solution": "The first four lie on y = 2x; the last has a large x but low y and contradicts that trend. Investigate it before excluding it.", "topic": "dat"}, {"id": "VM-Y10-DAT-040", "skill": "Comparing predictions", "difficulty": "challenge", "question": "Two fitted models predict 40 and 44 at x = 5, and 60 and 56 at x = 9. Actual values are 42 and 55. Which model has smaller total absolute prediction error?", "answer": "Second model", "solution": "First errors: 2 + 5 = 7. Second errors: 2 + 1 = 3.", "topic": "dat"}, {"id": "VM-Y10-DAT-041", "skill": "Paired observations", "difficulty": "easy", "question": "A student records each plant’s height and number of leaves. How many paired observations are collected from 12 plants?", "answer": "12", "solution": "Each plant supplies one pair of measurements.", "topic": "dat"}, {"id": "VM-Y10-DAT-042", "skill": "Association absence", "difficulty": "easy", "question": "A scatter plot shows points spread without any clear upward or downward trend. What association is suggested?", "answer": "No clear association", "solution": "There is no visible systematic trend between the variables.", "topic": "dat"}, {"id": "VM-Y10-DAT-043", "skill": "Prediction comparison", "difficulty": "medium", "question": "A model predicts 18, 22 and 26 for three observations whose actual values are 20, 21 and 30. Which prediction has the largest absolute error?", "answer": "The third", "solution": "Absolute errors are 2, 1 and 4.", "topic": "dat"}, {"id": "VM-Y10-DAT-044", "skill": "Axis selection", "difficulty": "medium", "question": "A class investigates whether hours of sunlight help predict plant growth. Which variable should usually be on the horizontal axis, and why?", "answer": "Hours of sunlight", "solution": "It is the explanatory variable used to predict growth.", "topic": "dat"}, {"id": "VM-Y10-DAT-045", "skill": "Variable identification", "difficulty": "easy", "question": "A study records daily rainfall and umbrella sales. Which variable would usually be used to predict sales?", "answer": "Daily rainfall", "solution": "Rainfall is the explanatory variable in this proposed prediction.", "topic": "dat"}, {"id": "VM-Y10-DAT-046", "skill": "Residual interpretation", "difficulty": "medium", "question": "A model predicts 48 sales but the actual number is 41. Find the residual (actual minus predicted).", "answer": "−7", "solution": "41 − 48 = −7.", "topic": "dat"}, {"id": "VM-Y10-DAT-047", "skill": "Confounding", "difficulty": "hard", "question": "A school finds students who attend revision sessions have higher marks. Give a possible alternative explanation besides the sessions causing improvement.", "answer": "Prior achievement or motivation may influence both.", "solution": "An observational association alone cannot isolate the effect of attendance.", "topic": "dat"}, {"id": "VM-Y10-DAT-048", "skill": "Investigation design", "difficulty": "challenge", "question": "A researcher measures exercise and sleep only among members of a competitive running club. Explain why the relationship may not generalise to all teenagers and suggest an improvement.", "answer": "Selection bias; sample a broader group of teenagers.", "solution": "Club members may differ in activity and routines; sample across schools and activity levels.", "topic": "dat"}, {"id": "VM-Y10-DAT-049", "skill": "Paired data", "difficulty": "easy", "question": "A class records each student's height and shoe length. Why must both measurements stay paired when sorting the data?", "answer": "To preserve the relationship for each student", "solution": "Sorting columns independently creates artificial pairs and can distort association.", "topic": "dat"}, {"id": "VM-Y10-DAT-050", "skill": "Axis reversal", "difficulty": "medium", "question": "A scatter plot shows a positive association. If the two variables exchange axes, does the association become negative?", "answer": "No", "solution": "Swapping axes reflects the plot in y = x; increasing pairs still show positive association.", "topic": "dat"}, {"id": "VM-Y10-DAT-051", "skill": "Aggregation", "difficulty": "hard", "question": "Two classes have different average test scores. Explain why a scatter plot of just the two class averages cannot establish the strength of the relationship between study time and score among individual students.", "answer": "Individual association is unknown", "solution": "Averages hide within-class variation and pairing; individual data are needed.", "topic": "dat"}, {"id": "VM-Y10-DAT-052", "skill": "Prediction audit", "difficulty": "challenge", "question": "Two models predict scores for three students. Actual scores are 60, 70, 80. Model A predicts 55, 70, 85; B predicts 62, 72, 82. Which has lower mean absolute prediction error?", "answer": "Model B", "solution": "A: (5 + 0 + 5) ÷ 3 = 10/3. B: (2 + 2 + 2) ÷ 3 = 2.", "topic": "dat"}, {"id": "VM-Y10-DAT-053", "skill": "Paired record", "difficulty": "easy", "question": "A table records a runner’s time and distance. One time is missing. Can that row supply a complete point on a time-distance scatter plot?", "answer": "No", "solution": "Both coordinates must be known for a paired observation.", "topic": "dat"}, {"id": "VM-Y10-DAT-054", "skill": "Prediction from line", "difficulty": "medium", "question": "A fitted line predicts travel time t = 5 + 3d minutes for distance d kilometres. Find the predicted time for 7 km and interpret the intercept.", "answer": "26 minutes; 5 minutes at zero distance.", "solution": "Substitute d=7. The intercept is the modelled fixed time, not necessarily an observed journey.", "topic": "dat"}, {"id": "VM-Y10-DAT-055", "skill": "Range restriction", "difficulty": "hard", "question": "A study finds little association between age and height among 15-year-olds. Does this establish that age and height are unrelated among children aged 2–15?", "answer": "No.", "solution": "The sample has a restricted age range and cannot establish the relationship across a much wider range.", "topic": "dat"}, {"id": "VM-Y10-DAT-056", "skill": "Same means different association", "difficulty": "challenge", "question": "Construct two sets of three paired observations with identical x-values and identical y-values but opposite directions of association.", "answer": "(1,2),(2,4),(3,6) versus (1,6),(2,4),(3,2).", "solution": "Both sets have the same marginal values, but the first increases and the second decreases.", "topic": "dat"}, {"id": "VM-Y10-DAT-057", "skill": "Paired observation", "difficulty": "easy", "question": "A scatter plot of study time and test score has a point (3,78). Interpret it if time is measured in hours and score in percent.", "answer": "One observation has 3 hours of study and a score of 78%.", "solution": "Read the horizontal and vertical coordinates together.", "topic": "dat"}, {"id": "VM-Y10-DAT-058", "skill": "Prediction comparison", "difficulty": "medium", "question": "A fitted line predicts 42 and 58 for inputs 2 and 6 respectively. Assuming the line is straight, predict the output at input 4.", "answer": "50", "solution": "Input 4 is halfway between 2 and 6; the predicted output is halfway between 42 and 58.", "topic": "dat"}, {"id": "VM-Y10-DAT-059", "skill": "Association under unit conversion", "difficulty": "hard", "question": "A scatter plot shows a negative association between temperature in Celsius and heating use. Would converting temperature to Fahrenheit reverse the association? Explain.", "answer": "No", "solution": "F = 1.8C + 32 is increasing, so the order of temperature values is preserved.", "topic": "dat"}, {"id": "VM-Y10-DAT-060", "skill": "Hidden grouping", "difficulty": "challenge", "question": "In each of two classes, students who practise more tend to score higher. The class with less average practice has much higher average scores. Explain why the combined scatter plot may be misleading.", "answer": "The combined association may differ from the within-class associations.", "solution": "Class membership may be associated with both practice and scores; compare groups separately before drawing conclusions.", "topic": "dat"}, {"id": "VM-Y10-DAT-061", "skill": "Scatter plot construction", "difficulty": "easy", "question": "Plot the paired observations (1, 7), (2, 5), (3, 4), (4, 2). Describe the direction of association.", "answer": "Negative association", "solution": "The plotted vertical values decrease as horizontal values increase.", "topic": "dat"}, {"id": "VM-Y10-DAT-062", "skill": "Prediction reliability", "difficulty": "medium", "question": "A line of best fit predicts 42 at x = 10. The observed value is 38. Find observed minus predicted and explain its sign.", "answer": "−4; the model overpredicts", "solution": "38 − 42 = −4, so the observed value is four units below the prediction.", "topic": "dat"}, {"id": "VM-Y10-DAT-063", "skill": "Measurement precision", "difficulty": "hard", "question": "A scatter plot uses study times rounded to the nearest hour. Explain why several points may share the same horizontal coordinate even if actual study times differ.", "answer": "Rounding groups distinct measurements", "solution": "For example, 2.1 and 2.4 hours both round to 2 hours. The plot loses some horizontal detail.", "topic": "dat"}, {"id": "VM-Y10-DAT-064", "skill": "Investigation reliability", "difficulty": "challenge", "question": "A school compares average sleep and test marks using only students who volunteer for a study. Suggest a change to recruitment and explain why it improves the investigation.", "answer": "Randomly select students from the target population.", "solution": "Volunteers may differ systematically from non-volunteers. Random selection reduces selection bias, though non-response can still matter.", "topic": "dat"}, {"id": "VM-Y10-DAT-065", "skill": "Paired measurement", "difficulty": "easy", "question": "A scatter plot compares each pupil’s height with their arm span. What does one point represent?", "answer": "One pupil’s paired measurements.", "solution": "Each point records both variables for the same individual.", "topic": "dat"}, {"id": "VM-Y10-DAT-066", "skill": "Association transformation", "difficulty": "medium", "question": "A positive association is plotted with distance in metres. If distance is converted to kilometres, does the direction change?", "answer": "No", "solution": "Dividing a variable by a positive constant preserves its order.", "topic": "dat"}, {"id": "VM-Y10-DAT-067", "skill": "Prediction residual comparison", "difficulty": "hard", "question": "For x = 8, model A predicts 19 and model B predicts 23. The observed value is 22. Which model has the smaller absolute prediction error for this observation?", "answer": "Model B.", "solution": "Absolute errors are |22−19| = 3 and |22−23| = 1.", "topic": "dat"}, {"id": "VM-Y10-DAT-068", "skill": "Study design", "difficulty": "challenge", "question": "A school compares exercise time and test scores but records exercise time only on sports day. Explain one limitation and propose a better measurement.", "answer": "Sports day may not represent usual exercise; record typical daily exercise over several days.", "solution": "An unusual day can distort the explanatory variable. Repeated measurements over ordinary days improve representativeness.", "topic": "dat"}, {"id": "VM-Y10-DAT-069", "skill": "Paired variables", "difficulty": "easy", "question": "A survey has two students with the same height but different arm spans. Why should both records be kept?", "answer": "They represent distinct paired observations.", "solution": "Equal values of one variable do not imply equal values of the other.", "topic": "dat"}, {"id": "VM-Y10-DAT-070", "skill": "Prediction interval", "difficulty": "medium", "question": "A trend line predicts 42 marks for a student who studies 3 hours. The student actually scores 49. Find the actual-minus-predicted difference.", "answer": "7 marks", "solution": "49 − 42 = 7.", "topic": "dat"}, {"id": "VM-Y10-DAT-071", "skill": "Association critique", "difficulty": "hard", "question": "A scatter plot of daily ice-cream sales and swimming attendance shows positive association. Suggest a plausible third variable and explain its effect.", "answer": "Temperature", "solution": "Warmer weather may increase both sales and swimming attendance; association does not establish causation.", "topic": "dat"}, {"id": "VM-Y10-DAT-072", "skill": "Aggregation", "difficulty": "challenge", "question": "A class records study time and test marks for each student, then replaces all pairs with one pair of class averages. Can the original association be determined from that pair? Explain.", "answer": "No", "solution": "One averaged point contains no information about how individual paired observations vary together.", "topic": "dat"}, {"id": "VM-Y10-DAT-073", "skill": "Association direction", "difficulty": "easy", "question": "A scatter plot tends to fall from left to right. What direction of association does this suggest?", "answer": "Negative", "solution": "Larger x values tend to accompany smaller y values.", "topic": "dat"}, {"id": "VM-Y10-DAT-074", "skill": "Interpolation", "difficulty": "medium", "question": "Observed temperatures range from 12°C to 28°C. A trend line predicts sales at 20°C and 35°C. Which prediction is interpolation?", "answer": "20°C", "solution": "20 lies inside the observed range; 35 lies outside it.", "topic": "dat"}, {"id": "VM-Y10-DAT-075", "skill": "Paired observation", "difficulty": "medium", "question": "A scatter plot uses hours of sleep on the horizontal axis and reaction time in milliseconds on the vertical axis. Interpret the point (7, 240).", "answer": "7 hours of sleep and 240 ms reaction time", "solution": "Read the coordinates using the axis labels.", "topic": "dat"}, {"id": "VM-Y10-DAT-076", "skill": "Data correction", "difficulty": "hard", "question": "A scatter plot contains (2, 12), (4, 16), (6, 20), (8, 24). The final y-value was entered as 42 instead of 24. Explain how the error affects the apparent linear relationship.", "answer": "It introduces an outlier above the original trend and may steepen a fitted line.", "solution": "The correct points satisfy y = 2x + 8. At x = 8 the incorrect value is 18 above the line.", "topic": "dat"}, {"id": "VM-Y10-DAT-077", "skill": "Paired observation", "difficulty": "easy", "question": "A scatter plot uses (hours studied, score). Interpret the point (3, 72).", "answer": "A student studied 3 hours and scored 72.", "solution": "The coordinates refer to the same observation.", "topic": "dat"}, {"id": "VM-Y10-DAT-078", "skill": "Association strength", "difficulty": "medium", "question": "Two scatter plots both slope upwards. In plot A points cluster closely around a line; in B they are widely scattered. Which shows stronger linear association?", "answer": "Plot A", "solution": "Closer clustering around a line indicates stronger linear association.", "topic": "dat"}, {"id": "VM-Y10-DAT-079", "skill": "Prediction interpretation", "difficulty": "medium", "question": "A fitted line predicts 52 sales on a day when actual sales are 47. By how much did it overpredict?", "answer": "5 sales", "solution": "52 − 47 = 5.", "topic": "dat"}, {"id": "VM-Y10-DAT-080", "skill": "Data collection", "difficulty": "hard", "question": "A student measures exercise time and resting heart rate only among competitive swimmers. Explain why conclusions may not generalise to all teenagers.", "answer": "The sample is restricted and may not represent all teenagers.", "solution": "Training habits and fitness differ; sample teenagers from a wider range of activity levels.", "topic": "dat"}, {"id": "VM-Y10-DAT-081", "skill": "Paired data", "difficulty": "easy", "question": "A plant study records height and leaf count. Which variable belongs on the horizontal axis if height is used to predict leaf count?", "answer": "Height", "solution": "The explanatory variable is conventionally on the horizontal axis.", "topic": "dat"}, {"id": "VM-Y10-DAT-082", "skill": "Prediction residual", "difficulty": "medium", "question": "A trend line predicts 68 marks for a student who actually scores 75. By how many marks does the prediction underestimate the score?", "answer": "7 marks", "solution": "75 − 68 = 7.", "topic": "dat"}, {"id": "VM-Y10-DAT-083", "skill": "Extrapolation", "difficulty": "medium", "question": "A trend line is based on observations of children aged 8 to 12. Explain why using it to predict the height of a 30-year-old is unreliable.", "answer": "It extrapolates beyond the observed ages.", "solution": "The relationship may change outside the data range, particularly after growth stops.", "topic": "dat"}, {"id": "VM-Y10-DAT-084", "skill": "Association reversal", "difficulty": "hard", "question": "Two factories each show increasing output with experience, but the newer factory has higher output at every experience level. Why might pooling the data hide the trend?", "answer": "Factory membership may confound the relationship.", "solution": "Different group baselines and experience distributions can mask within-group trends.", "topic": "dat"}, {"skill": "Paired observations", "difficulty": "easy", "question": "A researcher records each runner’s training hours and race time. What makes these data bivariate?", "answer": "Two variables are recorded for each runner", "solution": "Each observation pairs training hours with race time.", "id": "VM-Y10-DAT-085", "topic": "dat"}, {"skill": "Association direction", "difficulty": "medium", "question": "A scatter plot of outdoor temperature against heater usage slopes downwards. Describe the association without claiming causation.", "answer": "Negative association", "solution": "Higher temperatures tend to accompany lower heater usage.", "id": "VM-Y10-DAT-086", "topic": "dat"}, {"skill": "Prediction limitation", "difficulty": "hard", "question": "A model for fuel use was fitted to speeds from 40 to 80 km/h. Explain why a prediction at 150 km/h is questionable.", "answer": "It extrapolates beyond the observed range; the relationship may change.", "solution": "The fitted trend is supported only by the observed speed range.", "id": "VM-Y10-DAT-087", "topic": "dat"}, {"skill": "Influential point", "difficulty": "hard", "question": "Four paired observations are (1,2), (2,4), (3,6), (4,8). A fifth observation (5,0) is added. Explain how it changes the apparent association.", "answer": "It weakens the positive linear association", "solution": "The first four lie on y = 2x; the fifth is far below the trend at the largest x-value.", "id": "VM-Y10-DAT-088", "topic": "dat"}, {"id": "VM-Y10-DAT-089", "skill": "Variable pairing", "difficulty": "easy", "question": "A paired dataset has 12 complete rows. How many points can be plotted, counting coincident points separately?", "answer": "12", "solution": "Each complete row contributes one ordered pair.", "topic": "dat"}, {"id": "VM-Y10-DAT-090", "skill": "Scatter plot construction", "difficulty": "medium", "question": "Plot (2,9), (4,7), (6,5), (8,3). Describe the association and predict y at x = 5.", "answer": "Perfect negative linear association; 6", "solution": "The points lie on y = 11 − x; substitute 5.", "topic": "dat"}, {"id": "VM-Y10-DAT-091", "skill": "Grouped association", "difficulty": "hard", "question": "Two groups have paired values A: (1,8),(2,9),(3,10) and B: (5,2),(6,3),(7,4). Describe the within-group and combined trends.", "answer": "Positive within each group; negative overall", "solution": "Each group rises as x increases, but group B has higher x and lower y than group A, reversing the overall pattern.", "topic": "dat"}, {"id": "VM-Y10-DAT-092", "skill": "Prediction comparison", "difficulty": "hard", "question": "Two models predict 14 and 18 for a measurement whose observed value is 15. A second measurement is 20, with predictions 24 and 19 respectively. Which model has smaller total absolute error?", "answer": "Second model", "solution": "First: |14−15| + |24−20| = 5. Second: |18−15| + |19−20| = 4.", "topic": "dat"}, {"id": "VM-Y10-DAT-093", "skill": "Variable type", "difficulty": "easy", "question": "A survey records the number of pets in each household. Is this discrete or continuous numerical data?", "answer": "Discrete", "solution": "Pets are counted in whole numbers.", "topic": "dat"}, {"id": "VM-Y10-DAT-094", "skill": "Range interpretation", "difficulty": "medium", "question": "Two classes have the same median score but ranges 12 and 28. Which has the greater spread as measured by range?", "answer": "The class with range 28.", "solution": "Range measures maximum minus minimum.", "topic": "dat"}, {"id": "VM-Y10-DAT-095", "skill": "Missing frequency", "difficulty": "medium", "question": "A frequency table has counts 7, 12, x and 9, with 40 observations overall. Find x.", "answer": "12", "solution": "40 − 7 − 12 − 9 = 12.", "topic": "dat"}, {"id": "VM-Y10-DAT-096", "skill": "Scatterplot reasoning", "difficulty": "medium", "question": "A scatterplot shows a strong negative association between outdoor temperature and heating use. Does this mean every warmer day has lower heating use?", "answer": "No", "solution": "Association describes a general trend, not an exception-free rule.", "topic": "dat"}, {"id": "VM-Y10-DAT-097", "skill": "Combined mean", "difficulty": "hard", "question": "Group A has 12 students with mean 70. Group B has 18 students with mean 80. Find the combined mean.", "answer": "76", "solution": " (12 × 70 + 18 × 80) ÷ 30 = 76.", "topic": "dat"}, {"id": "VM-Y10-DAT-098", "skill": "Median robustness", "difficulty": "hard", "question": "The ordered values are 2, 4, 6, 8, 10, 12, 14. The largest value is replaced by 100. Compare the mean and median before and after.", "answer": "Median stays 8; mean rises from 8 to 142/7.", "solution": "Original sum 56; new sum 142. The fourth value remains 8.", "topic": "dat"}, {"id": "VM-Y10-DAT-099", "skill": "Variable type", "difficulty": "easy", "question": "Classify the number of books borrowed in a week as discrete or continuous.", "answer": "Discrete", "solution": "It is a count of whole books.", "topic": "dat"}, {"id": "VM-Y10-DAT-100", "skill": "Association direction", "difficulty": "easy", "question": "As outdoor temperature rises, heater use generally falls. Describe the association.", "answer": "Negative", "solution": "One variable tends to decrease as the other increases.", "topic": "dat"}, {"id": "VM-Y10-DAT-101", "skill": "Residual interpretation", "difficulty": "medium", "question": "A trend line predicts 18 minutes for a journey that actually takes 23 minutes. Calculate actual minus predicted and interpret.", "answer": "5 minutes; underprediction", "solution": "23 − 18 = 5, so the prediction is too low.", "topic": "dat"}, {"id": "VM-Y10-DAT-102", "skill": "Comparing spread", "difficulty": "medium", "question": "Group A has quartiles 12 and 20; group B has quartiles 9 and 23. Which has greater interquartile spread?", "answer": "Group B", "solution": "IQRs are 8 and 14 respectively.", "topic": "dat"}, {"id": "VM-Y10-DAT-103", "skill": "Confounding", "difficulty": "hard", "question": "A positive association is observed between umbrella sales and traffic delays. Explain a plausible confounder.", "answer": "Rainfall", "solution": "Rain can increase umbrella purchases and slow traffic, without purchases causing delays.", "topic": "dat"}, {"id": "VM-Y10-DAT-104", "skill": "Sampling design", "difficulty": "hard", "question": "A school surveys only students attending an optional lunchtime maths club about homework satisfaction. Explain a likely bias and propose an improvement.", "answer": "Selection bias; randomly sample across year groups", "solution": "Club attendees may differ in maths interest; a broader random sample reduces selection bias.", "topic": "dat"}, {"id": "VM-Y10-DAT-105", "skill": "Variable type", "difficulty": "easy", "question": "Classify the mass of a borrowed book as discrete or continuous.", "answer": "Continuous", "solution": "Mass can take any value within a measurement interval.", "topic": "dat"}, {"id": "VM-Y10-DAT-106", "skill": "Association", "difficulty": "easy", "question": "A scatterplot shows no obvious upward or downward pattern. Describe its apparent association.", "answer": "No clear association", "solution": "Neither variable consistently rises or falls with the other.", "topic": "dat"}, {"id": "VM-Y10-DAT-107", "skill": "Median robustness", "difficulty": "medium", "question": "Five ordered values are 3, 5, 7, 9, 11. The largest is replaced by 100. State the new median and explain.", "answer": "7", "solution": "The middle observation remains 7.", "topic": "dat"}, {"id": "VM-Y10-DAT-108", "skill": "Prediction range", "difficulty": "medium", "question": "A trend line is fitted to data for ages 12 to 17. Is predicting at age 25 interpolation or extrapolation?", "answer": "Extrapolation", "solution": "25 is outside the observed range.", "topic": "dat"}, {"id": "VM-Y10-DAT-109", "skill": "Grouped comparison", "difficulty": "hard", "question": "Class A has 10 students with mean score 80; class B has 30 with mean 60. Explain why averaging the two means gives the wrong combined mean, and calculate it.", "answer": "65", "solution": "The groups differ in size; weighted mean = (800 + 1800)/40 = 65.", "topic": "dat"}, {"id": "VM-Y10-DAT-110", "skill": "Association interpretation", "difficulty": "hard", "question": "A scatterplot of study time and marks has a positive trend except for one student with high study time and low marks. Does that point disprove the trend? Explain.", "answer": "No", "solution": "An association describes the overall pattern, not a rule for every observation; investigate the unusual point without automatically deleting it.", "topic": "dat"}, {"id": "VM-Y10-DAT-111", "skill": "Variable type", "difficulty": "easy", "question": "Classify the number of absent students in a class as discrete or continuous, and explain.", "answer": "Discrete", "solution": "It is a count taking whole-number values.", "topic": "dat"}, {"id": "VM-Y10-DAT-112", "skill": "Association", "difficulty": "easy", "question": "A scatter plot has points spread without an evident upward or downward trend. Describe the association.", "answer": "No apparent association", "solution": "There is no clear directional pattern.", "topic": "dat"}, {"id": "VM-Y10-DAT-113", "skill": "Prediction error", "difficulty": "medium", "question": "A model predicts 68 marks for a student who scores 74. Find actual minus predicted.", "answer": "6 marks", "solution": "74 − 68 = 6.", "topic": "dat"}, {"id": "VM-Y10-DAT-114", "skill": "Combined mean", "difficulty": "medium", "question": "A group of 12 students averages 15 points and another 8 averages 20 points. Find the combined mean.", "answer": "17 points", "solution": "(12 × 15 + 8 × 20) ÷ 20 = 17.", "topic": "dat"}, {"id": "VM-Y10-DAT-115", "skill": "Confounding", "difficulty": "hard", "question": "Ice cream sales and sunscreen sales rise together. Explain why this does not establish that ice cream purchases cause sunscreen purchases.", "answer": "A common factor may explain both", "solution": "Hot or sunny weather can increase both sales; association alone does not establish causation.", "topic": "dat"}, {"id": "VM-Y10-DAT-116", "skill": "Outlier influence", "difficulty": "hard", "question": "Five values have mean 18. A sixth value of 42 is added. Find the new mean and explain its change.", "answer": "22; increases by 4", "solution": "Original sum 90; new sum 132; 132 ÷ 6 = 22. The added value exceeds the old mean.", "topic": "dat"}, {"id": "VM-Y10-DAT-117", "skill": "Association direction", "difficulty": "easy", "question": "As the number of pages read increases, the number of unread pages in the same book decreases. State the direction of association.", "answer": "Negative", "solution": "One variable decreases as the other increases.", "topic": "dat"}, {"id": "VM-Y10-DAT-118", "skill": "Outlier effect", "difficulty": "medium", "question": "Five measurements are 8, 9, 10, 11 and 42. Find the mean with and without the largest measurement.", "answer": "16 and 9.5", "solution": "80 ÷ 5 = 16; 38 ÷ 4 = 9.5.", "topic": "dat"}, {"id": "VM-Y10-DAT-119", "skill": "Prediction residual", "difficulty": "medium", "question": "A model predicts 74 points and the observed score is 68. Calculate observed minus predicted.", "answer": "−6", "solution": "68 − 74 = −6.", "topic": "dat"}, {"id": "VM-Y10-DAT-120", "skill": "Confounding variable", "difficulty": "hard", "question": "A survey finds students who own more textbooks tend to have higher marks. Explain why buying textbooks cannot be concluded to cause higher marks.", "answer": "Association does not establish causation.", "solution": "Study habits or access to resources may influence both variables; the survey does not isolate the effect of textbooks.", "topic": "dat"}, {"id": "VM-Y10-FIN-001", "skill": "Repeated interest", "difficulty": "easy", "question": "A $500 deposit earns 4% annually. Find the balance after two years by calculating each year separately.", "answer": "$540.80", "solution": "Year 1: 500 + 20 = 520. Year 2: 520 + 20.80 = 540.80.", "topic": "fin"}, {"id": "VM-Y10-FIN-002", "skill": "Compound growth", "difficulty": "medium", "question": "An account starts with $2400 and earns 3% annually for 5 years. Find the interest earned.", "answer": "$382.26", "solution": "Interest = 2400(1.03)^5 − 2400 = 382.26 to cents.", "topic": "fin"}, {"id": "VM-Y10-FIN-003", "skill": "Comparison", "difficulty": "medium", "question": "Compare simple and compound interest on $1000 at 10% annually over three years.", "answer": "$31 more with compound interest", "solution": "Simple balance = 1300; compound balance = 1000(1.1)^3 = 1331.", "topic": "fin"}, {"id": "VM-Y10-FIN-004", "skill": "Depreciation", "difficulty": "medium", "question": "A $900 bicycle loses 20% of its value annually. Find its value after three years.", "answer": "$460.80", "solution": "Retain 80% each year: 900(0.8)^3 = 460.80.", "topic": "fin"}, {"id": "VM-Y10-FIN-005", "skill": "Reverse reasoning", "difficulty": "hard", "question": "A machine is worth $8100 after two annual depreciations of 10%. Find its initial value.", "answer": "$10000", "solution": "Initial value = 8100 ÷ 0.9² = 10000.", "topic": "fin"}, {"id": "VM-Y10-FIN-006", "skill": "Error analysis", "difficulty": "hard", "question": "A student says two annual increases of 5% give exactly 10% growth. Explain the error.", "answer": "Growth is 10.25%.", "solution": "The second increase applies to the increased balance: 1.05² = 1.1025.", "topic": "fin"}, {"id": "VM-Y10-FIN-007", "skill": "Multiplier", "difficulty": "easy", "question": "Which annual multiplier represents a loss of 7.5%?", "answer": "0.925", "solution": "Subtract 0.075 from 1.", "topic": "fin"}, {"id": "VM-Y10-FIN-008", "skill": "Frequency", "difficulty": "medium", "question": "An account pays 6% p.a. compounded monthly. What rate and number of periods apply over 18 months?", "answer": "0.5% per month; 18 periods", "solution": "Divide 6% by 12; count 18 months.", "topic": "fin"}, {"id": "VM-Y10-FIN-009", "skill": "Threshold", "difficulty": "hard", "question": "A $1000 investment grows by 20% annually. In which year does it first exceed $1700?", "answer": "Year 3", "solution": "After two years it is $1440; after three it is $1728.", "topic": "fin"}, {"id": "VM-Y10-FIN-010", "skill": "Changing rates", "difficulty": "medium", "question": "A $2000 investment earns 5% in year one and 2% in year two. Find its final balance.", "answer": "$2142", "solution": "2000 × 1.05 × 1.02 = 2142.", "topic": "fin"}, {"id": "VM-Y10-FIN-011", "skill": "Flat depreciation", "difficulty": "medium", "question": "A $1200 appliance loses $150 in value each year. Compare its value after two years with a 12.5% annual reducing-balance model.", "answer": "$900 versus $918.75", "solution": "Flat: 1200 − 300. Reducing: 1200 × 0.875².", "topic": "fin"}, {"id": "VM-Y10-FIN-012", "skill": "Model choice", "difficulty": "hard", "question": "Two investments start at the same amount. One earns 4% simple interest and the other 4% compound interest annually. Explain when their balances first differ.", "answer": "After year 2", "solution": "Year one interest is identical; year two compound interest includes interest on year one interest.", "topic": "fin"}, {"id": "VM-Y10-FIN-013", "skill": "Effective rate", "difficulty": "hard", "question": "Find the effective annual percentage increase if an account grows 1% each month. Round to two decimal places.", "answer": "12.68%", "solution": "(1.01¹² − 1) × 100 ≈ 12.68.", "topic": "fin"}, {"id": "VM-Y10-FIN-014", "skill": "Rate inference", "difficulty": "medium", "question": "An investment grows from $800 to $864 in one year. Find the annual rate.", "answer": "8%", "solution": "64 ÷ 800 × 100 = 8.", "topic": "fin"}, {"id": "VM-Y10-FIN-015", "skill": "Spreadsheet", "difficulty": "medium", "question": "Cell B2 contains an opening balance and C1 contains an annual interest rate as a percentage. Write a spreadsheet formula for the next balance that can be filled down.", "answer": "=B2*(1+$C$1)", "solution": "The absolute reference keeps the rate fixed.", "topic": "fin"}, {"id": "VM-Y10-FIN-016", "skill": "Comparison", "difficulty": "hard", "question": "A $5000 investment earns 4% annually for two years, with a $100 fee deducted at the end. Is the final balance above $5300?", "answer": "Yes, $5308", "solution": "5000 × 1.04² − 100 = 5308.", "topic": "fin"}, {"id": "VM-Y10-FIN-017", "skill": "Break-even comparison", "difficulty": "hard", "question": "Two $2000 accounts offer 5% compound interest or $105 simple interest each year. Which is ahead after three years?", "answer": "Compound by $0.25", "solution": "2000(1.05)^3 = 2315.25; simple balance = 2315.", "topic": "fin"}, {"id": "VM-Y10-FIN-018", "skill": "Rate recovery", "difficulty": "hard", "question": "A laptop loses 36% of its value over two years at a constant annual reducing-balance rate. Find that rate.", "answer": "20%", "solution": "The retained fraction is 0.64; its square root is 0.8, so the loss is 20% annually.", "topic": "fin"}, {"id": "VM-Y10-FIN-019", "skill": "Timing of deposits", "difficulty": "hard", "question": "An account earns 10% annually. Compare depositing $1000 now and $1000 in one year with depositing $2000 now, measured after two years.", "answer": "$2310 versus $2420", "solution": "First plan: 1000(1.1)^2 + 1000(1.1) = 2310. Second: 2000(1.1)^2 = 2420.", "topic": "fin"}, {"id": "VM-Y10-FIN-020", "skill": "Inflation", "difficulty": "hard", "question": "A savings balance rises 4% while prices rise 5%. Does its purchasing power increase?", "answer": "No", "solution": "The purchasing-power multiplier is 1.04 ÷ 1.05, less than 1.", "topic": "fin"}, {"id": "VM-Y10-FIN-021", "skill": "Graph interpretation", "difficulty": "hard", "question": "A depreciation graph starts at $8000 and falls by $800 each year. Is it a constant percentage model?", "answer": "No", "solution": "The dollar decrease is constant but the percentage of the remaining value increases.", "topic": "fin"}, {"id": "VM-Y10-FIN-022", "skill": "Model construction", "difficulty": "hard", "question": "A camera retains 75% of its value each year. Write a rule for its value V after n years if it costs $1600.", "answer": "V = 1600(0.75)^n", "solution": "Multiply the original value by the retention factor once per year.", "topic": "fin"}, {"id": "VM-Y10-FIN-023", "skill": "Interest table", "difficulty": "easy", "question": "A balance grows from $800 to $840 in one year. What percentage interest was credited?", "answer": "5%", "solution": "40 ÷ 800 × 100 = 5%.", "topic": "fin"}, {"id": "VM-Y10-FIN-024", "skill": "Compounding assumptions", "difficulty": "medium", "question": "Two accounts advertise 6% p.a., one compounded annually and one monthly. Which has the larger balance after a year with no fees or withdrawals?", "answer": "Monthly", "solution": "Monthly compounding gives multiplier 1.005^12, greater than 1.06.", "topic": "fin"}, {"id": "VM-Y10-FIN-025", "skill": "Spreadsheet debugging", "difficulty": "hard", "question": "Cell B2 contains 1500 and C2 contains 4% as a spreadsheet percentage. A student enters =B2+C2 for the next balance. Correct the formula.", "answer": "=B2*(1+C2)", "solution": "The interest rate must multiply the balance before being added.", "topic": "fin"}, {"id": "VM-Y10-FIN-026", "skill": "Depreciation interpretation", "difficulty": "easy", "question": "A camera retains 85% of its value each year. What percentage of its current value is lost annually?", "answer": "15%", "solution": "100% − 85% = 15%.", "topic": "fin"}, {"id": "VM-Y10-FIN-027", "skill": "Model limitation", "difficulty": "challenge", "question": "A $600 phone depreciates by 25% annually. Can this model predict a value of exactly zero after a finite number of years? Explain.", "answer": "No", "solution": "600 × 0.75^n remains positive for every finite nonnegative n.", "topic": "fin"}, {"id": "VM-Y10-FIN-028", "skill": "Interest comparison", "difficulty": "medium", "question": "An account earns $60 simple interest each year on $1500. What annual compound rate would give the same interest in the first year?", "answer": "4%", "solution": "60 ÷ 1500 = 0.04.", "topic": "fin"}, {"id": "VM-Y10-FIN-029", "skill": "Multiplier", "difficulty": "easy", "question": "A savings balance is multiplied by 1.035 each year. What annual percentage increase does this represent?", "answer": "3.5%", "solution": "Subtract 1 from 1.035 and multiply by 100.", "topic": "fin"}, {"id": "VM-Y10-FIN-030", "skill": "Interest interpretation", "difficulty": "easy", "question": "A statement shows an opening balance of $620 and a closing balance of $651, with no transactions. How much interest was credited?", "answer": "$31", "solution": "651 − 620 = 31.", "topic": "fin"}, {"id": "VM-Y10-FIN-031", "skill": "Variable depreciation", "difficulty": "challenge", "question": "A camera loses 30% of its value in the first year and 10% in the second. What single percentage loss produces the same final value?", "answer": "37%", "solution": "The retained fraction is 0.7 × 0.9 = 0.63, so the loss is 37%.", "topic": "fin"}, {"id": "VM-Y10-FIN-032", "skill": "Model constraints", "difficulty": "challenge", "question": "A $600 asset loses $80 each year under a flat depreciation model. Explain why the model cannot be used indefinitely.", "answer": "It predicts a negative value after eight years.", "solution": "600 − 80 × 8 = −40. A nonnegative resale value requires a restricted model.", "topic": "fin"}, {"id": "VM-Y10-FIN-033", "skill": "Graph reading", "difficulty": "easy", "question": "A balance graph passes through (0, 800), (1, 840) and (2, 882), with time in years. What annual percentage rate is shown?", "answer": "5%", "solution": "840 ÷ 800 = 1.05, so the rate is 5%.", "topic": "fin"}, {"id": "VM-Y10-FIN-034", "skill": "Depreciation graph", "difficulty": "medium", "question": "A camera worth $1600 loses 25% annually. Give the four points for years 0 to 3 on its value graph.", "answer": "(0,1600), (1,1200), (2,900), (3,675)", "solution": "Multiply each previous value by 0.75.", "topic": "fin"}, {"id": "VM-Y10-FIN-035", "skill": "Fee comparison", "difficulty": "hard", "question": "Account A pays 5% annually on $2000 but deducts $30 at each year end. Account B pays 3% with no fees. Which has more after two years?", "answer": "$2143.50 in A", "solution": "A: 2000 × 1.05 − 30 = 2070; then 2070 × 1.05 − 30 = 2143.50. B: 2000 × 1.03² = 2121.80.", "topic": "fin"}, {"id": "VM-Y10-FIN-036", "skill": "Graph crossing", "difficulty": "challenge", "question": "Two assets start at $1000 and $1500. The first grows 10% annually and the second falls 10% annually. At which whole year is the first worth more for the first time?", "answer": "Year 3", "solution": "Year 2: 1210 versus 1215. Year 3: 1331 versus 1093.50. The first increases and the second decreases, so year 3 is the first crossing.", "topic": "fin"}, {"id": "VM-Y10-FIN-037", "skill": "Budget decision", "difficulty": "hard", "question": "A family needs $3000 in two years. They have $2700 in an account earning 4% annually. How much extra must they deposit today?", "answer": "$73.67", "solution": "Required initial balance = 3000 ÷ 1.04² = 2773.67 rounded up to cents; subtract 2700.", "topic": "fin"}, {"id": "VM-Y10-FIN-038", "skill": "Investment fee timing", "difficulty": "hard", "question": "An investment of $4000 earns 5% annually. A $100 fee is deducted at the end of each year. Find the balance after two years.", "answer": "$4205", "solution": "Year 1: 4000 × 1.05 − 100 = 4100. Year 2: 4100 × 1.05 − 100 = 4205.", "topic": "fin"}, {"id": "VM-Y10-FIN-039", "skill": "Resale decision", "difficulty": "medium", "question": "A $12000 vehicle loses 15% annually. A dealer offers $8500 after two years. How much below the model value is the offer?", "answer": "$170", "solution": "Model value = 12000 × 0.85² = 8670; difference = 170.", "topic": "fin"}, {"id": "VM-Y10-FIN-040", "skill": "Interest allocation", "difficulty": "challenge", "question": "Two accounts together contain $5000. One earns 2% and the other 5% annually. Total first-year interest is $190. Find the starting balance in each.", "answer": "$2000 at 2%; $3000 at 5%", "solution": "Let x be the amount at 5%. Then 0.05x + 0.02(5000 − x) = 190, so 0.03x = 90 and x = 3000.", "topic": "fin"}, {"id": "VM-Y10-FIN-041", "skill": "Interest statement", "difficulty": "easy", "question": "A statement shows an opening balance of $800 and closing balance of $836 after one year, with no transactions. What annual interest rate was paid?", "answer": "4.5%", "solution": "Interest is $36; 36 ÷ 800 × 100 = 4.5%.", "topic": "fin"}, {"id": "VM-Y10-FIN-042", "skill": "Depreciation schedule", "difficulty": "easy", "question": "A printer valued at $600 loses $90 in its first year. What percentage of its original value remains?", "answer": "85%", "solution": "Remaining value is $510; 510 ÷ 600 × 100 = 85%.", "topic": "fin"}, {"id": "VM-Y10-FIN-043", "skill": "Rounding policy", "difficulty": "medium", "question": "A $100 deposit earns 1.25% each month. Interest is rounded to cents each month. Find the balance after two months.", "answer": "$102.52", "solution": "First interest is $1.25. Second interest is 101.25 × 0.0125 = 1.265625, rounded to $1.27. Add to obtain $102.52.", "topic": "fin"}, {"id": "VM-Y10-FIN-044", "skill": "Rate comparison", "difficulty": "medium", "question": "A savings account doubles over ten years. Is its total percentage increase 50%, 100% or 200%? Explain why this is not its annual rate.", "answer": "100%", "solution": "The increase equals the original balance. The total increase spans ten years, not one year.", "topic": "fin"}, {"id": "VM-Y10-FIN-045", "skill": "Statement interpretation", "difficulty": "easy", "question": "An annual statement shows an opening balance of $800, no transactions and closing balance of $840. What annual interest rate was credited?", "answer": "5%", "solution": "Interest is $40; 40 ÷ 800 × 100 = 5%.", "topic": "fin"}, {"id": "VM-Y10-FIN-046", "skill": "Fee timing", "difficulty": "medium", "question": "A $1000 account earns 10% annually and charges $20 at the end of each year after interest. Find the balance after two years.", "answer": "$1168", "solution": "Year 1: 1100 − 20 = 1080. Year 2: 1188 − 20 = 1168.", "topic": "fin"}, {"id": "VM-Y10-FIN-047", "skill": "Investment allocation", "difficulty": "hard", "question": "Of $2000, $500 earns 4% and the remainder earns 6% for one year. Find the overall percentage return.", "answer": "5.5%", "solution": "Interest = 500 × 0.04 + 1500 × 0.06 = 110; 110 ÷ 2000 = 0.055.", "topic": "fin"}, {"id": "VM-Y10-FIN-048", "skill": "Model investigation", "difficulty": "challenge", "question": "Two identical assets depreciate by 10% and 20% annually respectively. After two years, what is the ratio of their values?", "answer": "81:64", "solution": "The retained fractions are 0.9² = 0.81 and 0.8² = 0.64; initial values cancel.", "topic": "fin"}, {"id": "VM-Y10-FIN-049", "skill": "Growth reversal", "difficulty": "medium", "question": "A share price falls 20%. What percentage rise from its new price restores its original value?", "answer": "25%", "solution": "The new price is 0.8 of the original. Required multiplier = 1 ÷ 0.8 = 1.25.", "topic": "fin"}, {"id": "VM-Y10-FIN-050", "skill": "Interest cap", "difficulty": "hard", "question": "A $4000 account earns 5% annually on its first $3000 and no interest on the rest. Find its balance after two years if interest stays in the account.", "answer": "$4300", "solution": "The interest-bearing portion remains $3000. Each year adds $150, so 4000 + 2 × 150 = 4300.", "topic": "fin"}, {"id": "VM-Y10-FIN-051", "skill": "Depreciation floor", "difficulty": "easy", "question": "A $700 device loses $200 each year until it reaches a minimum resale value of $100. What is its value after four years?", "answer": "$100", "solution": "The floor is reached after three years; the fourth year cannot reduce it further.", "topic": "fin"}, {"id": "VM-Y10-FIN-052", "skill": "Doubling comparison", "difficulty": "challenge", "question": "Without calculating a long table, explain whether a deposit growing 10% annually doubles sooner or later than one growing by simple interest of 10% annually.", "answer": "Sooner", "solution": "Simple interest doubles after 10 years. Compound interest exceeds simple interest after year one, and 1.1⁸ = 2.14358881, so it doubles by year eight.", "topic": "fin"}, {"id": "VM-Y10-FIN-053", "skill": "Interest-only withdrawal", "difficulty": "easy", "question": "An account earns $84 interest in its first year. All interest is withdrawn at the end of each year and the rate stays fixed. How much interest is earned in year three?", "answer": "$84", "solution": "The principal never changes, so annual interest remains $84.", "topic": "fin"}, {"id": "VM-Y10-FIN-054", "skill": "Compounding period comparison", "difficulty": "medium", "question": "A bank offers 8% p.a. compounded quarterly. Find the balance of $1250 after six months.", "answer": "$1300.50", "solution": "Two quarters at 2% each: 1250 × 1.02² = 1300.50.", "topic": "fin"}, {"id": "VM-Y10-FIN-055", "skill": "Rate sequence", "difficulty": "hard", "question": "An investment loses 25% in year one and gains 40% in year two. Is it above its starting value?", "answer": "Yes, by 5%.", "solution": "The combined multiplier is 0.75 × 1.40 = 1.05.", "topic": "fin"}, {"id": "VM-Y10-FIN-056", "skill": "Equal annual dollar gains", "difficulty": "challenge", "question": "Can a positive investment earning a fixed positive compound rate have identical dollar interest in two consecutive years without withdrawals? Justify.", "answer": "No.", "solution": "If principal is P and rate r > 0, first interest is Pr and second is Pr(1+r), which is larger.", "topic": "fin"}, {"id": "VM-Y10-FIN-057", "skill": "Interest base", "difficulty": "easy", "question": "A savings account has $840 at the start of its second year, including $40 interest from year one. On what amount is second-year compound interest calculated?", "answer": "$840", "solution": "Compound interest uses the current balance, including previously credited interest.", "topic": "fin"}, {"id": "VM-Y10-FIN-058", "skill": "Missing statement entry", "difficulty": "medium", "question": "A statement shows an opening balance of $2500, interest of $75 and a closing balance of $2520. No deposits or withdrawals occurred. What fee was deducted?", "answer": "$55", "solution": "2500 + 75 − 2520 = 55.", "topic": "fin"}, {"id": "VM-Y10-FIN-059", "skill": "Depreciation comparison", "difficulty": "hard", "question": "Two cameras cost $800 and $1000. After one year the first retains 90% of its value and the second retains 72%. Compare their dollar losses.", "answer": "$80 and $280; difference $200", "solution": "Both retain $720. Subtract $720 from each original price.", "topic": "fin"}, {"id": "VM-Y10-FIN-060", "skill": "Equivalent growth periods", "difficulty": "challenge", "question": "An investment grows by 21% over two years at a constant annual compound rate. A second investment grows by 10% each year for four years. What percentage growth would the first investment achieve over four years?", "answer": "46.41%", "solution": "Two consecutive two-year periods give multiplier 1.21² = 1.4641.", "topic": "fin"}, {"id": "VM-Y10-FIN-061", "skill": "Spreadsheet references", "difficulty": "easy", "question": "Cell B2 contains the opening balance and C1 contains the annual interest rate as a percentage. Write a spreadsheet formula for the closing balance using an absolute reference to the rate.", "answer": "=B2*(1+$C$1)", "solution": "The balance reference changes when copied down; the rate reference stays fixed.", "topic": "fin"}, {"id": "VM-Y10-FIN-062", "skill": "Quarterly statement", "difficulty": "medium", "question": "A statement shows quarterly opening balances of $800, $808 and $816.08. Assuming no transactions, determine the nominal annual interest rate compounded quarterly.", "answer": "4% p.a.", "solution": "808 ÷ 800 − 1 = 0.01 per quarter. Multiply by 4.", "topic": "fin"}, {"id": "VM-Y10-FIN-063", "skill": "Fee break-even", "difficulty": "hard", "question": "Two accounts earn 3% and 4% respectively over one year. The second charges a $25 fee at year end. What opening balance makes the final balances equal?", "answer": "$2500", "solution": "Let P be the balance. 1.03P = 1.04P − 25, so 0.01P = 25.", "topic": "fin"}, {"id": "VM-Y10-FIN-064", "skill": "Depreciation assumptions", "difficulty": "challenge", "question": "A camera loses 25% of its value in year one and 10% of its remaining value in year two. Is a constant 17.5% annual depreciation model equivalent over two years? Justify.", "answer": "No", "solution": "Actual retention is 0.75 × 0.90 = 0.675. Constant retention is 0.825² = 0.680625, which is greater.", "topic": "fin"}, {"id": "VM-Y10-FIN-065", "skill": "Balance recurrence", "difficulty": "easy", "question": "A balance is updated each year using B(next) = 1.04B(current). What does the 1 represent in 1.04?", "answer": "The existing balance.", "solution": "The multiplier retains 100% of the balance and adds 4% interest.", "topic": "fin"}, {"id": "VM-Y10-FIN-066", "skill": "Interest distribution", "difficulty": "medium", "question": "An account earns $80 in its first year at 4% compound interest. How much interest does it earn in its second year if no money is withdrawn?", "answer": "$83.20", "solution": "The first interest payment also earns 4%: 80 × 1.04 = 83.20.", "topic": "fin"}, {"id": "VM-Y10-FIN-067", "skill": "Depreciation bound", "difficulty": "hard", "question": "A device loses 10% of its current value each year. Can its value become exactly zero after a finite number of years under this model?", "answer": "No.", "solution": "For positive initial value P, P × 0.9^n remains positive for every finite nonnegative integer n.", "topic": "fin"}, {"id": "VM-Y10-FIN-068", "skill": "Tax on interest model", "difficulty": "challenge", "question": "A $5000 deposit earns 6% annually. A hypothetical tax of 25% of each interest payment is deducted immediately. Find the balance after two years.", "answer": "$5460.13", "solution": "Net annual interest rate is 6% × 0.75 = 4.5%. Balance = 5000 × 1.045² = 5460.125, rounded to cents.", "topic": "fin"}, {"id": "VM-Y10-FIN-069", "skill": "Interest credit", "difficulty": "easy", "question": "A statement shows opening balance $800, a $32 interest credit and no other transactions. What percentage of the opening balance was credited?", "answer": "4%", "solution": "32 ÷ 800 × 100 = 4%.", "topic": "fin"}, {"id": "VM-Y10-FIN-070", "skill": "Comparing depreciation methods", "difficulty": "medium", "question": "A $6000 machine loses $900 each year under a flat model. Under a reducing model it loses 15% annually. Find the difference between the models after two years.", "answer": "$135", "solution": "Flat value = 4200; reducing value = 6000 × 0.85² = 4335. Difference = 135.", "topic": "fin"}, {"id": "VM-Y10-FIN-071", "skill": "Deposit timing", "difficulty": "hard", "question": "Two savers each deposit $400 at the start of one of two consecutive years. One deposits in year one and the other in year two. Both earn 5% annually. How much more does the earlier saver have at the end of year two?", "answer": "$21", "solution": "Earlier balance = 400 × 1.05² = 441; later balance = 420; difference = 21.", "topic": "fin"}, {"id": "VM-Y10-FIN-072", "skill": "Growth bound", "difficulty": "challenge", "question": "An investment grows 10% annually for two years. Can a single 20% increase followed by no growth produce the same final balance for a positive initial deposit? Justify.", "answer": "No", "solution": "The two-year multiplier is 1.21, whereas a single 20% increase gives 1.20. The difference is 1% of the initial deposit.", "topic": "fin"}, {"id": "VM-Y10-FIN-073", "skill": "Interest timing", "difficulty": "easy", "question": "A term deposit credits interest quarterly. How many credits occur in 30 months?", "answer": "10", "solution": "30 ÷ 3 = 10.", "topic": "fin"}, {"id": "VM-Y10-FIN-074", "skill": "Depreciation interpretation", "difficulty": "easy", "question": "A camera retains 82% of its value each year. What percentage of its value is lost annually?", "answer": "18%", "solution": "100 − 82 = 18%.", "topic": "fin"}, {"id": "VM-Y10-FIN-075", "skill": "Statement reconciliation", "difficulty": "medium", "question": "A savings account opens with $1200. Interest of 4% is credited before a $200 withdrawal at year end. Find the closing balance.", "answer": "$1048", "solution": "1200 × 1.04 − 200 = 1048.", "topic": "fin"}, {"id": "VM-Y10-FIN-076", "skill": "Compounding comparison", "difficulty": "hard", "question": "A $2000 deposit earns 4% p.a. compounded half-yearly. How much more does it earn in one year than a deposit earning 4% compounded annually?", "answer": "$0.80", "solution": "2000(1.02)² − 2000(1.04) = 0.80.", "topic": "fin"}, {"id": "VM-Y10-FIN-077", "skill": "Interest component", "difficulty": "easy", "question": "A statement lists an opening balance of $840 and a closing balance of $882, with no transactions. How many dollars of interest were credited?", "answer": "$42", "solution": "Subtract 840 from 882.", "topic": "fin"}, {"id": "VM-Y10-FIN-078", "skill": "Depreciation schedule", "difficulty": "medium", "question": "A printer worth $640 loses one quarter of its current value each year. List its values at the end of the first three years.", "answer": "$480, $360, $270", "solution": "Multiply successively by 0.75.", "topic": "fin"}, {"id": "VM-Y10-FIN-079", "skill": "Interest comparison", "difficulty": "medium", "question": "A $5000 deposit earns $250 in its first year. Another deposit of $4000 earns $220. Which has the higher annual percentage return?", "answer": "The second deposit", "solution": "250 ÷ 5000 = 5%; 220 ÷ 4000 = 5.5%.", "topic": "fin"}, {"id": "VM-Y10-FIN-080", "skill": "Transaction timing", "difficulty": "hard", "question": "An account starts with $3000 and earns 10% annually. Compare adding $500 immediately with adding it just after the second annual interest credit.", "answer": "$105 more if added immediately", "solution": "The original balance grows identically. The early $500 grows to $605; the late deposit remains $500.", "topic": "fin"}, {"id": "VM-Y10-FIN-081", "skill": "Rate interpretation", "difficulty": "easy", "question": "A reducing-balance depreciation model has multiplier 0.84. What percentage of the original value is lost in the first year?", "answer": "16%", "solution": "100% − 84% = 16%.", "topic": "fin"}, {"id": "VM-Y10-FIN-082", "skill": "Interest allocation", "difficulty": "medium", "question": "A $6000 investment is split equally between accounts earning 2% and 6% annually. Find the combined balance after one year.", "answer": "$6240", "solution": "3000 × 1.02 + 3000 × 1.06 = 6240.", "topic": "fin"}, {"id": "VM-Y10-FIN-083", "skill": "Statement reconstruction", "difficulty": "medium", "question": "A statement shows an opening balance of $800, interest of $24 and a closing balance of $924. The only other transaction was a deposit. Find it.", "answer": "$100", "solution": "924 − 800 − 24 = 100.", "topic": "fin"}, {"id": "VM-Y10-FIN-084", "skill": "Rate change comparison", "difficulty": "hard", "question": "A fund falls 25% then rises 40%. A second fund rises 10% over the same period. Which finishes higher if both start at $4000, and by how much?", "answer": "Second fund by $200", "solution": "First: 4000 × 0.75 × 1.4 = 4200. Second: 4400. Difference = 200.", "topic": "fin"}, {"skill": "Interest credit", "difficulty": "easy", "question": "A statement shows a starting balance of $840 and an interest credit of $21, with no other transactions. What percentage interest was credited?", "answer": "2.5%", "solution": "21 ÷ 840 × 100 = 2.5%.", "id": "VM-Y10-FIN-085", "topic": "fin"}, {"skill": "Depreciation schedule", "difficulty": "medium", "question": "A council records equipment values of $8000, $6800 and $5780 at successive year ends. Determine whether a constant percentage depreciation fits these figures.", "answer": "Yes, 15% annually", "solution": "6800 ÷ 8000 = 0.85 and 5780 ÷ 6800 = 0.85; each loss is 15%.", "id": "VM-Y10-FIN-086", "topic": "fin"}, {"skill": "Interest allocation", "difficulty": "medium", "question": "Two accounts earn 4% and 6% respectively for one year. A saver puts $3000 in the first and $1000 in the second. Find the overall percentage return.", "answer": "4.5%", "solution": "Interest = 120 + 60 = 180; 180 ÷ 4000 × 100 = 4.5%.", "id": "VM-Y10-FIN-087", "topic": "fin"}, {"skill": "Compounding comparison", "difficulty": "hard", "question": "A $5000 investment earns 8% in year one and loses 8% in year two. What percentage increase in year three restores the original balance?", "answer": "Approximately 0.644%", "solution": "Balance = 5000 × 1.08 × 0.92 = 4968. Required increase = 32 ÷ 4968 × 100 ≈ 0.644%.", "id": "VM-Y10-FIN-088", "topic": "fin"}, {"id": "VM-Y10-FIN-089", "skill": "Interest multiplier", "difficulty": "easy", "question": "A bank quotes a quarterly interest rate of 0.8%. What multiplier applies to the balance each quarter?", "answer": "1.008", "solution": "Convert 0.8% to 0.008 and add 1.", "topic": "fin"}, {"id": "VM-Y10-FIN-090", "skill": "Depreciation interpretation", "difficulty": "easy", "question": "A valuation spreadsheet uses the multiplier 0.94 each year. What percentage of the previous value is lost annually?", "answer": "6%", "solution": "1 − 0.94 = 0.06 = 6%.", "topic": "fin"}, {"id": "VM-Y10-FIN-091", "skill": "Partial year comparison", "difficulty": "medium", "question": "A $4000 deposit earns 1% each quarter. Compare the balance after six months with a single interest credit of 2%.", "answer": "$0.40 more with quarterly compounding", "solution": "4000 × 1.01² = 4080.40; 4000 × 1.02 = 4080.", "topic": "fin"}, {"id": "VM-Y10-FIN-092", "skill": "Different fee bases", "difficulty": "hard", "question": "Two one-year accounts start with $2500 and earn 6%. Account A charges $30 before interest; B charges $30 after interest. Which finishes higher and by how much?", "answer": "B by $1.80", "solution": "A: 2470 × 1.06 = 2618.20. B: 2500 × 1.06 − 30 = 2620.", "topic": "fin"}, {"id": "VM-Y10-FIN-093", "skill": "Percentage recovery", "difficulty": "easy", "question": "A share price falls from $80 to $60. What percentage of its original price remains?", "answer": "75%", "solution": "60 ÷ 80 × 100 = 75%.", "topic": "fin"}, {"id": "VM-Y10-FIN-094", "skill": "Interest interpretation", "difficulty": "easy", "question": "An account advertises 4% p.a. simple interest. What interest does each $100 earn over one year?", "answer": "$4", "solution": "100 × 0.04 = 4.", "topic": "fin"}, {"id": "VM-Y10-FIN-095", "skill": "Depreciation comparison", "difficulty": "medium", "question": "Two machines are each worth $9000. The first loses $1200 annually. The second loses 15% of its current value annually. Which loses more in the first year, and by how much?", "answer": "The second, by $150", "solution": "9000 × 0.15 = 1350; 1350 − 1200 = 150.", "topic": "fin"}, {"id": "VM-Y10-FIN-096", "skill": "Loan repayment", "difficulty": "medium", "question": "A loan of $2400 is repaid in 18 monthly instalments of $145. What is the total borrowing cost above principal?", "answer": "$210", "solution": "18 × 145 − 2400 = 210.", "topic": "fin"}, {"id": "VM-Y10-FIN-097", "skill": "Reverse compound interest", "difficulty": "hard", "question": "An investment grows by 5% annually for two years to $6615. Find its initial value.", "answer": "$6000", "solution": "6615 ÷ 1.05² = 6000.", "topic": "fin"}, {"id": "VM-Y10-FIN-098", "skill": "Fee threshold", "difficulty": "hard", "question": "An account earns 3% annual interest and charges a $45 annual fee after interest. What opening balance gives exactly zero net growth?", "answer": "$1500", "solution": "0.03P = 45, so P = 1500.", "topic": "fin"}, {"id": "VM-Y10-FIN-099", "skill": "Percentage fee", "difficulty": "easy", "question": "A transfer of $760 attracts a 1.5% fee. Find the fee.", "answer": "$11.40", "solution": "760 × 0.015 = 11.40.", "topic": "fin"}, {"id": "VM-Y10-FIN-100", "skill": "Depreciation interpretation", "difficulty": "easy", "question": "A machine retains 82% of its value each year. State its annual depreciation rate.", "answer": "18%", "solution": "100% − 82% = 18%.", "topic": "fin"}, {"id": "VM-Y10-FIN-101", "skill": "Reverse discount", "difficulty": "medium", "question": "A discounted appliance costs $714 after a 15% reduction. Find its original price.", "answer": "$840", "solution": "714 ÷ 0.85 = 840.", "topic": "fin"}, {"id": "VM-Y10-FIN-102", "skill": "Interest frequency", "difficulty": "medium", "question": "Compare one year of simple interest at 6% on $2400 with interest of 3% credited twice and reinvested.", "answer": "Compound earns $2.16 more", "solution": "Simple interest is $144; compound interest is 2400(1.03² − 1) = $146.16.", "topic": "fin"}, {"id": "VM-Y10-FIN-103", "skill": "Changing depreciation", "difficulty": "hard", "question": "A vehicle worth $24000 loses 20% in year one and 10% in year two. Find the overall percentage loss.", "answer": "28%", "solution": "Remaining fraction is 0.8 × 0.9 = 0.72; loss is 28%.", "topic": "fin"}, {"id": "VM-Y10-FIN-104", "skill": "Reverse compound growth", "difficulty": "hard", "question": "An investment doubles after two years at a constant annual compound rate. Find the rate to one decimal place.", "answer": "41.4%", "solution": "The annual multiplier is √2; subtract 1 and multiply by 100.", "topic": "fin"}, {"id": "VM-Y10-FIN-105", "skill": "Growth factor", "difficulty": "easy", "question": "A savings balance is multiplied by 1.045 each year. State the annual percentage rate.", "answer": "4.5%", "solution": "Subtract 1 from 1.045 and multiply by 100.", "topic": "fin"}, {"id": "VM-Y10-FIN-106", "skill": "Depreciation factor", "difficulty": "easy", "question": "A machine retains 87% of its value each year. State its annual depreciation rate.", "answer": "13%", "solution": "100% − 87% = 13%.", "topic": "fin"}, {"id": "VM-Y10-FIN-107", "skill": "Interest comparison", "difficulty": "medium", "question": "Two accounts start with $800. One earns $40 each year; the other earns 5% compound interest. Find the difference in balances after three years.", "answer": "$6.10", "solution": "Simple balance = 920; compound balance = 800(1.05)^3 = 926.10.", "topic": "fin"}, {"id": "VM-Y10-FIN-108", "skill": "Rounding interest", "difficulty": "medium", "question": "A bank credits interest to the nearest cent annually. A balance of $101 earns 2.5% per year. Find the balance after two years using conventional half-up rounding.", "answer": "$106.12", "solution": "First interest 2.525 rounds to 2.53; second interest 103.53 × 0.025 = 2.58825 rounds to 2.59.", "topic": "fin"}, {"id": "VM-Y10-FIN-109", "skill": "Depreciation recovery", "difficulty": "hard", "question": "An asset loses 36% of its value. What percentage increase on its reduced value would restore its original value?", "answer": "56.25%", "solution": "Original value divided by reduced value = 1/0.64 = 1.5625.", "topic": "fin"}, {"id": "VM-Y10-FIN-110", "skill": "Investment threshold", "difficulty": "hard", "question": "A $2000 investment earns 8% compound interest annually. Find the first whole year when its value exceeds $2500.", "answer": "3 years", "solution": "After two years it is $2332.80; after three it is $2519.424.", "topic": "fin"}, {"id": "VM-Y10-FIN-111", "skill": "Fee refund", "difficulty": "easy", "question": "A bank refunds three monthly fees of $4.50. What is the total refund?", "answer": "$13.50", "solution": "3 × 4.50 = 13.50.", "topic": "fin"}, {"id": "VM-Y10-FIN-112", "skill": "Percentage loss", "difficulty": "easy", "question": "A bicycle bought for $480 is sold for $360. Express the loss as a percentage of cost.", "answer": "25%", "solution": "Loss = 120; 120 ÷ 480 × 100 = 25%.", "topic": "fin"}, {"id": "VM-Y10-FIN-113", "skill": "Reverse depreciation", "difficulty": "medium", "question": "A camera is worth $765 after a 15% reduction in value. Find its previous value.", "answer": "$900", "solution": "765 ÷ 0.85 = 900.", "topic": "fin"}, {"id": "VM-Y10-FIN-114", "skill": "Interest comparison", "difficulty": "medium", "question": "An account pays 6% simple interest annually. What principal earns $270 over 18 months?", "answer": "$3000", "solution": "270 ÷ (0.06 × 1.5) = 3000.", "topic": "fin"}, {"id": "VM-Y10-FIN-115", "skill": "Compound fee", "difficulty": "hard", "question": "A $4000 balance grows by 5% each year, then a $30 fee is deducted at each year end. Find the balance after two years.", "answer": "$4348.50", "solution": "Year one: 4200 − 30 = 4170. Year two: 4170 × 1.05 − 30 = 4348.50.", "topic": "fin"}, {"id": "VM-Y10-FIN-116", "skill": "Equivalent discounts", "difficulty": "hard", "question": "A retailer offers 20% off followed by a further 15% off. What single discount gives the same price?", "answer": "32%", "solution": "Remaining fraction = 0.8 × 0.85 = 0.68; discount = 32%.", "topic": "fin"}, {"id": "VM-Y10-FIN-117", "skill": "Percentage fee", "difficulty": "easy", "question": "A prepaid travel card charges 1.5% on a $240 purchase. Find the fee.", "answer": "$3.60", "solution": "240 × 0.015 = 3.60.", "topic": "fin"}, {"id": "VM-Y10-FIN-118", "skill": "Effective saving", "difficulty": "medium", "question": "A $360 annual membership is offered for $32 per month instead. How much is saved by paying annually?", "answer": "$24", "solution": "12 × 32 − 360 = 24.", "topic": "fin"}, {"id": "VM-Y10-FIN-119", "skill": "Reverse compound growth", "difficulty": "hard", "question": "An investment is worth $5,292 after two years of growth at 5% p.a. compounded annually. Find its initial value.", "answer": "$4,800", "solution": "5292 ÷ 1.05² = 4800.", "topic": "fin"}, {"id": "VM-Y10-FIN-120", "skill": "Depreciation comparison", "difficulty": "medium", "question": "A machine loses $180 of its $900 value in year one and $144 in year two. Is the percentage depreciation constant?", "answer": "Yes, 20%", "solution": "180 ÷ 900 = 0.2; 144 ÷ 720 = 0.2.", "topic": "fin"}, {"id": "VM-Y10-GEO-001", "skill": "Definition", "difficulty": "easy", "question": "Are all circles similar? Explain.", "answer": "Yes", "solution": "All circles have the same shape and a uniform scale factor equal to the ratio of radii.", "topic": "geo"}, {"id": "VM-Y10-GEO-002", "skill": "Correspondence", "difficulty": "easy", "question": "Given triangle ABC is similar to triangle PQR, which side corresponds to BC?", "answer": "QR", "solution": "Vertices correspond in the order stated.", "topic": "geo"}, {"id": "VM-Y10-GEO-003", "skill": "Proportion", "difficulty": "medium", "question": "Are rectangles 4 by 6 and 8 by 13 similar? Explain.", "answer": "No", "solution": "The side ratios 8/4 and 13/6 are unequal.", "topic": "geo"}, {"id": "VM-Y10-GEO-004", "skill": "Scale drawing", "difficulty": "medium", "question": "A map uses scale 1:25000. Two points are 6 cm apart on the map. Find actual distance in km.", "answer": "1.5 km", "solution": "6×25000 = 150000 cm = 1.5 km.", "topic": "geo"}, {"id": "VM-Y10-GEO-005", "skill": "Indirect measurement", "difficulty": "hard", "question": "At the same time, a 1.5 m pole casts a 2 m shadow and a tree casts a 14 m shadow. Find tree height. Both objects are vertical and stand on level ground.", "answer": "10.5 m", "solution": "Similar triangles give h/14 = 1.5/2.", "topic": "geo"}, {"id": "VM-Y10-GEO-006", "skill": "Reduction", "difficulty": "medium", "question": "A drawing is reduced from width 24 cm to 18 cm. Its original height is 16 cm. Find new height. Assume uniform scaling.", "answer": "12 cm", "solution": "Scale factor = 18/24 = 0.75; height = 16×0.75.", "topic": "geo"}, {"id": "VM-Y10-GEO-007", "skill": "Scale factor", "difficulty": "easy", "question": "A 5 cm side corresponds to a 12 cm side in an enlargement. Find scale factor.", "answer": "2.4", "solution": "12 ÷ 5 = 2.4.", "topic": "geo"}, {"id": "VM-Y10-GEO-008", "skill": "Similarity test", "difficulty": "medium", "question": "Triangles have side lengths 3, 5, 7 and 6, 10, 14. Are they similar?", "answer": "Yes", "solution": "All three corresponding side ratios are 2 (SSS similarity).", "topic": "geo"}, {"id": "VM-Y10-GEO-009", "skill": "Angles", "difficulty": "medium", "question": "One triangle has angles 40° and 65°. Another has angles 75° and 40°. Are they similar?", "answer": "Yes", "solution": "The missing angles are 75° and 65°; AA similarity.", "topic": "geo"}, {"id": "VM-Y10-GEO-010", "skill": "Counterexample", "difficulty": "medium", "question": "Are all rhombuses similar? Give a reason.", "answer": "No", "solution": "A square and a rhombus with a 60° angle have different corresponding angles.", "topic": "geo"}, {"id": "VM-Y10-GEO-011", "skill": "Area ratio", "difficulty": "hard", "question": "Similar triangles have corresponding sides in ratio 2:5. The smaller area is 24 cm². Find larger area.", "answer": "150 cm²", "solution": "24 × (5/2)² = 150.", "topic": "geo"}, {"id": "VM-Y10-GEO-012", "skill": "Perimeter", "difficulty": "medium", "question": "Two similar polygons have perimeters 18 cm and 30 cm. A side of the larger is 10 cm. Find corresponding smaller side.", "answer": "6 cm", "solution": "10 × 18/30 = 6.", "topic": "geo"}, {"id": "VM-Y10-GEO-013", "skill": "Scale drawing", "difficulty": "medium", "question": "A 7.2 m wall is drawn as 9 cm. Find the scale in the form 1:n.", "answer": "1:80", "solution": "720 ÷ 9 = 80.", "topic": "geo"}, {"id": "VM-Y10-GEO-014", "skill": "Error analysis", "difficulty": "medium", "question": "A student claims two triangles are similar because one pair of angles is equal. Explain why this is insufficient.", "answer": "One angle alone does not fix the shape.", "solution": "For example, triangles with angles 60°,60°,60° and 60°,40°,80° share one angle but are not similar.", "topic": "geo"}, {"id": "VM-Y10-GEO-016", "skill": "Reverse reasoning", "difficulty": "hard", "question": "A photo is 15 cm by 10 cm. It must fit within a 24 cm by 18 cm frame without distortion. Find the largest possible dimensions. Scale uniformly without cropping, keeping the photo aligned with the frame.", "answer": "24 cm by 16 cm", "solution": "Maximum scale factor is min(24/15,18/10) = 1.6.", "topic": "geo"}, {"id": "VM-Y10-GEO-018", "skill": "Counterexample", "difficulty": "hard", "question": "Can two isosceles triangles with equal perimeters fail to be similar?", "answer": "Yes", "solution": "Sides 5,5,6 and 6,6,4 both total 16 but corresponding ratios differ.", "topic": "geo"}, {"id": "VM-Y10-GEO-019", "skill": "Scale construction", "difficulty": "medium", "question": "A room is 4.8 m by 3.6 m. Draw a scale plan at 1:60 and label the dimensions.", "answer": "8 cm by 6 cm", "solution": "Convert to centimetres and divide both dimensions by 60.", "topic": "geo"}, {"id": "VM-Y10-GEO-020", "skill": "Correspondence reasoning", "difficulty": "hard", "question": "Triangle ABC has sides AB=4, BC=6, AC=8. A similar triangle has shortest side 10. Find its longest side.", "answer": "20", "solution": "Scale factor 10/4 = 2.5; multiply 8 by 2.5.", "topic": "geo"}, {"id": "VM-Y10-GEO-021", "skill": "Area interpretation", "difficulty": "hard", "question": "A map is enlarged on a photocopier to 150% of its original length. What happens to the area of a region on the map? The enlargement is uniform in both dimensions.", "answer": "It becomes 225% of the original", "solution": "Area multiplier = 1.5² = 2.25.", "topic": "geo"}, {"id": "VM-Y10-GEO-022", "skill": "Indirect measurement", "difficulty": "hard", "question": "A 2 m vertical staff and a building cast shadows of 1.6 m and 12 m on level ground at the same time. Explain the similarity assumption.", "answer": "Parallel sun rays and vertical objects give equal corresponding angles", "solution": "Both triangles are right-angled and have equal sun elevation angles; AA applies.", "topic": "geo"}, {"id": "VM-Y10-GEO-023", "skill": "Matching order", "difficulty": "easy", "question": "Given ABCD ∼ WXYZ, which angle corresponds to angle C?", "answer": "Angle Y", "solution": "Match the third vertices in the statements.", "topic": "geo"}, {"id": "VM-Y10-GEO-024", "skill": "Proportional sides", "difficulty": "medium", "question": "Two similar pentagons have corresponding sides 8 cm and 12 cm. A different side of the larger pentagon is 18 cm. Find its counterpart.", "answer": "12 cm", "solution": "Scale factor small to large = 1.5; 18 ÷ 1.5 = 12.", "topic": "geo"}, {"id": "VM-Y10-GEO-025", "skill": "Scale selection", "difficulty": "hard", "question": "A building 24 m wide must fit on a drawing with maximum width 18 cm. Which scale fits: 1:100 or 1:200?", "answer": "1:200", "solution": "2400 cm ÷ 100 = 24 cm; ÷ 200 = 12 cm.", "topic": "geo"}, {"id": "VM-Y10-GEO-026", "skill": "Shape reasoning", "difficulty": "easy", "question": "Are all squares similar, regardless of size?", "answer": "Yes", "solution": "All angles are right angles and corresponding side ratios are constant.", "topic": "geo"}, {"id": "VM-Y10-GEO-027", "skill": "Similarity counterexample", "difficulty": "challenge", "question": "Two rhombuses each have side length 5 cm. Must they be similar? Justify.", "answer": "No", "solution": "One can have angles 60° and 120°, another 90° throughout; corresponding angles differ.", "topic": "geo"}, {"id": "VM-Y10-GEO-028", "skill": "Scale accuracy", "difficulty": "medium", "question": "A map at scale 1:5000 is printed at half its original linear size. What is its new scale?", "answer": "1:10000", "solution": "Each printed length halves while the actual distance stays unchanged.", "topic": "geo"}, {"id": "VM-Y10-GEO-029", "skill": "Correspondence", "difficulty": "easy", "question": "Triangles ABC and DEF are similar in that order. Which side corresponds to BC?", "answer": "EF", "solution": "Match B with E and C with F.", "topic": "geo"}, {"id": "VM-Y10-GEO-030", "skill": "Scale factor", "difficulty": "easy", "question": "A drawing is enlarged by scale factor 1.5. What happens to a 60° angle?", "answer": "It remains 60°", "solution": "Enlargement preserves angle measures.", "topic": "geo"}, {"id": "VM-Y10-GEO-031", "skill": "Similarity reasoning", "difficulty": "challenge", "question": "Two rectangles have equal perimeters. Must they be similar? Give a counterexample.", "answer": "No; 2 by 6 and 3 by 5", "solution": "Both perimeters are 16, but their side ratios differ.", "topic": "geo"}, {"id": "VM-Y10-GEO-032", "skill": "Scale composition", "difficulty": "challenge", "question": "A shape is enlarged by factor 4/3 and then reduced by factor 3/5. Find the overall scale factor and classify the result.", "answer": "4/5; reduction", "solution": "Multiply the scale factors: (4/3)(3/5) = 4/5.", "topic": "geo"}, {"id": "VM-Y10-GEO-033", "skill": "Diagram correspondence", "difficulty": "easy", "question": "Triangles ABC and PQR are similar in that order. Which side corresponds to AC?", "answer": "PR", "solution": "A corresponds to P and C to R.", "topic": "geo"}, {"id": "VM-Y10-GEO-034", "skill": "Scale plan", "difficulty": "medium", "question": "On a plan drawn at 1:250, a rectangular room is 2.4 cm by 1.6 cm. Find its actual floor area.", "answer": "24 m²", "solution": "Actual dimensions are 600 cm and 400 cm, or 6 m and 4 m. Area = 24 m².", "topic": "geo"}, {"id": "VM-Y10-GEO-035", "skill": "Parallel section", "difficulty": "hard", "question": "In triangle ABC, D lies on AB and E lies on AC, with DE parallel to BC. AD = 4 cm, DB = 6 cm and BC = 15 cm. Find DE and justify.", "answer": "6 cm", "solution": "Triangles ADE and ABC are similar by AA. DE/BC = AD/AB = 4/10, so DE = 6.", "topic": "geo"}, {"id": "VM-Y10-GEO-036", "skill": "Distorted map", "difficulty": "challenge", "question": "A map is stretched horizontally by factor 2 but vertically by factor 1.5. Explain whether a square region on the original map remains similar to its image.", "answer": "No", "solution": "Its image has side ratio 2:1.5 = 4:3 rather than 1:1, so corresponding sides are not proportional.", "topic": "geo"}, {"id": "VM-Y10-GEO-037", "skill": "Photo enlargement", "difficulty": "medium", "question": "A 12 cm by 18 cm photograph is enlarged without distortion to a width of 30 cm, corresponding to its original 12 cm side. Will it fit a 30 cm by 40 cm frame?", "answer": "No", "solution": "Scale factor = 30/12 = 2.5; other side = 18 × 2.5 = 45 cm.", "topic": "geo"}, {"id": "VM-Y10-GEO-038", "skill": "Shadow measurement", "difficulty": "hard", "question": "At the same instant a 1.5 m stick casts a 2 m shadow and a tree casts a 14 m shadow on level ground. Estimate the tree height and state an assumption.", "answer": "10.5 m; parallel sunlight and vertical objects", "solution": "Similar triangles give h/14 = 1.5/2, hence h = 10.5.", "topic": "geo"}, {"id": "VM-Y10-GEO-039", "skill": "Map error", "difficulty": "hard", "question": "On a 1:25000 map, a route measures 7.2 cm. A student reports 18 km. Explain the error and give the correct distance.", "answer": "1.8 km", "solution": "7.2 × 25000 = 180000 cm = 1800 m = 1.8 km; the conversion was off by a factor of ten.", "topic": "geo"}, {"id": "VM-Y10-GEO-040", "skill": "Similarity decision", "difficulty": "challenge", "question": "Two triangles have side lengths 6, 8, 10 and 9, 12, 16. A student claims they are similar because two side ratios match. Is the claim valid?", "answer": "No", "solution": "9/6 = 12/8 = 1.5 but 16/10 = 1.6. All three corresponding ratios must agree for SSS similarity.", "topic": "geo"}, {"id": "VM-Y10-GEO-041", "skill": "Angle correspondence", "difficulty": "easy", "question": "Triangles ABC and DEF are similar in that order. Which angle corresponds to angle B?", "answer": "Angle E", "solution": "Corresponding vertices occupy the same position in the naming order.", "topic": "geo"}, {"id": "VM-Y10-GEO-042", "skill": "Scale interpretation", "difficulty": "easy", "question": "A model is drawn at scale 1:5. Is it larger or smaller than the actual object?", "answer": "Smaller", "solution": "One unit on the model represents five units on the object.", "topic": "geo"}, {"id": "VM-Y10-GEO-043", "skill": "Similarity rejection", "difficulty": "medium", "question": "Two rectangles measure 4 cm by 6 cm and 8 cm by 10 cm. Are they similar?", "answer": "No", "solution": "The side ratios are 8 ÷ 4 = 2 and 10 ÷ 6 = 5/3, which differ.", "topic": "geo"}, {"id": "VM-Y10-GEO-044", "skill": "Unknown corresponding side", "difficulty": "medium", "question": "Two similar triangles have corresponding sides 9 cm and 15 cm. Another side of the larger triangle is 20 cm. Find its corresponding smaller side.", "answer": "12 cm", "solution": "Multiply 20 by 9/15 to obtain 12.", "topic": "geo"}, {"id": "VM-Y10-GEO-045", "skill": "Correspondence", "difficulty": "easy", "question": "Triangles ABC and DEF are similar in that order. Which angle corresponds to angle BCA?", "answer": "Angle EFD", "solution": "C corresponds to F, B to E and A to D.", "topic": "geo"}, {"id": "VM-Y10-GEO-046", "skill": "Scale comparison", "difficulty": "medium", "question": "A 12 cm drawing is reduced to 9 cm. A different line on the original is 20 cm. Find its reduced length.", "answer": "15 cm", "solution": "Scale factor = 9 ÷ 12 = 0.75; multiply 20 by 0.75.", "topic": "geo"}, {"id": "VM-Y10-GEO-047", "skill": "Similarity test", "difficulty": "hard", "question": "Two triangles have side lengths 4, 6, 8 and 6, 9, 11. Are they similar? Justify.", "answer": "No", "solution": "The first two ratios are 1.5 but 11 ÷ 8 = 1.375; sides are not proportional.", "topic": "geo"}, {"id": "VM-Y10-GEO-048", "skill": "Scale reasoning", "difficulty": "challenge", "question": "Two similar triangles have perimeters 24 cm and 36 cm. The smaller has area 32 cm². Find the larger area.", "answer": "72 cm²", "solution": "Linear scale = 36 ÷ 24 = 1.5; area scale = 1.5² = 2.25; 32 × 2.25 = 72.", "topic": "geo"}, {"id": "VM-Y10-GEO-049", "skill": "Scale notation", "difficulty": "easy", "question": "A plan uses scale 1:50. What actual length does 2 cm represent?", "answer": "1 m", "solution": "2 × 50 = 100 cm = 1 m.", "topic": "geo"}, {"id": "VM-Y10-GEO-050", "skill": "Similarity orientation", "difficulty": "medium", "question": "A triangle is rotated 90° and then enlarged by factor 3. What happens to its angles and perimeter?", "answer": "Angles unchanged; perimeter triples", "solution": "Rotation preserves lengths and angles; enlargement preserves angles and triples lengths.", "topic": "geo"}, {"id": "VM-Y10-GEO-051", "skill": "Similarity obstruction", "difficulty": "hard", "question": "Two triangles have side lengths 4, 6, 8 and 6, 9, 13. Explain why matching the two shorter sides is insufficient to establish similarity.", "answer": "They are not similar", "solution": "The first two ratios are 1.5, but 13 ÷ 8 = 1.625. All corresponding side ratios must agree for SSS similarity.", "topic": "geo"}, {"id": "VM-Y10-GEO-052", "skill": "Scale recovery", "difficulty": "challenge", "question": "A map is photocopied at 80% of its original linear size. Its original scale was 1:2000. What is the new scale?", "answer": "1:2500", "solution": "A new 1 cm represents 1 ÷ 0.8 = 1.25 original cm, corresponding to 2500 actual cm.", "topic": "geo"}, {"id": "VM-Y10-GEO-053", "skill": "Angle sum correspondence", "difficulty": "easy", "question": "Two similar triangles have angles 35° and 75° in the first triangle. Find the third angle in the second triangle.", "answer": "70°", "solution": "The third angle is 180−35−75=70°, and corresponding angles are equal.", "topic": "geo"}, {"id": "VM-Y10-GEO-054", "skill": "Scale bar", "difficulty": "medium", "question": "A map scale bar of 4 cm represents 600 m. A route measures 7 cm on the same map. Find the actual distance.", "answer": "1050 m", "solution": "Each centimetre represents 150 m; multiply by 7.", "topic": "geo"}, {"id": "VM-Y10-GEO-055", "skill": "Similarity and perimeter", "difficulty": "hard", "question": "Two similar triangles have perimeters 24 cm and 36 cm. The smaller triangle has a longest side of 10 cm. Find the longest side of the larger triangle.", "answer": "15 cm", "solution": "The linear scale factor is 36÷24=1.5. Multiply 10 by 1.5.", "topic": "geo"}, {"id": "VM-Y10-GEO-056", "skill": "Equal area counterexample", "difficulty": "challenge", "question": "Give two non-similar rectangles with equal area and explain why they are not similar.", "answer": "2 by 12 and 4 by 6.", "solution": "Both areas are 24, but their longer-to-shorter side ratios are 6 and 1.5, so they are not similar.", "topic": "geo"}, {"id": "VM-Y10-GEO-057", "skill": "Scale direction", "difficulty": "easy", "question": "A drawing uses scale 2:1. Is the drawing larger or smaller than the object?", "answer": "Larger", "solution": "Two units on the drawing represent one unit on the object.", "topic": "geo"}, {"id": "VM-Y10-GEO-058", "skill": "Correspondence order", "difficulty": "medium", "question": "Triangles ABC and PQR are similar in that order. If angle B is 72° and angle P is 41°, find angle R.", "answer": "67°", "solution": "Angle Q = angle B = 72°. Angle R = 180 − 72 − 41.", "topic": "geo"}, {"id": "VM-Y10-GEO-059", "skill": "Similarity from parallel lines", "difficulty": "hard", "question": "In triangle ABC, D lies on AB and E on AC, with DE parallel to BC. AD = 6, DB = 4 and AC = 15. Find EC.", "answer": "6 units", "solution": "Triangles ADE and ABC are similar by AA. AE = 15 × 6/10 = 9; EC = 15 − 9.", "topic": "geo"}, {"id": "VM-Y10-GEO-060", "skill": "Scale distortion test", "difficulty": "challenge", "question": "A rectangular map image is stretched from 12 cm by 8 cm to 18 cm by 10 cm. Can a single new scale accurately describe distances in every direction?", "answer": "No", "solution": "Horizontal multiplier is 1.5; vertical multiplier is 1.25. Unequal multipliers distort similarity.", "topic": "geo"}, {"id": "VM-Y10-GEO-061", "skill": "Corresponding vertices", "difficulty": "easy", "question": "Triangle ABC is similar to triangle QRP in that order. Which side corresponds to BC?", "answer": "RP", "solution": "B corresponds to R and C to P.", "topic": "geo"}, {"id": "VM-Y10-GEO-062", "skill": "Scale bar recovery", "difficulty": "medium", "question": "A map has scale 1:25000. How long should a scale bar representing 1 km be on the map?", "answer": "4 cm", "solution": "1 km = 100000 cm; divide by 25000.", "topic": "geo"}, {"id": "VM-Y10-GEO-063", "skill": "Similarity justification", "difficulty": "hard", "question": "In triangle ABC, D lies on AB and E on AC, with DE parallel to BC. Explain why AD/AB = AE/AC.", "answer": "Triangles ADE and ABC are similar by AA.", "solution": "Angle A is common; corresponding angles at D and B are equal because DE is parallel to BC. Corresponding sides are proportional.", "topic": "geo"}, {"id": "VM-Y10-GEO-064", "skill": "Ambiguous scale", "difficulty": "challenge", "question": "Two rectangles have equal diagonals of 10 cm. One is 6 cm by 8 cm and the other is a square. Are they similar? Justify.", "answer": "No", "solution": "The square has side ratio 1:1, whereas the rectangle has ratio 3:4. Equal diagonals do not establish similarity.", "topic": "geo"}, {"id": "VM-Y10-GEO-065", "skill": "Similarity orientation", "difficulty": "easy", "question": "Two identical triangles are mirror images. Are they similar?", "answer": "Yes.", "solution": "Reflection preserves all angles and side lengths, so the scale factor is 1.", "topic": "geo"}, {"id": "VM-Y10-GEO-066", "skill": "Scale conversion", "difficulty": "medium", "question": "A plan uses 1 cm to represent 2.5 m. Express its scale as a ratio using the same units.", "answer": "1:250", "solution": "2.5 m = 250 cm.", "topic": "geo"}, {"id": "VM-Y10-GEO-067", "skill": "Similarity sufficiency", "difficulty": "hard", "question": "Two triangles each have angles 35° and 75°. Must their third angles match, and must the triangles be similar?", "answer": "Yes; yes.", "solution": "The third angle is 70° in both triangles. Equal corresponding angles establish similarity.", "topic": "geo"}, {"id": "VM-Y10-GEO-068", "skill": "Scale drawing inconsistency", "difficulty": "challenge", "question": "A rectangular room is 4 m by 6 m. A drawing shows it as 8 cm by 11.8 cm. Can one exact uniform scale explain both dimensions?", "answer": "No.", "solution": "The first dimension gives 1:50; the second gives 11.8:600, which is not 1:50. At 1:50 the longer side should be 12 cm.", "topic": "geo"}, {"id": "VM-Y10-GEO-069", "skill": "Corresponding angles", "difficulty": "easy", "question": "Triangles ABC and PQR are similar in that order. Which angle corresponds to angle B?", "answer": "Angle Q", "solution": "The second vertices correspond.", "topic": "geo"}, {"id": "VM-Y10-GEO-070", "skill": "Scale drawing", "difficulty": "medium", "question": "A plan uses scale 1:250. A path measures 7.2 cm on the plan. Find its actual length in metres.", "answer": "18 m", "solution": "7.2 × 250 = 1800 cm = 18 m.", "topic": "geo"}, {"id": "VM-Y10-GEO-071", "skill": "Similarity construction", "difficulty": "hard", "question": "A triangle has sides 5, 7 and 9 cm. A similar triangle has perimeter 63 cm. Find its longest side.", "answer": "27 cm", "solution": "Original perimeter = 21; scale factor = 3; longest side = 27.", "topic": "geo"}, {"id": "VM-Y10-GEO-072", "skill": "Similarity counterexample", "difficulty": "challenge", "question": "Two rectangles have the same diagonal length. Must they be similar? Give a numerical counterexample.", "answer": "No; 3 × 4 and 1 × √24", "solution": "Both diagonals equal 5 by Pythagoras, but their side ratios differ.", "topic": "geo"}, {"id": "VM-Y10-GEO-073", "skill": "Scale factor direction", "difficulty": "easy", "question": "A drawing is transformed by scale factor 0.6. Is the image larger or smaller than the original?", "answer": "Smaller", "solution": "A positive scale factor below 1 reduces lengths.", "topic": "geo"}, {"id": "VM-Y10-GEO-074", "skill": "Correspondence", "difficulty": "medium", "question": "Similar triangles ABC and PQR have AB = 6 cm, BC = 9 cm and PQ = 10 cm. Find QR.", "answer": "15 cm", "solution": "Corresponding sides have factor 10/6; QR = 9 × 10/6.", "topic": "geo"}, {"id": "VM-Y10-GEO-075", "skill": "Angle criterion", "difficulty": "medium", "question": "Two triangles each have angles 42° and 68°. Explain why they are similar.", "answer": "AA similarity", "solution": "Two corresponding angles agree; the third must also agree because angles sum to 180°.", "topic": "geo"}, {"id": "VM-Y10-GEO-076", "skill": "Scale consistency", "difficulty": "hard", "question": "A model bridge is 36 cm long and 9 cm high. The real bridge is 48 m long and 12 m high. Determine whether the model is uniformly scaled and give its scale.", "answer": "Yes; 3:400", "solution": "Convert to cm: 36:4800 and 9:1200 both simplify to 3:400.", "topic": "geo"}, {"id": "VM-Y10-GEO-077", "skill": "Scale direction", "difficulty": "easy", "question": "A scale drawing uses 1 cm to represent 2 m. Does a 3 cm line represent 6 m or 1.5 m?", "answer": "6 m", "solution": "Multiply 3 by 2.", "topic": "geo"}, {"id": "VM-Y10-GEO-078", "skill": "Similarity criterion", "difficulty": "medium", "question": "Two triangles have sides 5, 12, 13 and 10, 24, 25. Is SSS similarity established?", "answer": "No", "solution": "The first two ratios are 2 but 25/13 is not 2.", "topic": "geo"}, {"id": "VM-Y10-GEO-079", "skill": "Missing angle", "difficulty": "medium", "question": "Two similar triangles have corresponding vertices A and P. Angle A is 73°. Find angle P and explain.", "answer": "73°", "solution": "Corresponding angles of similar figures are equal.", "topic": "geo"}, {"id": "VM-Y10-GEO-080", "skill": "Scale consistency", "difficulty": "hard", "question": "A rectangular image is 15 cm wide and 10 cm high. A resized version is 21 cm wide and 15 cm high. How much should its height change to preserve similarity at the new width?", "answer": "Decrease by 1 cm", "solution": "Width multiplier = 21/15 = 1.4. Required height = 14 cm.", "topic": "geo"}, {"skill": "Correspondence", "difficulty": "easy", "question": "A pentagon is enlarged by factor 3. What happens to its perimeter?", "answer": "It triples", "solution": "All side lengths are multiplied by 3.", "id": "VM-Y10-GEO-081", "topic": "geo"}, {"id": "VM-Y10-GEO-082", "skill": "Scale perimeter", "difficulty": "medium", "question": "Two similar polygons have corresponding sides 8 cm and 12 cm. The smaller perimeter is 36 cm. Find the larger perimeter.", "answer": "54 cm", "solution": "Linear scale factor = 12 ÷ 8 = 1.5; 36 × 1.5 = 54.", "topic": "geo"}, {"id": "VM-Y10-GEO-083", "skill": "Similarity evidence", "difficulty": "medium", "question": "One triangle has angles 38° and 72°. Another has angles 70° and 38°. Explain whether they are similar.", "answer": "Yes", "solution": "The missing angles are 70° and 72° respectively; both have the same angles.", "topic": "geo"}, {"id": "VM-Y10-GEO-084", "skill": "Scale drawing correction", "difficulty": "hard", "question": "A plan at scale 1:200 is printed at 125% of its original size. What is the new scale?", "answer": "1:160", "solution": "Each printed length becomes 1.25 times larger, so 200 ÷ 1.25 = 160.", "topic": "geo"}, {"skill": "Similarity meaning", "difficulty": "easy", "question": "Two similar polygons have corresponding angles of 112° and x°. Find x.", "answer": "112°", "solution": "Corresponding angles of similar figures are equal.", "id": "VM-Y10-GEO-085", "topic": "geo"}, {"skill": "Scale perimeter", "difficulty": "medium", "question": "A model has perimeter 36 cm and is enlarged by scale factor 2.5. Find the enlarged perimeter.", "answer": "90 cm", "solution": "All lengths scale by 2.5, so 36 × 2.5 = 90.", "id": "VM-Y10-GEO-086", "topic": "geo"}, {"skill": "Similarity test", "difficulty": "hard", "question": "Triangle A has sides 6, 8 and 10 cm. Triangle B has sides 9, 12 and 16 cm. Explain why they are not similar.", "answer": "The side ratios are not all equal", "solution": "9/6 = 12/8 = 1.5 but 16/10 = 1.6.", "id": "VM-Y10-GEO-087", "topic": "geo"}, {"skill": "Parallel segments", "difficulty": "hard", "question": "In triangle ABC, D lies on AB and E on AC, with DE parallel to BC. AD = 8 cm, DB = 4 cm and BC = 15 cm. Find DE and justify the method.", "answer": "10 cm", "solution": "Triangles ADE and ABC are similar by AA. DE/15 = 8/12, so DE = 10.", "id": "VM-Y10-GEO-088", "topic": "geo"}, {"id": "VM-Y10-GEO-089", "skill": "Correspondence", "difficulty": "easy", "question": "Triangles ABC and PQR are similar in order. If angle Q is 70°, which angle in ABC is 70°?", "answer": "Angle B", "solution": "B corresponds to Q.", "topic": "geo"}, {"id": "VM-Y10-GEO-090", "skill": "Scale conversion", "difficulty": "medium", "question": "A floor plan at scale 1:75 is redrawn so every length is 1.5 times its previous size. Find the new scale.", "answer": "1:50", "solution": "Divide 75 by 1.5.", "topic": "geo"}, {"id": "VM-Y10-GEO-091", "skill": "Similarity reasoning", "difficulty": "medium", "question": "Two right triangles each have an acute angle of 37°. Explain why they are similar even if their hypotenuses differ.", "answer": "AA similarity", "solution": "Both have angles 90°, 37° and 53°; equal corresponding angles establish similarity.", "topic": "geo"}, {"id": "VM-Y10-GEO-092", "skill": "Scale reasoning", "difficulty": "hard", "question": "Two similar polygons have corresponding perimeters 36 cm and 60 cm. A side of the larger polygon is 15 cm. Find the corresponding smaller side.", "answer": "9 cm", "solution": "The larger-to-smaller scale factor is 36 ÷ 60 = 0.6. The smaller side is 15 × 0.6 = 9 cm.", "topic": "geo"}, {"id": "VM-Y10-GEO-093", "skill": "Angle property", "difficulty": "easy", "question": "A parallelogram has one interior angle of 112°. Find the adjacent interior angle.", "answer": "68°", "solution": "Adjacent angles are supplementary.", "topic": "geo"}, {"id": "VM-Y10-GEO-095", "skill": "Similarity correspondence", "difficulty": "medium", "question": "Triangles ABC and DEF are similar in that order. AB = 8 cm, BC = 10 cm and DE = 12 cm. Find EF.", "answer": "15 cm", "solution": "Scale factor = 12 ÷ 8 = 1.5; EF = 10 × 1.5.", "topic": "geo"}, {"id": "VM-Y10-GEO-096", "skill": "Quadrilateral counterexample", "difficulty": "medium", "question": "Is every quadrilateral with perpendicular diagonals a square? Give a counterexample.", "answer": "No; a non-square rhombus.", "solution": "A rhombus has perpendicular diagonals but need not have right interior angles.", "topic": "geo"}, {"id": "VM-Y10-GEO-097", "skill": "Exterior angle reasoning", "difficulty": "hard", "question": "A convex polygon has exterior angles all equal to 24°. How many diagonals meet at each vertex?", "answer": "12", "solution": "360 ÷ 24 = 15 vertices; exclude the vertex itself and its two neighbours: 15 − 3.", "topic": "geo"}, {"id": "VM-Y10-GEO-099", "skill": "Similarity property", "difficulty": "easy", "question": "Two similar triangles have corresponding sides in ratio 2:5. What is the ratio of their corresponding angles?", "answer": "1:1", "solution": "Corresponding angles are equal.", "topic": "geo"}, {"id": "VM-Y10-GEO-101", "skill": "Parallel line angles", "difficulty": "medium", "question": "Two parallel lines are cut by a transversal. One co-interior angle is 118°. Find the other.", "answer": "62°", "solution": "Co-interior angles sum to 180°.", "topic": "geo"}, {"id": "VM-Y10-GEO-102", "skill": "Similarity perimeter", "difficulty": "medium", "question": "Similar polygons have perimeters 42 cm and 63 cm. A side of the smaller is 8 cm. Find its corresponding larger side.", "answer": "12 cm", "solution": "Scale factor 63/42 = 1.5; 8 × 1.5 = 12.", "topic": "geo"}, {"id": "VM-Y10-GEO-105", "skill": "Similarity angles", "difficulty": "easy", "question": "A triangle has angles 40° and 65°. Find the third angle in any similar triangle.", "answer": "75°", "solution": "180 − 40 − 65 = 75; similarity preserves angles.", "topic": "geo"}, {"id": "VM-Y10-GEO-107", "skill": "Counterexample", "difficulty": "medium", "question": "Are all rectangles similar? Give a counterexample if not.", "answer": "No; 2 by 3 and 2 by 5 rectangles", "solution": "Their long-to-short side ratios differ.", "topic": "geo"}, {"id": "VM-Y10-GEO-108", "skill": "Scale factor", "difficulty": "medium", "question": "Two similar figures have areas 36 cm² and 81 cm². Find the enlargement factor from smaller to larger.", "answer": "1.5", "solution": "Square root of 81/36 = 1.5.", "topic": "geo"}, {"id": "VM-Y10-GEO-110", "skill": "Similarity reasoning", "difficulty": "hard", "question": "Two triangles have side lengths 5, 12, 13 and 10, 24, 26. Explain why both have a right angle without calculating angles.", "answer": "Both are right triangles", "solution": "5² + 12² = 13² by converse Pythagoras; the second is similar by SSS with factor 2.", "topic": "geo"}, {"id": "VM-Y10-GEO-111", "skill": "Polygon angles", "difficulty": "easy", "question": "Find the sum of interior angles of a heptagon.", "answer": "900°", "solution": "(7 − 2) × 180 = 900.", "topic": "geo"}, {"id": "VM-Y10-GEO-113", "skill": "Similarity ratio", "difficulty": "medium", "question": "Similar triangles have areas 49 cm² and 81 cm². Find the ratio of corresponding side lengths, smaller to larger.", "answer": "7:9", "solution": "Take square roots of 49:81.", "topic": "geo"}, {"id": "VM-Y10-GEO-114", "skill": "Angle reasoning", "difficulty": "medium", "question": "An isosceles triangle has an exterior angle of 112° at its apex. Find each base angle.", "answer": "56°", "solution": "Apex interior = 68°; remaining 112° is split equally.", "topic": "geo"}, {"id": "VM-Y10-GEO-116", "skill": "Diagonal reasoning", "difficulty": "hard", "question": "A quadrilateral has diagonals that bisect each other and are perpendicular. Must it be a square? Justify.", "answer": "No", "solution": "It is a rhombus, but its angles need not be right angles; a non-square rhombus is a counterexample.", "topic": "geo"}, {"id": "VM-Y10-GEO-117", "skill": "Quadrilateral properties", "difficulty": "easy", "question": "Which quadrilateral must have four equal sides but need not have right angles?", "answer": "Rhombus", "solution": "A rhombus has four equal sides; right angles are not required.", "topic": "geo"}, {"id": "VM-Y10-GEO-118", "skill": "Similarity scale", "difficulty": "easy", "question": "Corresponding sides of two similar figures are 14 cm and 21 cm. Find the enlargement scale factor from the smaller to the larger.", "answer": "1.5", "solution": "21 ÷ 14 = 1.5.", "topic": "geo"}, {"id": "VM-Y10-GEO-120", "skill": "Polygon angles", "difficulty": "medium", "question": "Find each interior angle of a regular 15-sided polygon.", "answer": "156°", "solution": "Exterior angle = 360 ÷ 15 = 24°; interior = 180 − 24.", "topic": "geo"}, {"id": "VM-Y10-GEO-121", "skill": "Similarity perimeter", "difficulty": "hard", "question": "Two similar triangles have areas in the ratio 16:81. The smaller perimeter is 28 cm. Find the larger perimeter.", "answer": "63 cm", "solution": "Linear ratio = 4:9; 28 × 9/4 = 63.", "topic": "geo"}, {"id": "VM-Y10-GEO-123", "skill": "Similarity", "difficulty": "easy", "question": "A model is reduced from 15 cm to 9 cm. Find the scale factor from original to model.", "answer": "3/5", "solution": "9/15 simplifies to 3/5.", "topic": "geo"}, {"id": "VM-Y10-GEO-125", "skill": "Parallel lines", "difficulty": "medium", "question": "Two parallel lines are crossed by a transversal. One interior angle is 112°. Find the co-interior angle on the same side.", "answer": "68°", "solution": "Co-interior angles sum to 180°.", "topic": "geo"}, {"id": "VM-Y10-GEO-126", "skill": "Similarity reasoning", "difficulty": "hard", "question": "A 1.8 m pole casts a 2.4 m shadow. At the same instant a tree casts a shadow 10 m longer than the pole shadow. Find the tree height.", "answer": "9.3 m", "solution": "Tree shadow = 12.4 m; height = 12.4 × 1.8/2.4 = 9.3.", "topic": "geo"}, {"id": "VM-Y10-GEO-127", "skill": "Quadrilateral reasoning", "difficulty": "hard", "question": "A parallelogram has adjacent angles in the ratio 4:5. Find all four angles.", "answer": "80°, 100°, 80°, 100°", "solution": "Adjacent angles sum to 180°; one part = 20°; opposite angles equal.", "topic": "geo"}, {"id": "VM-Y10-GEO-128", "skill": "Scale drawing", "difficulty": "medium", "question": "A map uses scale 1:2500. A rectangular playground measures 3 cm by 2 cm on the map. Find its actual perimeter.", "answer": "250 m", "solution": "Actual dimensions 75 m and 50 m; perimeter = 2(75 + 50).", "topic": "geo"}, {"id": "VM-Y10-GEO-129", "skill": "Similarity", "difficulty": "easy", "question": "Two similar triangles have corresponding sides 7 cm and 21 cm. State the enlargement factor.", "answer": "3", "solution": "21÷7=3.", "topic": "geo"}, {"id": "VM-Y10-GEO-130", "skill": "Angle properties", "difficulty": "easy", "question": "One interior angle of a rhombus is 112°. Find an adjacent angle.", "answer": "68°", "solution": "Adjacent angles sum to 180°.", "topic": "geo"}, {"id": "VM-Y10-GEO-132", "skill": "Similarity", "difficulty": "medium", "question": "A scale photograph shows a 2 m door as 5 cm tall. A window appears 3 cm tall in the same plane. Find its actual height.", "answer": "1.2 m", "solution": "The actual-to-image ratio is 2/5 m per cm; 3 × 2/5 = 1.2.", "topic": "geo"}, {"id": "VM-Y10-GEO-133", "skill": "Angle reasoning", "difficulty": "medium", "question": "The exterior angles of a convex pentagon are 65°, 75°, 80°, 90° and x. Find x.", "answer": "50°", "solution": "Exterior angles sum to 360°; subtract 310°.", "topic": "geo"}, {"id": "VM-Y10-GEO-134", "skill": "Quadrilateral properties", "difficulty": "medium", "question": "A parallelogram has diagonals intersecting at O. If AO=7.5 cm, find AC, where A and C are opposite vertices.", "answer": "15 cm", "solution": "Diagonals bisect each other.", "topic": "geo"}, {"id": "VM-Y10-GEO-135", "skill": "Similarity reasoning", "difficulty": "medium", "question": "Two similar polygons have perimeters 45 cm and 75 cm. A side of the larger is 20 cm. Find corresponding smaller side.", "answer": "12 cm", "solution": "Multiply 20 by 45/75.", "topic": "geo"}, {"id": "VM-Y10-GEO-137", "skill": "Similarity", "difficulty": "hard", "question": "In triangle ABC, D lies on AB and E on AC, with DE parallel to BC. AD=6, DB=4 and EC=8 cm. Find AE.", "answer": "12 cm", "solution": "AD/AB=6/10=AE/(AE+8). Solve 10AE=6AE+48.", "topic": "geo"}, {"id": "VM-Y10-GEO-138", "skill": "Angle reasoning", "difficulty": "hard", "question": "A regular polygon has interior angle 165°. How many sides does it have?", "answer": "24", "solution": "Exterior angle 15°; 360/15=24.", "topic": "geo"}, {"id": "VM-Y10-GEO-139", "skill": "Geometric reasoning", "difficulty": "hard", "question": "A quadrilateral has both pairs of opposite sides parallel and equal diagonals. Explain why it is a rectangle.", "answer": "It is a parallelogram with equal diagonals, hence a rectangle.", "solution": "Label vertices ABCD in order. Triangles ABC and BAD are congruent by SSS: AB is common, BC=AD and AC=BD. Thus angles ABC and BAD are equal and supplementary, so both are 90°.", "topic": "geo"}, {"id": "VM-Y10-GEO-140", "skill": "Similarity reasoning", "difficulty": "challenge", "question": "A triangle is cut by a segment parallel to its base. The smaller triangle has one quarter of the area of the remaining trapezium. Find the ratio of the smaller triangle's corresponding side to the original triangle's side.", "answer": "1:√5", "solution": "Small area is 1/5 of total; linear ratio is square root of area ratio.", "topic": "geo"}, {"skill": "Correspondence", "difficulty": "easy", "question": "Similar polygons ABCD and WXYZ are named in corresponding order. Which side matches CD?", "answer": "YZ", "solution": "C matches Y and D matches Z.", "id": "VM-Y10-GEO-R01", "topic": "geo"}, {"skill": "Scale factor", "difficulty": "easy", "question": "A 3 cm side becomes 12 cm. Find the enlargement factor.", "answer": "4", "solution": "12 ÷ 3 = 4.", "id": "VM-Y10-GEO-R02", "topic": "geo"}, {"skill": "Corresponding angles", "difficulty": "easy", "question": "A 112° angle belongs to a polygon enlarged by factor 5. Find the corresponding angle.", "answer": "112°", "solution": "Enlargement preserves angles.", "id": "VM-Y10-GEO-R03", "topic": "geo"}, {"skill": "Scale drawing", "difficulty": "easy", "question": "A plan uses 1 cm for 2 m. What real length is represented by 7 cm?", "answer": "14 m", "solution": "7 × 2 = 14.", "id": "VM-Y10-GEO-R04", "topic": "geo"}, {"skill": "Similarity reasoning", "difficulty": "hard", "question": "A rectangular photo 12 by 18 cm is printed 20 cm wide, with width originally 12 cm. What height avoids distortion?", "answer": "30 cm", "solution": "The common factor is 20 ÷ 12; multiply 18 by it.", "id": "VM-Y10-GEO-R05", "topic": "geo"}, {"skill": "Scale consistency", "difficulty": "hard", "question": "A map shows a 300 m road as 6 cm and a 450 m road as 8 cm. Can both use one scale?", "answer": "No", "solution": "The rates are 50 m/cm and 56.25 m/cm.", "id": "VM-Y10-GEO-R06", "topic": "geo"}, {"skill": "Similarity perimeter", "difficulty": "hard", "question": "Two similar pentagons have perimeters 35 and 56 cm. A small side is 7.5 cm. Find its match.", "answer": "12 cm", "solution": "The scale factor is 56 ÷ 35 = 1.6; 7.5 × 1.6 = 12.", "id": "VM-Y10-GEO-R07", "topic": "geo"}, {"skill": "Scale construction", "difficulty": "hard", "question": "A 9 m by 6 m room must fit on a 12 cm by 8 cm sheet. Find the largest uniform scale as 1:n.", "answer": "1:75", "solution": "900 ÷ 12 = 75 and 600 ÷ 8 = 75.", "id": "VM-Y10-GEO-R08", "topic": "geo"}, {"skill": "Angle reasoning", "difficulty": "hard", "question": "A similar quadrilateral has three angles 80°, 95°, 110°. Find the fourth angle in its enlargement.", "answer": "75°", "solution": "360 − 80 − 95 − 110 = 75; angles are preserved.", "id": "VM-Y10-GEO-R09", "topic": "geo"}, {"skill": "Scale conversion", "difficulty": "hard", "question": "A drawing at 1:200 is photocopied at 80% of its original size. Find the new scale.", "answer": "1:250", "solution": "A new 0.8 cm represents 200 cm; 200 ÷ 0.8 = 250.", "id": "VM-Y10-GEO-R10", "topic": "geo"}, {"skill": "Similarity reasoning", "difficulty": "hard", "question": "A model has corresponding sides 4, 6, 9 cm. A proposed enlargement has 10, 15, 23 cm. Identify and correct the inconsistent side.", "answer": "23 cm should be 22.5 cm", "solution": "First two ratios are 2.5; 9 × 2.5 = 22.5.", "id": "VM-Y10-GEO-R11", "topic": "geo"}, {"skill": "Scale reasoning", "difficulty": "hard", "question": "Two plans of one building use scales 1:50 and 1:125. A wall measures 15 cm on the first. Find its length on the second.", "answer": "6 cm", "solution": "Actual length 750 cm; divide by 125.", "id": "VM-Y10-GEO-R12", "topic": "geo"}, {"skill": "Similarity correspondence", "difficulty": "hard", "question": "Similar hexagons have corresponding side ratio 3:5. The larger perimeter exceeds the smaller by 24 cm. Find both perimeters.", "answer": "36 cm and 60 cm", "solution": "Two ratio units equal 24; one unit is 12.", "id": "VM-Y10-GEO-R13", "topic": "geo"}, {"skill": "Scale interpretation", "difficulty": "hard", "question": "A scale bar marked 40 km measures 5 cm. After resizing it measures 2 cm. A route now measures 7 cm. Find its length.", "answer": "140 km", "solution": "New rate is 20 km/cm; 7 × 20 = 140.", "id": "VM-Y10-GEO-R14", "topic": "geo"}, {"skill": "Similarity reasoning", "difficulty": "challenge", "question": "A poster is enlarged by 25% then reduced by 20%. Explain the final dimensions.", "answer": "Unchanged", "solution": "The combined factor is 1.25 × 0.8 = 1.", "id": "VM-Y10-GEO-R15", "topic": "geo"}, {"skill": "Scale plan", "difficulty": "challenge", "question": "A 24 m by 15 m site must fit within 18 cm by 12 cm. Choose the largest drawing from scales 1:100, 1:150, 1:200.", "answer": "1:150", "solution": "At 1:100 width is 24 cm; at 1:150 dimensions are 16 cm by 10 cm; 1:200 is smaller.", "id": "VM-Y10-GEO-R16", "topic": "geo"}, {"id": "VM-Y10-LIN-001", "skill": "Interpretation", "difficulty": "easy", "question": "State the gradient and vertical intercept of y = −3x + 7.", "answer": "−3 and 7", "solution": "Compare with y = mx + b.", "topic": "lin"}, {"id": "VM-Y10-LIN-002", "skill": "Equation", "difficulty": "easy", "question": "A line rises 2 units for every 5 units right and crosses the vertical axis at −4. Write its equation.", "answer": "y = (2/5)x − 4", "solution": "Gradient = rise ÷ run = 2/5; intercept = −4.", "topic": "lin"}, {"id": "VM-Y10-LIN-003", "skill": "Graphing", "difficulty": "medium", "question": "Give three points to plot y = 2x − 3, including its vertical intercept.", "answer": "(0,−3), (1,−1), (2,1)", "solution": "Substitute x = 0, 1, 2.", "topic": "lin"}, {"id": "VM-Y10-LIN-004", "skill": "Context", "difficulty": "medium", "question": "A taxi charges $6 plus $2.50 per kilometre. Explain both coefficients in C = 2.5d + 6.", "answer": "$2.50 per km; $6 fixed charge", "solution": "The gradient is the rate of change; the intercept is the cost at zero distance.", "topic": "lin"}, {"id": "VM-Y10-LIN-005", "skill": "Parallel lines", "difficulty": "medium", "question": "Find the line parallel to y = 4x − 1 through (2,9).", "answer": "y = 4x + 1", "solution": "Same gradient; 9 = 8 + b, so b = 1.", "topic": "lin"}, {"id": "VM-Y10-LIN-006", "skill": "Perpendicular lines", "difficulty": "hard", "question": "Find the line perpendicular to y = −2x + 3 through (4,0).", "answer": "y = x/2 − 2", "solution": "Negative reciprocal gradient is 1/2; 0 = 2 + b.", "topic": "lin"}, {"id": "VM-Y10-LIN-007", "skill": "Gradient", "difficulty": "easy", "question": "Find the gradient of the line through (−2, 5) and (4, 2).", "answer": "−1/2", "solution": "(2 − 5) ÷ (4 − (−2)) = −3/6.", "topic": "lin"}, {"id": "VM-Y10-LIN-008", "skill": "Intercepts", "difficulty": "medium", "question": "Find both axis intercepts of 3x + 2y = 12.", "answer": "(4,0), (0,6)", "solution": "Set y = 0, then x = 0.", "topic": "lin"}, {"id": "VM-Y10-LIN-009", "skill": "Vertical lines", "difficulty": "easy", "question": "Write the equation of the vertical line through (−3, 8).", "answer": "x = −3", "solution": "Every point on the line has x-coordinate −3.", "topic": "lin"}, {"id": "VM-Y10-LIN-010", "skill": "Collinearity", "difficulty": "hard", "question": "Are (1,2), (3,6) and (5,11) collinear?", "answer": "No", "solution": "Successive gradients are 2 and 2.5, which differ.", "topic": "lin"}, {"id": "VM-Y10-LIN-011", "skill": "Intersection", "difficulty": "medium", "question": "Two water tanks contain 90 − 3t and 30 + 2t litres after t minutes. When are their volumes equal?", "answer": "12 minutes", "solution": "90 − 3t = 30 + 2t, so 5t = 60.", "topic": "lin"}, {"id": "VM-Y10-LIN-012", "skill": "Parameter", "difficulty": "hard", "question": "Find k if the line through (2,k) and (6,10) has gradient 3.", "answer": "−2", "solution": "(10 − k)/4 = 3, so k = −2.", "topic": "lin"}, {"id": "VM-Y10-LIN-013", "skill": "Error analysis", "difficulty": "medium", "question": "A student claims y = 2x + 1 and y = −2x + 5 are perpendicular because their gradients have opposite signs. Explain.", "answer": "They are not perpendicular.", "solution": "Their gradient product is −4, not −1.", "topic": "lin"}, {"id": "VM-Y10-LIN-014", "skill": "Graph interpretation", "difficulty": "medium", "question": "A straight distance–time graph joins (0,20) and (4,8), with distance in km and time in hours. Interpret its gradient.", "answer": "Distance decreases by 3 km per hour.", "solution": "(8 − 20)/4 = −3.", "topic": "lin"}, {"id": "VM-Y10-LIN-015", "skill": "Equation", "difficulty": "medium", "question": "Rewrite 4x − 2y = 10 in gradient-intercept form.", "answer": "y = 2x − 5", "solution": "−2y = 10 − 4x; divide by −2.", "topic": "lin"}, {"id": "VM-Y10-LIN-016", "skill": "Reasoning", "difficulty": "hard", "question": "Can two distinct nonvertical lines have the same gradient and the same vertical intercept?", "answer": "No", "solution": "Both would have identical equations y = mx + b.", "topic": "lin"}, {"id": "VM-Y10-LIN-017", "skill": "Perpendicular bisector", "difficulty": "hard", "question": "Find the perpendicular bisector of the segment joining (2,1) and (8,5).", "answer": "y = −1.5x + 10.5", "solution": "Midpoint (5,3); segment gradient 2/3; perpendicular gradient −3/2. Substitute midpoint.", "topic": "lin"}, {"id": "VM-Y10-LIN-018", "skill": "Tariff design", "difficulty": "hard", "question": "A hire company wants a linear price rule charging $32 for 2 hours and $68 for 5 hours. Find the rule.", "answer": "C = 12h + 8", "solution": "Gradient = (68−32)/3 = 12; intercept = 32−24 = 8.", "topic": "lin"}, {"id": "VM-Y10-LIN-019", "skill": "Graph construction", "difficulty": "hard", "question": "Sketch 2x − y = 4 using its intercepts and mark the region where y is positive along the line.", "answer": "Intercepts (2,0), (0,−4); x > 2", "solution": "Rearrange to y = 2x−4. Positive y requires 2x > 4.", "topic": "lin"}, {"id": "VM-Y10-LIN-020", "skill": "Parameter reasoning", "difficulty": "hard", "question": "For which value of a is ax + 3y = 9 parallel to y = 2x − 7?", "answer": "a = −6", "solution": "Gradient is −a/3; equate to 2.", "topic": "lin"}, {"id": "VM-Y10-LIN-021", "skill": "Intersection design", "difficulty": "hard", "question": "Construct a line with negative gradient that meets y = x + 2 on the vertical axis.", "answer": "Example y = −x + 2", "solution": "Both lines must pass through (0,2); any negative gradient works.", "topic": "lin"}, {"id": "VM-Y10-LIN-022", "skill": "Domain interpretation", "difficulty": "hard", "question": "A candle height is h = 24 − 1.5t cm after t hours. Give a realistic domain.", "answer": "0 ≤ t ≤ 16", "solution": "Time cannot be negative; height reaches zero at 24 ÷ 1.5 = 16.", "topic": "lin"}, {"id": "VM-Y10-LIN-023", "skill": "Intercept meaning", "difficulty": "easy", "question": "A water tank has V = 90 − 3t litres after t minutes. Interpret the vertical intercept.", "answer": "90 litres initially", "solution": "At t = 0, V = 90.", "topic": "lin"}, {"id": "VM-Y10-LIN-024", "skill": "Graph scale", "difficulty": "medium", "question": "A line rises 3 vertical grid squares for every 2 horizontal squares. Each vertical square represents 4 units and each horizontal square 3 units. Find its gradient.", "answer": "2", "solution": "Rise = 12; run = 6; gradient = 12 ÷ 6.", "topic": "lin"}, {"id": "VM-Y10-LIN-025", "skill": "Equation matching", "difficulty": "easy", "question": "Which of y = 4x − 2 and y = −2x + 4 crosses the vertical axis at 4?", "answer": "y = −2x + 4", "solution": "Substitute x = 0 in both equations.", "topic": "lin"}, {"id": "VM-Y10-LIN-026", "skill": "Graph construction", "difficulty": "medium", "question": "Draw y = −3x + 6 using its two axis intercepts. State their coordinates.", "answer": "(0,6), (2,0)", "solution": "Set x = 0, then solve 0 = −3x + 6.", "topic": "lin"}, {"id": "VM-Y10-LIN-027", "skill": "Model constraint", "difficulty": "hard", "question": "A linear model has gradient 2 and passes through (3,7). Can it also pass through (5,12)? Explain.", "answer": "No", "solution": "Its equation is y = 2x + 1; at x = 5, y = 11.", "topic": "lin"}, {"id": "VM-Y10-LIN-028", "skill": "Comparing rates", "difficulty": "challenge", "question": "Two straight lines have equal positive gradients but different vertical intercepts. Can the lower line ever overtake the upper line? Explain.", "answer": "No", "solution": "Their vertical difference is constant for every x.", "topic": "lin"}, {"id": "VM-Y10-LIN-029", "skill": "Intercept interpretation", "difficulty": "easy", "question": "A delivery charge is modelled by C = 7 + 2d, where d is distance in kilometres. What is the fixed charge?", "answer": "$7", "solution": "At d = 0, C = 7.", "topic": "lin"}, {"id": "VM-Y10-LIN-030", "skill": "Horizontal line", "difficulty": "easy", "question": "All points on a line have y-coordinate −4. State its equation.", "answer": "y = −4", "solution": "The y-coordinate is constant regardless of x.", "topic": "lin"}, {"id": "VM-Y10-LIN-031", "skill": "Model construction", "difficulty": "challenge", "question": "A straight line passes through (2, 7) and has an x-intercept of −5. Find its y-intercept.", "answer": "5", "solution": "Gradient = 7 ÷ 7 = 1; y = x + 5.", "topic": "lin"}, {"id": "VM-Y10-LIN-032", "skill": "Constraint reasoning", "difficulty": "challenge", "question": "Can two distinct nonvertical straight lines have the same x-intercept and the same gradient? Explain.", "answer": "No", "solution": "The gradient and one common point determine a unique straight line.", "topic": "lin"}, {"id": "VM-Y10-LIN-033", "skill": "Graph segments", "difficulty": "easy", "question": "A graph joins (0, 4) to (3, 10). How much does y increase for each unit increase in x?", "answer": "2", "solution": "Gradient = (10 − 4) ÷ 3 = 2.", "topic": "lin"}, {"id": "VM-Y10-LIN-034", "skill": "Graph window", "difficulty": "medium", "question": "A line y = 3x − 12 is drawn in a window with 0 ≤ x ≤ 8 and 0 ≤ y ≤ 6. Find the endpoints of its visible segment.", "answer": "(4,0) and (6,6)", "solution": "Set y = 0 and y = 6 to obtain x = 4 and x = 6.", "topic": "lin"}, {"id": "VM-Y10-LIN-035", "skill": "Route graph", "difficulty": "hard", "question": "A cyclist travels 12 km in 40 minutes, stops for 10 minutes, then returns home in 30 minutes. Give the vertices of the distance-from-home graph and the return speed.", "answer": "(0,0), (40,12), (50,12), (80,0); 24 km/h", "solution": "The return takes 0.5 hours, so speed = 12 ÷ 0.5 = 24 km/h.", "topic": "lin"}, {"id": "VM-Y10-LIN-036", "skill": "Feasible intersection", "difficulty": "challenge", "question": "Two hire plans cost A = 18 + 4h and B = 6 + 7h dollars. Hire is available only for whole hours from 1 to 3. Can the plans ever cost the same for an available hire?", "answer": "No", "solution": "Equating gives 12 = 3h, hence h = 4, outside the available domain.", "topic": "lin"}, {"id": "VM-Y10-LIN-037", "skill": "Meeting deadline", "difficulty": "hard", "question": "A courier is 12 km ahead of another courier. They travel in the same direction at 18 and 24 km/h respectively. Will the second catch the first within 90 minutes?", "answer": "No; after 2 hours", "solution": "The gap closes at 6 km/h. Time = 12 ÷ 6 = 2 hours, greater than 1.5 hours.", "topic": "lin"}, {"id": "VM-Y10-LIN-038", "skill": "Coordinate design", "difficulty": "medium", "question": "A straight fence passes through (2, 3) and (8, 6). A gate must be on the fence at x = 5. Find its coordinates.", "answer": "(5, 4.5)", "solution": "Gradient = 3/6 = 0.5. At x = 5, y = 3 + 0.5(5 − 2) = 4.5.", "topic": "lin"}, {"id": "VM-Y10-LIN-039", "skill": "Measurement consistency", "difficulty": "hard", "question": "A sensor is expected to follow a linear rule. It reports (0, 4), (3, 10), (7, 19). Which reading is inconsistent if the first two are correct?", "answer": "(7, 19)", "solution": "The first two give y = 2x + 4. At x = 7 the expected reading is 18.", "topic": "lin"}, {"id": "VM-Y10-LIN-040", "skill": "Integer decision", "difficulty": "challenge", "question": "A hall charges $180 plus $8 per guest. Another charges $300 plus $5 per guest. Find the smallest whole number of guests for which the second hall is cheaper.", "answer": "41", "solution": "300 + 5n < 180 + 8n gives n > 40. The smallest integer is 41.", "topic": "lin"}, {"id": "VM-Y10-LIN-041", "skill": "Point membership", "difficulty": "easy", "question": "Does the point (−2, 7) lie on y = 3 − 2x?", "answer": "Yes", "solution": "Substitute x = −2: 3 − 2(−2) = 7.", "topic": "lin"}, {"id": "VM-Y10-LIN-042", "skill": "Axis crossing", "difficulty": "easy", "question": "A straight line crosses the x-axis at −4. Write the coordinates of this crossing.", "answer": "(−4, 0)", "solution": "Every point on the x-axis has y-coordinate zero.", "topic": "lin"}, {"id": "VM-Y10-LIN-043", "skill": "Missing table entry", "difficulty": "medium", "question": "A linear relationship has y-values 8, 13 and 23 at x = 0, 1 and 3 respectively. Find y at x = 2.", "answer": "18", "solution": "The increase is 5 per unit of x, so y = 13 + 5 = 18.", "topic": "lin"}, {"id": "VM-Y10-LIN-044", "skill": "Coordinate translation", "difficulty": "medium", "question": "A line y = 4x − 1 is shifted vertically down 6 units. Give its new equation and gradient.", "answer": "y = 4x − 7; gradient 4", "solution": "Subtract 6 from every y-value. The gradient does not change.", "topic": "lin"}, {"id": "VM-Y10-LIN-045", "skill": "Intercept meaning", "difficulty": "easy", "question": "A water tank model is V = 90 − 6t, where V is litres and t is minutes. What does 90 represent?", "answer": "Initial volume of 90 L", "solution": "At t = 0, V = 90.", "topic": "lin"}, {"id": "VM-Y10-LIN-046", "skill": "Collinearity", "difficulty": "medium", "question": "Do (1, 4), (3, 10) and (5, 15) lie on one straight line?", "answer": "No", "solution": "Successive gradients are 6 ÷ 2 = 3 and 5 ÷ 2 = 2.5.", "topic": "lin"}, {"id": "VM-Y10-LIN-047", "skill": "Constraint modelling", "difficulty": "hard", "question": "A hall charges $80 plus $12 per guest. A group has $350. Find the greatest whole number of guests it can afford.", "answer": "22", "solution": "12n ≤ 270, so n ≤ 22.5; the greatest integer is 22.", "topic": "lin"}, {"id": "VM-Y10-LIN-048", "skill": "Intersection investigation", "difficulty": "challenge", "question": "Find the value of k for which y = kx + 2 passes through the intersection of y = 2x + 5 and y = −x + 11.", "answer": "3.5", "solution": "Equating gives x = 2, y = 9. Then 9 = 2k + 2, so k = 3.5.", "topic": "lin"}, {"id": "VM-Y10-LIN-049", "skill": "Graph reflection", "difficulty": "medium", "question": "Reflect the line y = 2x + 6 in the y-axis. Give its new equation.", "answer": "y = −2x + 6", "solution": "Reflection replaces x with −x while preserving y.", "topic": "lin"}, {"id": "VM-Y10-LIN-050", "skill": "Unit change", "difficulty": "hard", "question": "A distance graph has equation d = 12t + 3, where d is kilometres and t is hours. Rewrite it with distance in metres and time in minutes.", "answer": "D = 200T + 3000", "solution": "Substitute t = T ÷ 60 and multiply distance by 1000.", "topic": "lin"}, {"id": "VM-Y10-LIN-051", "skill": "Slope sign", "difficulty": "easy", "question": "A line crosses the y-axis at 4 and the x-axis at 8. Is its gradient positive, negative or zero?", "answer": "Negative", "solution": "Moving from (0,4) to (8,0) increases x and decreases y.", "topic": "lin"}, {"id": "VM-Y10-LIN-052", "skill": "Intersection constraint", "difficulty": "challenge", "question": "Find all values of k for which y = kx + 2 and y = 3x + 5 intersect at a positive x-coordinate.", "answer": "k > 3", "solution": "Equating gives (k − 3)x = 3. The quotient is positive exactly when k > 3; k = 3 gives parallel lines.", "topic": "lin"}, {"id": "VM-Y10-LIN-054", "skill": "Axis triangle", "difficulty": "medium", "question": "Find the area enclosed by y = 12 − 3x and the coordinate axes.", "answer": "24 square units", "solution": "Intercepts are (0,12) and (4,0). Area = ½ × 4 × 12 = 24.", "topic": "lin"}, {"id": "VM-Y10-LIN-055", "skill": "Parallel strip", "difficulty": "hard", "question": "The lines y = 2x + 1 and y = 2x + 9 bound a strip. Find the area of the strip between x = 1 and x = 6.", "answer": "40 square units", "solution": "The vertical separation is always 8. The resulting parallelogram has vertical base 8 and perpendicular width 5.", "topic": "lin"}, {"id": "VM-Y10-LIN-056", "skill": "Intercept constraint", "difficulty": "challenge", "question": "A line has positive x- and y-intercepts. Its y-intercept is twice its x-intercept and the triangle it forms with the axes has area 49. Find its equation.", "answer": "y = −2x + 14", "solution": "Let x-intercept be a > 0. Area = ½ × a × 2a = a² = 49, so a=7. The intercepts give gradient −2.", "topic": "lin"}, {"id": "VM-Y10-LIN-057", "skill": "Gradient from displacement", "difficulty": "easy", "question": "A straight line moves 6 units left and 3 units up between two points. Find its gradient.", "answer": "−0.5", "solution": "Gradient = 3 ÷ (−6) = −0.5.", "topic": "lin"}, {"id": "VM-Y10-LIN-058", "skill": "Graph calibration", "difficulty": "medium", "question": "A graph has horizontal grid intervals of 2 units and vertical intervals of 5 units. A line rises three squares for every two squares right. Find its gradient.", "answer": "3.75", "solution": "Rise = 15, run = 4, so gradient = 15 ÷ 4.", "topic": "lin"}, {"id": "VM-Y10-LIN-059", "skill": "Equal distance from axis", "difficulty": "hard", "question": "Find the two points on y = 2x − 6 whose vertical distance from the x-axis is 4 units.", "answer": "(1, −4) and (5, 4)", "solution": "Set y = −4 and y = 4 separately; solve 2x − 6 = ±4.", "topic": "lin"}, {"id": "VM-Y10-LIN-060", "skill": "Line through rectangle", "difficulty": "challenge", "question": "A line of gradient 2 passes through the centre of a rectangle with vertices (0,0), (8,0), (8,6), (0,6). Where does it leave the rectangle?", "answer": "(2.5,0) and (5.5,6)", "solution": "Centre (4,3) gives y = 2x − 5. At y = 0 and 6, x = 2.5 and 5.5, both within the rectangle.", "topic": "lin"}, {"id": "VM-Y10-LIN-061", "skill": "Coordinate membership", "difficulty": "easy", "question": "Which of (−2, 5), (0, 1) and (3, −4) lie on y = 1 − 2x?", "answer": "First two points", "solution": "Substitution gives 5, 1 and −5 respectively.", "topic": "lin"}, {"id": "VM-Y10-LIN-062", "skill": "Graph construction", "difficulty": "medium", "question": "Sketch y = 2x − 3 using its two axis intercepts. State both intercept coordinates.", "answer": "(0, −3), (1.5, 0)", "solution": "Set x = 0 for the vertical intercept; solve 2x − 3 = 0 for the horizontal intercept. Join the points with a straight line.", "topic": "lin"}, {"id": "VM-Y10-LIN-063", "skill": "Unknown endpoint", "difficulty": "hard", "question": "A segment has midpoint (4, −1) and gradient 3. One endpoint has x-coordinate 2. Find both endpoints.", "answer": "(2, −7), (6, 5)", "solution": "The horizontal offsets from the midpoint are −2 and 2. Multiply by 3 for vertical offsets −6 and 6.", "topic": "lin"}, {"id": "VM-Y10-LIN-064", "skill": "Model validity", "difficulty": "challenge", "question": "A taxi model is C = 6 + 2.4d for distance d in kilometres. A passenger pays $18 for a 4 km trip. Can this single observation establish a new per-kilometre rate if the fixed fee may also have changed?", "answer": "No", "solution": "There are two unknowns and one equation: a + 4b = 18. For example a = 6, b = 3 or a = 10, b = 2 both fit.", "topic": "lin"}, {"id": "VM-Y10-LIN-065", "skill": "Gradient invariance", "difficulty": "easy", "question": "A straight line is shifted 4 units to the right without rotation. What happens to its gradient?", "answer": "It stays the same.", "solution": "Translation changes position, not rise divided by run.", "topic": "lin"}, {"id": "VM-Y10-LIN-066", "skill": "Intercept from symmetry", "difficulty": "medium", "question": "A line crosses the x-axis at 6 and the y-axis at 6. Find its equation.", "answer": "y = 6 − x", "solution": "The intercepts are (6,0) and (0,6), so gradient = −1 and y-intercept = 6.", "topic": "lin"}, {"id": "VM-Y10-LIN-067", "skill": "Coordinate locus", "difficulty": "hard", "question": "Find the equation of the line containing all points whose y-coordinate is 3 less than twice their x-coordinate. Does (−2,−7) lie on it?", "answer": "y = 2x − 3; yes.", "solution": "Substitute x = −2: 2(−2) − 3 = −7.", "topic": "lin"}, {"id": "VM-Y10-LIN-068", "skill": "Equal tariffs interval", "difficulty": "challenge", "question": "Two hire plans cost $20 + $4 per hour and $8 + $6 per hour. For whole-hour hires of 1 to 10 hours, list the durations for which the first plan is strictly cheaper.", "answer": "7, 8, 9 and 10 hours.", "solution": "20 + 4h < 8 + 6h gives h > 6; restrict to the stated whole-hour domain.", "topic": "lin"}, {"id": "VM-Y10-LIN-069", "skill": "Discrete domain", "difficulty": "easy", "question": "A ticket booth charges C = 8n + 3 dollars for n tickets. Is n = 2.5 a meaningful input for this model?", "answer": "No", "solution": "Tickets are counted in whole numbers, so the practical domain consists of non-negative integers.", "topic": "lin"}, {"id": "VM-Y10-LIN-070", "skill": "Axis scaling", "difficulty": "medium", "question": "A line rises 3 vertical grid squares for every 2 horizontal squares. Each vertical square represents 10 units and each horizontal square 5 units. Find the gradient.", "answer": "3", "solution": "Rise = 30; run = 10; gradient = 3.", "topic": "lin"}, {"id": "VM-Y10-LIN-071", "skill": "Parallel boundary", "difficulty": "hard", "question": "A straight fence passes through (2, 7) and is parallel to the line 3x + y = 8. Find its equation.", "answer": "y = −3x + 13", "solution": "The gradient is −3. Substitute (2, 7): 7 = −6 + b, so b = 13.", "topic": "lin"}, {"id": "VM-Y10-LIN-072", "skill": "Model comparison", "difficulty": "challenge", "question": "Two linear cost models agree at both 4 items and 11 items. Can they disagree at 20 items if both remain linear? Explain.", "answer": "No", "solution": "Two distinct points determine a unique straight line, so both models have identical gradients and intercepts.", "topic": "lin"}, {"id": "VM-Y10-LIN-073", "skill": "Intercept interpretation", "difficulty": "easy", "question": "A linear model gives a temperature of 18°C at noon and 18°C at 3 pm. What is its hourly rate of change?", "answer": "0°C per hour", "solution": "The temperature change is zero over three hours.", "topic": "lin"}, {"id": "VM-Y10-LIN-074", "skill": "Horizontal line", "difficulty": "easy", "question": "A graph contains (−4, 7), (0, 7) and (5, 7). Write the equation of the straight line through them.", "answer": "y = 7", "solution": "The y-coordinate is constant.", "topic": "lin"}, {"id": "VM-Y10-LIN-075", "skill": "Unit conversion model", "difficulty": "medium", "question": "A taxi fare is C = 5 + 2d with d in kilometres. Rewrite the formula using distance m in metres.", "answer": "C = 5 + 0.002m", "solution": "Substitute d = m ÷ 1000.", "topic": "lin"}, {"id": "VM-Y10-LIN-076", "skill": "Intersection constraint", "difficulty": "hard", "question": "The lines y = 2x + a and y = −x + 9 meet on the y-axis. Find a and the intersection.", "answer": "a = 9; (0, 9)", "solution": "At x = 0 both equations must give 9.", "topic": "lin"}, {"id": "VM-Y10-LIN-077", "skill": "Intercept meaning", "difficulty": "easy", "question": "A graph of remaining phone credit against minutes used crosses the vertical axis at 24. What does 24 represent? Credit is measured in dollars.", "answer": "Initial credit of $24", "solution": "At zero minutes the credit is $24.", "topic": "lin"}, {"id": "VM-Y10-LIN-078", "skill": "Line construction", "difficulty": "medium", "question": "Give an equation for a line with negative gradient that crosses the x-axis at 6 and the y-axis at 3.", "answer": "y = −0.5x + 3", "solution": "Gradient = (0 − 3) ÷ (6 − 0) = −0.5.", "topic": "lin"}, {"id": "VM-Y10-LIN-079", "skill": "Coordinate constraints", "difficulty": "medium", "question": "A point on y = 4x − 1 has equal x- and y-coordinates. Find the point.", "answer": "(1/3, 1/3)", "solution": "Set x = 4x − 1, so 3x = 1.", "topic": "lin"}, {"id": "VM-Y10-LIN-080", "skill": "Parallel model", "difficulty": "hard", "question": "A straight road follows y = 2x + 1 on a coordinate map. A parallel road passes through (4, 3). Find where the second road crosses the x-axis.", "answer": "(2.5, 0)", "solution": "Its equation is y = 2x − 5. Set y = 0.", "topic": "lin"}, {"skill": "Coordinate interpretation", "difficulty": "easy", "question": "A graph of distance against time is horizontal between minutes 4 and 7. What does this indicate?", "answer": "Distance remains constant for three minutes", "solution": "A horizontal segment has zero gradient.", "id": "VM-Y10-LIN-081", "topic": "lin"}, {"id": "VM-Y10-LIN-082", "skill": "Graph scale", "difficulty": "medium", "question": "On a graph each horizontal square represents 2 seconds and each vertical square represents 5 metres. A straight line rises three squares over five squares. Find its gradient in metres per second.", "answer": "1.5 m/s", "solution": "Rise = 15 m; run = 10 s; gradient = 15 ÷ 10.", "topic": "lin"}, {"id": "VM-Y10-LIN-083", "skill": "Missing coefficient", "difficulty": "medium", "question": "The line y = ax + 6 passes through (4, −2). Determine a.", "answer": "−2", "solution": "−2 = 4a + 6, so 4a = −8.", "topic": "lin"}, {"id": "VM-Y10-LIN-084", "skill": "Linear constraints", "difficulty": "hard", "question": "A hall charges a fixed booking fee plus a constant cost per guest. A booking for 30 costs $390 and one for 50 costs $550. What is the largest whole number of guests a $700 budget allows?", "answer": "68", "solution": "Cost per guest = 160 ÷ 20 = 8; fixed fee = 150. 550 ÷ 8 = 68.75, so at most 68.", "topic": "lin"}, {"skill": "Intercept meaning", "difficulty": "easy", "question": "A candle has height h = 18 − 2t centimetres after t hours. What does the vertical intercept represent?", "answer": "Initial height of 18 cm", "solution": "At t = 0, h = 18.", "id": "VM-Y10-LIN-085", "topic": "lin"}, {"skill": "Coordinate translation", "difficulty": "medium", "question": "A straight line passes through (1, 4) and (5, 12). Both points are moved three units to the right. Find the equation of the translated line.", "answer": "y = 2x − 4", "solution": "New points (4,4) and (8,12) give gradient 2 and intercept 4 − 8 = −4.", "id": "VM-Y10-LIN-086", "topic": "lin"}, {"skill": "Linear constraint", "difficulty": "medium", "question": "A line with gradient −3 crosses the x-axis at 7. Find its y-intercept without drawing the graph.", "answer": "21", "solution": "Substitute (7,0) into y = −3x + c: c = 21.", "id": "VM-Y10-LIN-087", "topic": "lin"}, {"skill": "Coordinate area", "difficulty": "hard", "question": "The line y = 12 − 3x and the coordinate axes enclose a triangle. A vertical line x = 2 divides it into two regions. Find the area of the smaller region.", "answer": "6 square units", "solution": "The right triangle has base 4 − 2 = 2 and height 6, giving area 6; the whole area is 24.", "id": "VM-Y10-LIN-088", "topic": "lin"}, {"id": "VM-Y10-LIN-089", "skill": "Horizontal line", "difficulty": "easy", "question": "A graph contains all points whose second coordinate is −4. Write its equation.", "answer": "y = −4", "solution": "The y-coordinate is constant.", "topic": "lin"}, {"id": "VM-Y10-LIN-091", "skill": "Rate units", "difficulty": "medium", "question": "A linear model gives distance in metres as d = 90t + 12, where t is minutes. Rewrite it using seconds s.", "answer": "d = 1.5s + 12", "solution": "t = s ÷ 60; substitute into the model.", "topic": "lin"}, {"id": "VM-Y10-LIN-092", "skill": "Intersection constraint", "difficulty": "hard", "question": "The lines y = 2x + k and y = −x + 9 intersect on the horizontal line y = 5. Find k.", "answer": "−3", "solution": "5 = −x + 9 gives x = 4. Then 5 = 8 + k.", "topic": "lin"}, {"id": "VM-Y10-LIN-093", "skill": "Gradient meaning", "difficulty": "easy", "question": "A water level model is h = 42 − 3t, with h in centimetres and t in minutes. Interpret the coefficient −3.", "answer": "The level falls 3 cm per minute.", "solution": "The coefficient of time is the rate of change.", "topic": "lin"}, {"id": "VM-Y10-LIN-094", "skill": "Intercept constraint", "difficulty": "easy", "question": "A straight line passes through (0, −7). What is its y-intercept?", "answer": "−7", "solution": "At the y-intercept x = 0.", "topic": "lin"}, {"id": "VM-Y10-LIN-096", "skill": "Linear model domain", "difficulty": "medium", "question": "A tank contains V = 180 − 12t litres until empty. State the physically meaningful time interval in minutes.", "answer": "0 ≤ t ≤ 15", "solution": "Require t ≥ 0 and 180 − 12t ≥ 0.", "topic": "lin"}, {"id": "VM-Y10-LIN-097", "skill": "Parallel intercepts", "difficulty": "hard", "question": "Two parallel lines have gradient 2. Their x-intercepts are −3 and 5. Find the vertical separation between them.", "answer": "16 units", "solution": "Their equations are y = 2x + 6 and y = 2x − 10; intercept difference is 16.", "topic": "lin"}, {"id": "VM-Y10-LIN-098", "skill": "Integer constraint", "difficulty": "hard", "question": "A line y = 3x − 8 crosses a rectangle with 0 ≤ x ≤ 6 and 0 ≤ y ≤ 4. Find all integer-coordinate points on the line inside or on the rectangle.", "answer": "(3, 1), (4, 4)", "solution": "0 ≤ 3x − 8 ≤ 4 gives 8/3 ≤ x ≤ 4; integer x values are 3 and 4.", "topic": "lin"}, {"id": "VM-Y10-LIN-099", "skill": "Gradient sign", "difficulty": "easy", "question": "A straight line falls 9 units as x increases by 3. Find its gradient.", "answer": "−3", "solution": "Gradient = −9 ÷ 3.", "topic": "lin"}, {"id": "VM-Y10-LIN-100", "skill": "Horizontal line", "difficulty": "easy", "question": "Write the equation of the horizontal line through (−4, 7).", "answer": "y = 7", "solution": "Every point has y-coordinate 7.", "topic": "lin"}, {"id": "VM-Y10-LIN-101", "skill": "Missing coordinate", "difficulty": "medium", "question": "Points (2, 9) and (6, k) lie on a line of gradient −2. Find k.", "answer": "1", "solution": "k − 9 = −2 × 4 = −8.", "topic": "lin"}, {"id": "VM-Y10-LIN-102", "skill": "Equation comparison", "difficulty": "medium", "question": "Explain whether 3x + 2y = 12 and y = 6 − 1.5x represent the same line.", "answer": "Yes", "solution": "Rearrange the first equation to y = 6 − 1.5x.", "topic": "lin"}, {"id": "VM-Y10-LIN-103", "skill": "Intersecting tariffs", "difficulty": "hard", "question": "Two delivery charges are A = 8 + 1.2d and B = 14 + 0.8d. Find the distances for which B is cheaper.", "answer": "d > 15 km", "solution": "14 + 0.8d < 8 + 1.2d gives d > 15.", "topic": "lin"}, {"id": "VM-Y10-LIN-104", "skill": "Parameter constraint", "difficulty": "hard", "question": "The line y = ax + 4 passes through the intersection of y = 2x − 1 and y = −x + 8. Find a.", "answer": "1/3", "solution": "Intersection is (3,5); 5 = 3a + 4.", "topic": "lin"}, {"id": "VM-Y10-LIN-105", "skill": "Linear equations", "difficulty": "easy", "question": "A line has gradient −3 and passes through (4, 2). What is its vertical intercept?", "answer": "14", "solution": "Substitute into y = −3x + b: 2 = −12 + b, so b = 14.", "topic": "lin"}, {"id": "VM-Y10-LIN-106", "skill": "Point membership", "difficulty": "easy", "question": "Does (−2, 7) lie on y = 1 − 3x?", "answer": "Yes", "solution": "Substitution gives 1 − 3(−2) = 7.", "topic": "lin"}, {"id": "VM-Y10-LIN-107", "skill": "Horizontal intersection", "difficulty": "medium", "question": "Find the intersection of y = 7 and 4x + y = 19.", "answer": "(3, 7)", "solution": "4x = 12, so x = 3.", "topic": "lin"}, {"id": "VM-Y10-LIN-108", "skill": "Parallel condition", "difficulty": "medium", "question": "Find k if 6x + ky = 12 has gradient −2.", "answer": "3", "solution": "Gradient = −6/k; equate to −2.", "topic": "lin"}, {"id": "VM-Y10-LIN-109", "skill": "Collinearity", "difficulty": "hard", "question": "Find p so that (−1, 4), (2, p) and (5, −8) are collinear.", "answer": "−2", "solution": "The middle x is halfway between the others, so p = (4 − 8)/2.", "topic": "lin"}, {"id": "VM-Y10-LIN-110", "skill": "Intercept constraint", "difficulty": "hard", "question": "A line crosses the axes at (a, 0) and (0, 2a), where a is positive. It passes through (3, 8). Find a.", "answer": "7", "solution": "Its gradient is −2, so 8 = −6 + 2a.", "topic": "lin"}, {"id": "VM-Y10-LIN-111", "skill": "Gradient interpretation", "difficulty": "easy", "question": "A straight-line model for remaining water is W = 90 − 6t, with t in minutes. How much water is lost each minute? W is measured in litres.", "answer": "6 L, if W is measured in litres", "solution": "The gradient is −6, so the amount falls by 6 units each minute.", "topic": "lin"}, {"id": "VM-Y10-LIN-112", "skill": "Point membership", "difficulty": "easy", "question": "Which point lies on y = 7 − 2x: (2,3) or (3,2)?", "answer": "(2,3)", "solution": "7 − 2 × 2 = 3; 7 − 2 × 3 = 1.", "topic": "lin"}, {"id": "VM-Y10-LIN-113", "skill": "Missing coordinate", "difficulty": "medium", "question": "The points (−2,5), (1,11) and (k,19) are collinear. Find k.", "answer": "5", "solution": "Gradient = 6 ÷ 3 = 2; equation y = 2x + 9; 19 = 2k + 9.", "topic": "lin"}, {"id": "VM-Y10-LIN-114", "skill": "Parallel line", "difficulty": "medium", "question": "Find the x-intercept of the line through (3,8) parallel to y = 4x − 9.", "answer": "1", "solution": "Equation y = 4x − 4; set y = 0.", "topic": "lin"}, {"id": "VM-Y10-LIN-115", "skill": "Model constraints", "difficulty": "hard", "question": "Two linear plans cost A = 18 + 3n and B = 42 + n dollars for n whole visits. For which positive integers n is A cheaper?", "answer": "1 to 11", "solution": "18 + 3n < 42 + n gives n < 12.", "topic": "lin"}, {"id": "VM-Y10-LIN-116", "skill": "Intercept geometry", "difficulty": "hard", "question": "A line passes through (2,6) and cuts the positive axes at equal numerical intercepts. Find its equation.", "answer": "y = 8 − x", "solution": "Equal intercepts imply gradient −1; substituting gives intercept 8.", "topic": "lin"}, {"id": "VM-Y10-LIN-117", "skill": "Gradient interpretation", "difficulty": "easy", "question": "A line models water remaining in a barrel by W = 90 − 3t, with W in litres and t in minutes. What does −3 represent?", "answer": "Loss of 3 L per minute", "solution": "The coefficient of t is the rate of change, assuming W is measured in litres.", "topic": "lin"}, {"id": "VM-Y10-LIN-118", "skill": "Point membership", "difficulty": "easy", "question": "Does (−3, 11) lie on y = 2 − 3x?", "answer": "Yes", "solution": "2 − 3(−3) = 11.", "topic": "lin"}, {"id": "VM-Y10-LIN-119", "skill": "Intercept constraint", "difficulty": "medium", "question": "A line passes through (0, −7) and (4, 5). Find its equation.", "answer": "y = 3x − 7", "solution": "Gradient = (5 + 7) ÷ 4 = 3; intercept = −7.", "topic": "lin"}, {"id": "VM-Y10-LIN-120", "skill": "Parallel lines", "difficulty": "medium", "question": "Find k if y = (k − 2)x + 9 is parallel to y = 5x − 4.", "answer": "7", "solution": "k − 2 = 5, so k = 7.", "topic": "lin"}, {"id": "VM-Y10-LIN-121", "skill": "Intersection interpretation", "difficulty": "hard", "question": "Two reservoirs contain 160 − 4t and 40 + 2t litres after t minutes. At what volume are they equal?", "answer": "80 L", "solution": "160 − 4t = 40 + 2t gives t = 20; substitute to get 80.", "topic": "lin"}, {"id": "VM-Y10-LIN-122", "skill": "Coordinate constraint", "difficulty": "hard", "question": "A line of gradient −2 passes through (a, 7) and (a + 3, b). Find b without finding a.", "answer": "1", "solution": "Change in y = −2 × 3 = −6; b = 7 − 6.", "topic": "lin"}, {"id": "VM-Y10-LIN-123", "skill": "Gradient interpretation", "difficulty": "easy", "question": "A freezer cools at a constant rate of 3°C per hour. What is the gradient of temperature against time?", "answer": "−3 °C per hour", "solution": "Temperature decreases by 3 °C each hour, so the gradient is −3 °C per hour.", "topic": "lin"}, {"id": "VM-Y10-LIN-124", "skill": "Intercept constraint", "difficulty": "medium", "question": "A straight line crosses the y-axis at −8 and the x-axis at 2. Find its equation.", "answer": "y = 4x − 8", "solution": "Gradient = (0 + 8)/2 = 4; intercept = −8.", "topic": "lin"}, {"id": "VM-Y10-LIN-125", "skill": "Linear model", "difficulty": "medium", "question": "A candle is 19 cm tall after 2 hours and 13 cm after 5 hours. Find its initial height. Assume the candle burns at a constant rate.", "answer": "23 cm", "solution": "Rate = (13 − 19)/3 = −2 cm/h; initial height = 19 + 4.", "topic": "lin"}, {"id": "VM-Y10-LIN-126", "skill": "Parallel lines", "difficulty": "hard", "question": "The lines y = 3x + a and y = 3x − 7 have vertical separation 12. Find both possible values of a.", "answer": "5 or −19", "solution": "|a + 7| = 12, so a + 7 = ±12.", "topic": "lin"}, {"id": "VM-Y10-LIN-127", "skill": "Intersection constraint", "difficulty": "hard", "question": "The lines y = kx + 2 and y = 5x − 10 meet at a point with x-coordinate 4. Find k.", "answer": "2", "solution": "At x = 4 the second line gives y = 10; 4k + 2 = 10.", "topic": "lin"}, {"id": "VM-Y10-LIN-128", "skill": "Linear reasoning", "difficulty": "challenge", "question": "A line passes through (2, 5). Its x-intercept is three times its y-intercept. Find its equation.", "answer": "y = −x/3 + 17/3", "solution": "Write x/3 + y = b. Substituting gives b = 2/3 + 5 = 17/3.", "topic": "lin"}, {"id": "VM-Y10-LIN-129", "skill": "Gradient", "difficulty": "easy", "question": "A straight path drops 9 m over a horizontal distance of 60 m. State its gradient.", "answer": "−0.15", "solution": "Divide signed rise −9 by run 60.", "topic": "lin"}, {"id": "VM-Y10-LIN-130", "skill": "Intercept", "difficulty": "easy", "question": "A line has equation 3x + y = 12. Where does it cross the horizontal axis?", "answer": "(4, 0)", "solution": "Set y = 0; 3x = 12.", "topic": "lin"}, {"id": "VM-Y10-LIN-131", "skill": "Linear model", "difficulty": "easy", "question": "A tank loses 7 L each minute. Initially it holds 93 L. Write its volume V after t minutes. Use the model only until the tank is empty.", "answer": "V = 93 − 7t, for 0 ≤ t ≤ 93/7", "solution": "Initial volume is 93 L and the rate is −7 L/min. The tank is empty at t = 93/7 minutes.", "topic": "lin"}, {"id": "VM-Y10-LIN-132", "skill": "Coordinate geometry", "difficulty": "medium", "question": "The midpoint of a segment on y = 3x − 5 has x-coordinate 4. Find its y-coordinate.", "answer": "7", "solution": "Substitute x = 4 into the equation.", "topic": "lin"}, {"id": "VM-Y10-LIN-133", "skill": "Parallel lines", "difficulty": "medium", "question": "Find k if y = (k − 2)x + 8 is parallel to 5x − y = 1.", "answer": "7", "solution": "The second line has gradient 5, so k − 2 = 5.", "topic": "lin"}, {"id": "VM-Y10-LIN-134", "skill": "Perpendicular lines", "difficulty": "medium", "question": "Find the gradient of a line perpendicular to 4x + 3y = 9.", "answer": "3/4", "solution": "Original gradient is −4/3; take the negative reciprocal.", "topic": "lin"}, {"id": "VM-Y10-LIN-135", "skill": "Linear model", "difficulty": "medium", "question": "A subscription charges $18 plus $0.40 per download. Another charges $6 plus $0.70 per download. At how many downloads are the costs equal?", "answer": "40", "solution": "18 + 0.4n = 6 + 0.7n, hence 12 = 0.3n.", "topic": "lin"}, {"id": "VM-Y10-LIN-136", "skill": "Intercepts", "difficulty": "medium", "question": "A line crosses the axes at (−6, 0) and (0, 9). Find its equation.", "answer": "y = 1.5x + 9", "solution": "Gradient = 9/6 = 1.5 and intercept = 9.", "topic": "lin"}, {"id": "VM-Y10-LIN-137", "skill": "Linear constraints", "difficulty": "hard", "question": "A line through (2, 8) crosses the y-axis at twice the y-coordinate of that point. Find its x-intercept.", "answer": "4", "solution": "Intercept is 16; gradient (8−16)/2 = −4. Solve 0 = 16−4x.", "topic": "lin"}, {"id": "VM-Y10-LIN-138", "skill": "Linear model", "difficulty": "hard", "question": "Two candles start at 31 cm and 25 cm and burn at 2.5 and 1 cm per hour respectively. When is the shorter initial candle 3 cm taller?", "answer": "6 hours", "solution": "25−t = 31−2.5t+3, so 1.5t=9.", "topic": "lin"}, {"id": "VM-Y10-LIN-139", "skill": "Coordinate geometry", "difficulty": "hard", "question": "A line through (−2, 5) is perpendicular to the segment joining (1, 2) and (7, 5). Find its equation.", "answer": "y = −2x + 1", "solution": "Segment gradient 3/6 = 1/2; perpendicular gradient −2. Substitute point.", "topic": "lin"}, {"id": "VM-Y10-LIN-140", "skill": "Linear reasoning", "difficulty": "challenge", "question": "A line with gradient −3 passes through the midpoint of (a, 2) and (8, 10). Its y-intercept is 21. Find a.", "answer": "2", "solution": "Midpoint is ((a+8)/2,6). Solve 6=−3(a+8)/2+21, giving a+8=10.", "topic": "lin"}, {"skill": "Gradient interpretation", "difficulty": "medium", "question": "A tank contains 84 L at 2 min and 60 L at 8 min. Interpret the gradient.", "answer": "−4 L/min", "solution": "Change in volume is −24 L over 6 min; the tank loses 4 L each minute.", "id": "VM-Y10-LIN-R01", "topic": "lin"}, {"skill": "Intercept meaning", "difficulty": "medium", "question": "A printer model is C = 18 + 0.12n dollars. What does the vertical intercept represent?", "answer": "$18 setup cost", "solution": "At n = 0, C = 18.", "id": "VM-Y10-LIN-R02", "topic": "lin"}, {"skill": "Graph construction", "difficulty": "hard", "question": "A line crosses the axes at (−6,0) and (0,9). Find its equation and sketch it.", "answer": "y = 1.5x + 9", "solution": "Gradient = 9 ÷ 6 = 1.5; plot the two intercepts and join.", "id": "VM-Y10-LIN-R03", "topic": "lin"}, {"id": "VM-Y10-NLI-001", "skill": "Parabola", "difficulty": "easy", "question": "State the vertex and axis of symmetry of y = x² − 9.", "answer": "(0,−9); x = 0", "solution": "The graph of y = x² shifts down 9.", "topic": "nli"}, {"id": "VM-Y10-NLI-002", "skill": "Intercepts", "difficulty": "medium", "question": "Find both horizontal intercepts of y = 2x² − 8.", "answer": "(−2,0), (2,0)", "solution": "Set y = 0: x² = 4.", "topic": "nli"}, {"id": "VM-Y10-NLI-003", "skill": "Concavity", "difficulty": "medium", "question": "Compare the concavity of y = x² and y = −3x².", "answer": "Upward and downward respectively", "solution": "The sign of the quadratic coefficient determines concavity.", "topic": "nli"}, {"id": "VM-Y10-NLI-004", "skill": "Exponential", "difficulty": "medium", "question": "Describe the vertical intercept and horizontal asymptote of y = 3^x.", "answer": "(0,1); y = 0", "solution": "3^0 = 1; values approach zero as x becomes very negative.", "topic": "nli"}, {"id": "VM-Y10-NLI-005", "skill": "Classification", "difficulty": "medium", "question": "The values at x = 0,1,2,3 are 2,6,18,54. Identify the relationship type.", "answer": "Exponential", "solution": "Each successive value is multiplied by 3.", "topic": "nli"}, {"id": "VM-Y10-NLI-006", "skill": "Context", "difficulty": "hard", "question": "A culture starts with 80 cells and doubles hourly. When does it first exceed 1000 cells?", "answer": "After 4 hours", "solution": "After 3 hours: 640; after 4: 1280.", "topic": "nli"}, {"id": "VM-Y10-NLI-007", "skill": "Table", "difficulty": "easy", "question": "Complete the values of y = x² + 1 at x = −2, 0, 2.", "answer": "5, 1, 5", "solution": "Square each input and add 1.", "topic": "nli"}, {"id": "VM-Y10-NLI-008", "skill": "Symmetry", "difficulty": "medium", "question": "A parabola has axis x = 3 and passes through (1,7). Give another point at height 7.", "answer": "(5,7)", "solution": "Reflect across x = 3.", "topic": "nli"}, {"id": "VM-Y10-NLI-009", "skill": "Intersection", "difficulty": "hard", "question": "Find the intersections of y = x² and y = 9.", "answer": "(−3,9), (3,9)", "solution": "Solve x² = 9.", "topic": "nli"}, {"id": "VM-Y10-NLI-010", "skill": "Decay", "difficulty": "medium", "question": "A quantity starts at 64 and halves each day. Write a rule for its value after n days.", "answer": "64(1/2)^n", "solution": "Each day multiplies the preceding value by one half.", "topic": "nli"}, {"id": "VM-Y10-NLI-011", "skill": "Differences", "difficulty": "medium", "question": "The outputs for equally spaced inputs are 1, 4, 9, 16, 25. Show why the relationship is not linear.", "answer": "First differences are 3,5,7,9.", "solution": "A linear relationship has constant first differences.", "topic": "nli"}, {"id": "VM-Y10-NLI-012", "skill": "Maximum", "difficulty": "medium", "question": "A model gives height h = 16 − (t − 4)². State the maximum height and when it occurs.", "answer": "16 at t = 4", "solution": "The squared term is nonnegative and is zero at t = 4.", "topic": "nli"}, {"id": "VM-Y10-NLI-013", "skill": "Error analysis", "difficulty": "medium", "question": "A student says y = 2^x crosses the horizontal axis at x = 0. Correct the claim.", "answer": "It crosses the vertical axis at (0,1).", "solution": "2⁰ = 1; 2^x is positive for every real x.", "topic": "nli"}, {"id": "VM-Y10-NLI-014", "skill": "Comparison", "difficulty": "hard", "question": "For integer x from 2 to 6, when does 2^x first strictly exceed x²?", "answer": "x = 5", "solution": "At x = 2, 3, 4 the pairs are (4,4), (8,9), (16,16); at 5, 32 > 25.", "topic": "nli"}, {"id": "VM-Y10-NLI-015", "skill": "Graph features", "difficulty": "medium", "question": "Does y = x² + 4 have any real horizontal intercepts? Explain.", "answer": "No", "solution": "x² + 4 is at least 4.", "topic": "nli"}, {"id": "VM-Y10-NLI-016", "skill": "Context", "difficulty": "hard", "question": "A square garden has side length s metres. Explain why doubling s does not double its area.", "answer": "Area quadruples.", "solution": "(2s)² = 4s².", "topic": "nli"}, {"id": "VM-Y10-NLI-017", "skill": "Graph comparison", "difficulty": "hard", "question": "Sketch y = x² and y = x² − 4 on common axes. Describe the transformation and label intercepts.", "answer": "Shift down 4; second graph intercepts (−2,0), (2,0), (0,−4)", "solution": "Subtracting 4 lowers every output by 4. Solve x² = 4 for horizontal intercepts.", "topic": "nli"}, {"id": "VM-Y10-NLI-018", "skill": "Model selection", "difficulty": "hard", "question": "A table gives outputs 5, 10, 20, 40 for inputs 0, 1, 2, 3. Write a rule and predict the next output.", "answer": "y = 5(2)^x; 80", "solution": "Successive ratios are 2 and the initial output is 5.", "topic": "nli"}, {"id": "VM-Y10-NLI-019", "skill": "Reverse graph reasoning", "difficulty": "hard", "question": "A parabola y = ax² passes through (3,18). Find a and state whether it opens upwards.", "answer": "a = 2; upwards", "solution": "18 = 9a; positive a gives upward concavity.", "topic": "nli"}, {"id": "VM-Y10-NLI-020", "skill": "Physical domain", "difficulty": "hard", "question": "A ball height is h = 9 − t² for t ≥ 0. When does the model reach ground level?", "answer": "3 seconds", "solution": "Set h = 0; t² = 9; discard negative time.", "topic": "nli"}, {"id": "VM-Y10-NLI-021", "skill": "Counterexample", "difficulty": "hard", "question": "A student says every increasing curve is exponential. Give a counterexample.", "answer": "y = x² for x ≥ 0", "solution": "It increases on that domain but equal input steps do not give a constant output ratio.", "topic": "nli"}, {"id": "VM-Y10-NLI-022", "skill": "Symmetry construction", "difficulty": "hard", "question": "Write a quadratic with vertex (0,0) passing through (−2,−12), then predict its value at x = 2.", "answer": "y = −3x²; −12", "solution": "Substitute −12 = 4a. Symmetry about x = 0 gives equal outputs.", "topic": "nli"}, {"id": "VM-Y10-NLI-023", "skill": "Vertex interpretation", "difficulty": "easy", "question": "A parabola has vertex (0,−4) and opens upwards. What is its minimum y-value?", "answer": "−4", "solution": "The vertex is the lowest point.", "topic": "nli"}, {"id": "VM-Y10-NLI-024", "skill": "Graph comparison", "difficulty": "medium", "question": "Compare the widths of y = x² and y = 4x² at height y = 4.", "answer": "2nd is half as wide", "solution": "The first has x = ±2, the second x = ±1; widths 4 and 2.", "topic": "nli"}, {"id": "VM-Y10-NLI-025", "skill": "Exponential asymptote", "difficulty": "easy", "question": "What horizontal line does y = 3^x approach as x becomes very negative?", "answer": "y = 0", "solution": "Positive powers with negative exponent become small positive reciprocals.", "topic": "nli"}, {"id": "VM-Y10-NLI-026", "skill": "Graph investigation", "difficulty": "hard", "question": "Use a graphing tool to plot y = 2^x and y = (1/2)^x. Describe their relationship.", "answer": "Reflections in the y-axis", "solution": "Replacing x by −x gives 2^(−x) = (1/2)^x.", "topic": "nli"}, {"id": "VM-Y10-NLI-027", "skill": "Intercept reasoning", "difficulty": "challenge", "question": "Explain why y = 5^x has no x-intercept, even though its graph approaches the x-axis.", "answer": "It is always positive", "solution": "A positive base raised to any real power is positive.", "topic": "nli"}, {"id": "VM-Y10-NLI-028", "skill": "Table interpretation", "difficulty": "medium", "question": "A table has y-values 1, 3, 9, 27 at x = 0, 1, 2, 3. Identify the relationship. Assume an exponential model.", "answer": "y = 3^x", "solution": "Each unit increase in x multiplies y by 3.", "topic": "nli"}, {"id": "VM-Y10-NLI-029", "skill": "Symmetry", "difficulty": "easy", "question": "The graph y = x² contains (4, 16). Give the other point with y-coordinate 16.", "answer": "(−4, 16)", "solution": "Squaring opposite numbers gives equal results.", "topic": "nli"}, {"id": "VM-Y10-NLI-030", "skill": "Exponential pattern", "difficulty": "easy", "question": "A quantity takes values 3, 6, 12, 24 at equally spaced times. Is its growth linear or exponential? Assume the observed pattern continues.", "answer": "Exponential", "solution": "The ratio is constant at 2; the differences are not constant.", "topic": "nli"}, {"id": "VM-Y10-NLI-031", "skill": "Intersection reasoning", "difficulty": "challenge", "question": "Without drawing a graph, explain why y = x² + 2 and y = 1 have no real intersection.", "answer": "x² + 2 is always at least 2.", "solution": "A real square is nonnegative, so x² + 2 cannot equal 1.", "topic": "nli"}, {"id": "VM-Y10-NLI-032", "skill": "Model comparison", "difficulty": "challenge", "question": "Two models start at 16: A decreases by 6 each step and B halves each step. At which positive integer step do they first agree?", "answer": "Step 2", "solution": "A gives 10, 4; B gives 8, 4. The first agreement is at step 2.", "topic": "nli"}, {"id": "VM-Y10-NLI-033", "skill": "Graph points", "difficulty": "easy", "question": "Which of (2, 8), (3, 8) and (4, 8) lies on y = 2ˣ?", "answer": "(3,8)", "solution": "2³ = 8; the other powers are 4 and 16.", "topic": "nli"}, {"id": "VM-Y10-NLI-034", "skill": "Graph sketch", "difficulty": "medium", "question": "Sketch y = (x − 2)² − 4 using its vertex and both x-intercepts. State those three points.", "answer": "(2,−4), (0,0), (4,0)", "solution": "The square is zero at x = 2. For intercepts, (x − 2)² = 4, giving x = 0 or 4.", "topic": "nli"}, {"id": "VM-Y10-NLI-035", "skill": "Graph scale", "difficulty": "hard", "question": "A population doubles each day. On a graph with equal daily intervals, its first three values are 20, 40 and 80. Explain why joining them with one straight line is misleading.", "answer": "The daily increases are unequal.", "solution": "The increases are 20 then 40; a straight line has constant gradient. The doubling model is exponential.", "topic": "nli"}, {"id": "VM-Y10-NLI-036", "skill": "Model intersection", "difficulty": "challenge", "question": "A square garden has side x metres. A rectangular garden has sides 2 m and x + 3 m. For what positive x do they have equal area?", "answer": "x = 1 + √7 m", "solution": "x² = 2(x + 3), so (x − 1)² = 7. Only 1 + √7 is positive.", "topic": "nli"}, {"id": "VM-Y10-NLI-037", "skill": "Projectile interpretation", "difficulty": "hard", "question": "A ball follows h = 12t − 3t², where h is metres and t is seconds. For how long is it at or above 9 m?", "answer": "2 seconds", "solution": "Solve 12t − 3t² = 9: t² − 4t + 3 = 0, giving t = 1 and 3. The downward parabola is above 9 between them.", "topic": "nli"}, {"id": "VM-Y10-NLI-038", "skill": "Growth comparison", "difficulty": "medium", "question": "A colony doubles every hour from 50 organisms. A second colony starts at 200 and gains 50 each hour. Compare their sizes after three hours.", "answer": "400 and 350", "solution": "Exponential: 50 × 2³ = 400. Linear: 200 + 3 × 50 = 350.", "topic": "nli"}, {"id": "VM-Y10-NLI-039", "skill": "Quadratic design", "difficulty": "hard", "question": "A rectangular garden has sides x and 14 − x metres. Find two possible widths giving area 40 m².", "answer": "4 m and 10 m", "solution": "x(14 − x) = 40 gives x² − 14x + 40 = (x − 4)(x − 10) = 0.", "topic": "nli"}, {"id": "VM-Y10-NLI-040", "skill": "Model discrimination", "difficulty": "challenge", "question": "Three observations at x = 0, 1, 2 have y = 2, 4, 8. Both y = 2 × 2^x and y = x² + x + 2 fit. Which prediction at x = 3 would distinguish them?", "answer": "16 versus 14", "solution": "Exponential gives 2 × 8 = 16; quadratic gives 9 + 3 + 2 = 14. A fourth observation can distinguish the models.", "topic": "nli"}, {"id": "VM-Y10-NLI-041", "skill": "Zero substitution", "difficulty": "easy", "question": "Find the y-intercept of y = 2x² − 7.", "answer": "(0, −7)", "solution": "At x = 0 the squared term is zero.", "topic": "nli"}, {"id": "VM-Y10-NLI-042", "skill": "Growth recognition", "difficulty": "easy", "question": "A population triples every hour. Is the increase by a constant amount or a constant factor?", "answer": "Constant factor", "solution": "Each new population is three times the previous one.", "topic": "nli"}, {"id": "VM-Y10-NLI-043", "skill": "Graph ordering", "difficulty": "medium", "question": "For x = 2, arrange the values of y = x², y = 3x and y = 3ˣ from smallest to largest.", "answer": "x², 3x, 3ˣ", "solution": "The respective values are 4, 6 and 9.", "topic": "nli"}, {"id": "VM-Y10-NLI-044", "skill": "Negative inputs", "difficulty": "medium", "question": "A student claims y = x² always increases as x increases. Use x = −3 and x = −2 to test the claim.", "answer": "False", "solution": "The outputs are 9 and 4 respectively, so the output decreases as x increases.", "topic": "nli"}, {"id": "VM-Y10-NLI-045", "skill": "Symmetry", "difficulty": "easy", "question": "The graph y = x² is symmetric about the y-axis. Reflect the point (−3, 9) across that axis.", "answer": "(3, 9)", "solution": "Reflection reverses the x-coordinate and preserves the y-coordinate.", "topic": "nli"}, {"id": "VM-Y10-NLI-046", "skill": "Graph comparison", "difficulty": "medium", "question": "At x = 0 and x = 2 compare y = 2^x with y = x².", "answer": "At 0: 1 and 0; at 2: both 4", "solution": "Substitute each input into both rules.", "topic": "nli"}, {"id": "VM-Y10-NLI-047", "skill": "Area model", "difficulty": "hard", "question": "A rectangular garden has sides x and 12 − x metres. Find the area when x = 3 and x = 6, and explain why x = 9 gives the same area as x = 3.", "answer": "27 m²; 36 m²; side lengths swap", "solution": "A = x(12 − x); at 3 and 9 the sides are 3 and 9.", "topic": "nli"}, {"id": "VM-Y10-NLI-048", "skill": "Model investigation", "difficulty": "challenge", "question": "A population doubles each day. A second population starts four times larger but remains constant. When do the populations match?", "answer": "After 2 days", "solution": "If the first starts at P, solve P × 2^t = 4P; 2² = 4.", "topic": "nli"}, {"id": "VM-Y10-NLI-049", "skill": "Finite differences", "difficulty": "medium", "question": "For equally spaced x-values 0, 1, 2, 3, a table gives y-values 4, 7, 12, 19. Find the next value if the second differences remain constant.", "answer": "28", "solution": "First differences are 3, 5, 7. The next is 9, so 19 + 9 = 28.", "topic": "nli"}, {"id": "VM-Y10-NLI-050", "skill": "Model domain", "difficulty": "hard", "question": "A square garden has side length 10 − x metres after a strip of width x is removed from each of two adjacent sides. State the area model and the domain allowing a nonzero garden and nonnegative strip width. The strips are removed from the original 10 m square.", "answer": "A = (10 − x)²; 0 ≤ x < 10", "solution": "Square the remaining side. Its length must be positive and x cannot be negative.", "topic": "nli"}, {"id": "VM-Y10-NLI-051", "skill": "Graph intercept", "difficulty": "easy", "question": "Does the graph y = 4ˣ pass through (0,0)? Explain.", "answer": "No", "solution": "4⁰ = 1, so it passes through (0,1).", "topic": "nli"}, {"id": "VM-Y10-NLI-052", "skill": "Equal heights", "difficulty": "challenge", "question": "Two points on y = x² − 8x + 9 have equal y-values. One has x = −1. Find the other x-coordinate.", "answer": "9", "solution": "The axis of symmetry is x = 4. The first point is 5 units left of it, so the other is 5 units right.", "topic": "nli"}, {"id": "VM-Y10-NLI-053", "skill": "Quadratic zero", "difficulty": "easy", "question": "Which has an x-intercept: y = x² or y = x² + 1?", "answer": "y = x² only", "solution": "At x = 0 the first graph has y = 0; the second is always at least 1.", "topic": "nli"}, {"id": "VM-Y10-NLI-054", "skill": "Exponential ratio", "difficulty": "medium", "question": "A curve passes through (0,3), (1,12) and (2,48). Assuming y = abˣ, find a and b.", "answer": "a = 3, b = 4", "solution": "At x=0, y=a. Consecutive y-values have ratio 4.", "topic": "nli"}, {"id": "VM-Y10-NLI-055", "skill": "Quadratic interval", "difficulty": "hard", "question": "A garden model gives area A = x(18 − x). Find the two widths giving area 65 m².", "answer": "5 m and 13 m", "solution": "x² − 18x + 65 = 0, so (x−5)(x−13)=0.", "topic": "nli"}, {"id": "VM-Y10-NLI-056", "skill": "Discrete model ambiguity", "difficulty": "challenge", "question": "Two data points are (0,2) and (1,4). Give one linear and one exponential model fitting both, and compare their predictions at x=3.", "answer": "Linear: y = 2 + 2x, giving 8; exponential: y = 2 × 2ˣ, giving 16.", "solution": "y=2+2x and y=2×2ˣ both fit. Substitution at x=3 gives 8 and 16.", "topic": "nli"}, {"id": "VM-Y10-NLI-057", "skill": "Graph reflection", "difficulty": "easy", "question": "The graph y = x² is reflected in the x-axis. What is its new equation?", "answer": "y = −x²", "solution": "Reflection in the x-axis negates each output.", "topic": "nli"}, {"id": "VM-Y10-NLI-058", "skill": "Quadratic table completion", "difficulty": "medium", "question": "A quadratic graph is symmetric about x = 3. Its values at x = 1 and x = 2 are 9 and 6. Find its values at x = 4 and x = 5.", "answer": "6 and 9", "solution": "Inputs 2 and 4 are equally distant from 3, as are 1 and 5.", "topic": "nli"}, {"id": "VM-Y10-NLI-059", "skill": "Model consistency", "difficulty": "hard", "question": "A population model predicts 200, 300 and 450 organisms at equally spaced times. Explain why a constant additive increase cannot fit these values and give the constant multiplier that does.", "answer": "The differences 100 and 150 are unequal; the constant multiplier is 1.5.", "solution": "Differences are 100 and 150, but ratios are 300/200 = 450/300 = 1.5.", "topic": "nli"}, {"id": "VM-Y10-NLI-060", "skill": "Quadratic versus linear", "difficulty": "challenge", "question": "For positive integer x, find the first x for which x² exceeds 5x + 6.", "answer": "7", "solution": "x² − 5x − 6 = (x − 6)(x + 1). For positive x this is positive only when x > 6.", "topic": "nli"}, {"id": "VM-Y10-NLI-061", "skill": "Graph orientation", "difficulty": "easy", "question": "Does y = −2x² + 7 have a maximum or minimum? State its value.", "answer": "Maximum 7", "solution": "The squared term is non-positive and equals zero at x = 0.", "topic": "nli"}, {"id": "VM-Y10-NLI-062", "skill": "Exponential table", "difficulty": "medium", "question": "A quantity follows y = 64(0.5)^x. Make a table for x = 0, 1, 2, 3 and describe the pattern.", "answer": "64, 32, 16, 8; halves each step", "solution": "Substitute each input or multiply the previous output by 0.5.", "topic": "nli"}, {"id": "VM-Y10-NLI-063", "skill": "Parabola construction", "difficulty": "hard", "question": "A parabola has axis of symmetry x = 2 and crosses the horizontal axis at x = −1. Find its other horizontal intercept.", "answer": "x = 5", "solution": "The first intercept is three units left of the axis, so the other is three units right.", "topic": "nli"}, {"id": "VM-Y10-NLI-064", "skill": "Model ambiguity", "difficulty": "challenge", "question": "Two models y = x² and y = 2^x agree at x = 2 and x = 4. Explain why those observations alone cannot identify the correct model and give a positive integer input that distinguishes them.", "answer": "x = 3", "solution": "Both give 4 and 16 at the observed inputs. At x = 3 the outputs are 9 and 8, so another observation can distinguish them.", "topic": "nli"}, {"id": "VM-Y10-NLI-065", "skill": "Quadratic sign", "difficulty": "easy", "question": "For y = −x², can any real input produce a positive output?", "answer": "No.", "solution": "A real square is nonnegative, so its negative is nonpositive.", "topic": "nli"}, {"id": "VM-Y10-NLI-066", "skill": "Exponential missing term", "difficulty": "medium", "question": "Three consecutive terms of an exponential growth sequence are 12, k, 27. The common multiplier is positive. Find k.", "answer": "18", "solution": "The common ratio satisfies r² = 27/12 = 2.25, so r = 1.5 and k = 18.", "topic": "nli"}, {"id": "VM-Y10-NLI-067", "skill": "Quadratic equal output", "difficulty": "hard", "question": "The graph y = (x − 4)² + 1 passes through (1,10). Find the other point with y = 10 without expanding the expression.", "answer": "(7,10)", "solution": "The axis of symmetry is x = 4. The point x = 1 is three units left, so the matching point is three units right.", "topic": "nli"}, {"id": "VM-Y10-NLI-068", "skill": "Model counterexample", "difficulty": "challenge", "question": "A student claims every increasing sequence with increasing first differences is exponential. Give a counterexample and explain.", "answer": "1, 4, 9, 16.", "solution": "The differences 3, 5, 7 increase, but successive ratios 4, 9/4 and 16/9 differ; this is a quadratic sequence.", "topic": "nli"}, {"id": "VM-Y10-NLI-069", "skill": "Quadratic symmetry", "difficulty": "easy", "question": "The graph of y = x² has a point at (−6, 36). Give its reflection in the y-axis.", "answer": "(6, 36)", "solution": "Reflection changes the sign of x only.", "topic": "nli"}, {"id": "VM-Y10-NLI-070", "skill": "Exponential change", "difficulty": "medium", "question": "A culture has 80 cells initially and doubles every hour. Find the increase in cell count during the third hour.", "answer": "320 cells", "solution": "At hour two there are 320 cells; at hour three there are 640. Increase = 320.", "topic": "nli"}, {"id": "VM-Y10-NLI-071", "skill": "Quadratic model", "difficulty": "hard", "question": "A rectangular garden has perimeter 24 m. Express its area in terms of width w and find the maximum area.", "answer": "A = w(12 − w); 36 m²", "solution": "Length = 12 − w. A = 36 − (w − 6)², so maximum is 36 at w = 6.", "topic": "nli"}, {"id": "VM-Y10-NLI-072", "skill": "Finite data ambiguity", "difficulty": "challenge", "question": "A table gives y = 1, 4, 9 for x = 1, 2, 3. Does this prove that y = x² for all x? Give a counterexample rule.", "answer": "No; y = x² + (x − 1)(x − 2)(x − 3)", "solution": "The added product is zero at the three observed inputs but not at x = 4.", "topic": "nli"}, {"id": "VM-Y10-NLI-073", "skill": "Graph recognition", "difficulty": "easy", "question": "Which has a constant ratio between outputs at consecutive positive integer inputs: y = 3x or y = 3ˣ?", "answer": "y = 3ˣ", "solution": "Each increase of 1 in x multiplies the exponential output by 3.", "topic": "nli"}, {"id": "VM-Y10-NLI-074", "skill": "Quadratic intercept", "difficulty": "easy", "question": "A parabola y = x² + c passes through (0, 6). Find c.", "answer": "6", "solution": "Substitute x = 0 and y = 6.", "topic": "nli"}, {"id": "VM-Y10-NLI-075", "skill": "Graph comparison", "difficulty": "medium", "question": "For which integer x from −2 to 2 does x² exceed 2x?", "answer": "−2, −1", "solution": "The differences x² − 2x are 8, 3, 0, −1, 0 respectively.", "topic": "nli"}, {"id": "VM-Y10-NLI-076", "skill": "Model parameter", "difficulty": "hard", "question": "A parabola y = ax² + 4 passes through (3, −14). Find a and state whether its vertex is a maximum or minimum.", "answer": "a = −2; maximum", "solution": "−14 = 9a + 4, so a = −2. Negative coefficient means it opens downwards.", "topic": "nli"}, {"id": "VM-Y10-NLI-077", "skill": "Graph symmetry", "difficulty": "easy", "question": "Is the point (−2, 4) the reflection of (2, 4) across the x-axis or y-axis?", "answer": "y-axis", "solution": "Only the x-coordinate changes sign.", "topic": "nli"}, {"id": "VM-Y10-NLI-078", "skill": "Exponential table", "difficulty": "medium", "question": "An exponential model has outputs 12, 18, 27 at x = 0, 1, 2. Find the output at x = 3.", "answer": "40.5", "solution": "The common multiplier is 1.5; multiply 27 by 1.5.", "topic": "nli"}, {"id": "VM-Y10-NLI-079", "skill": "Graph comparison", "difficulty": "medium", "question": "Which graph, y = x² or y = 4x, lies higher at x = 3? By how much?", "answer": "y = 4x by 3", "solution": "The outputs are 9 and 12 respectively.", "topic": "nli"}, {"id": "VM-Y10-NLI-080", "skill": "Parameter recovery", "difficulty": "hard", "question": "A parabola y = ax² + c passes through (1, 7) and (3, 23). Find a and c.", "answer": "a = 2, c = 5", "solution": "a + c = 7 and 9a + c = 23. Subtract to obtain 8a = 16.", "topic": "nli"}, {"id": "VM-Y10-NLI-081", "skill": "Vertex interpretation", "difficulty": "easy", "question": "The lowest point on a parabola is (−3, 2). What is its minimum y-value?", "answer": "2", "solution": "The vertical coordinate of the lowest point is 2.", "topic": "nli"}, {"id": "VM-Y10-NLI-082", "skill": "Quadratic table", "difficulty": "medium", "question": "For y = x² − 4, find the two integer inputs that produce y = 5.", "answer": "−3 and 3", "solution": "x² = 9, so x = ±3.", "topic": "nli"}, {"id": "VM-Y10-NLI-083", "skill": "Exponential comparison", "difficulty": "medium", "question": "A culture triples each hour. Its population is 270 at hour 3. What was its population at hour 1?", "answer": "30", "solution": "Reverse two hourly multiplications: 270 ÷ 9 = 30.", "topic": "nli"}, {"id": "VM-Y10-NLI-084", "skill": "Graph intersection", "difficulty": "hard", "question": "Find both intersections of y = x² and y = 2x + 3.", "answer": "(−1, 1) and (3, 9)", "solution": "x² − 2x − 3 = (x − 3)(x + 1) = 0. Substitute each root.", "topic": "nli"}, {"skill": "Graph symmetry", "difficulty": "easy", "question": "The graph y = x² + 7 contains the point (3,16). Give another point with the same y-coordinate.", "answer": "(−3,16)", "solution": "Squaring opposite inputs gives equal outputs.", "id": "VM-Y10-NLI-085", "topic": "nli"}, {"skill": "Exponential table", "difficulty": "medium", "question": "A culture has 90 cells at hour zero, 135 at hour one and 202.5 in a mathematical model at hour two. Write an exponential model for the predicted count.", "answer": "N = 90(1.5)^t", "solution": "The successive ratio is 1.5 and initial value is 90.", "id": "VM-Y10-NLI-086", "topic": "nli"}, {"skill": "Quadratic comparison", "difficulty": "medium", "question": "At which x-values do y = x² and y = 4x have equal outputs?", "answer": "0 and 4", "solution": "x² = 4x gives x(x − 4) = 0.", "id": "VM-Y10-NLI-087", "topic": "nli"}, {"skill": "Physical restriction", "difficulty": "hard", "question": "A rectangular garden has perimeter 30 m. Its area is modelled by A = x(15 − x). Find the maximum area and explain why x = 18 is invalid.", "answer": "56.25 m²; x = 18 gives a negative side length", "solution": "A = 56.25 − (x − 7.5)², so maximum at x = 7.5. Both sides must be positive.", "id": "VM-Y10-NLI-088", "topic": "nli"}, {"id": "VM-Y10-NLI-089", "skill": "Quadratic output", "difficulty": "easy", "question": "For y = 12 − x², does the output increase or decrease as x moves from 0 to 2?", "answer": "Decreases", "solution": "The output changes from 12 to 8.", "topic": "nli"}, {"id": "VM-Y10-NLI-090", "skill": "Exponential ratio", "difficulty": "medium", "question": "A model has outputs 48, 24, 12 and 6 at consecutive integer inputs starting at zero. Find the output at input 5. Assume the halving pattern continues.", "answer": "1.5", "solution": "Each step halves the output; the next two are 3 and 1.5.", "topic": "nli"}, {"id": "VM-Y10-NLI-091", "skill": "Parabola intercepts", "difficulty": "medium", "question": "Sketch y = (x − 2)(x + 4), labelling its two horizontal intercepts and axis of symmetry.", "answer": "Intercepts (2,0), (−4,0); axis x = −1", "solution": "Set each factor to zero. The roots are −4 and 2; their midpoint is −1. Substituting x = −1 gives y = −9. Plot the vertex (−1,−9) and draw an upward-opening parabola.", "topic": "nli"}, {"id": "VM-Y10-NLI-092", "skill": "Comparing models", "difficulty": "hard", "question": "The models y = ax² and y = b × 2ˣ both pass through (2, 24). Find their outputs at x = 0.", "answer": "0 and 6 respectively", "solution": "24 = 4a and 24 = 4b, so a = b = 6. At x = 0 the outputs are 0 and 6.", "topic": "nli"}, {"id": "VM-Y10-NLI-094", "skill": "Quadratic symmetry", "difficulty": "easy", "question": "The graph y = x² + 7 contains (−4, 23). Give its reflected point across the y-axis.", "answer": "(4, 23)", "solution": "Changing the sign of x does not change x².", "topic": "nli"}, {"id": "VM-Y10-NLI-095", "skill": "Exponential comparison", "difficulty": "medium", "question": "A population model is P = 200 × 2ᵗ. By what factor does P change between t = 3 and t = 5?", "answer": "4", "solution": "2⁵ ÷ 2³ = 4.", "topic": "nli"}, {"id": "VM-Y10-NLI-096", "skill": "Parabola parameters", "difficulty": "medium", "question": "A parabola y = ax² passes through (3, −18). Find a and state whether it opens upwards or downwards.", "answer": "a = −2; downwards", "solution": "9a = −18; negative a gives a downward opening.", "topic": "nli"}, {"id": "VM-Y10-NLI-097", "skill": "Graphical intersections", "difficulty": "hard", "question": "Find the positive x-coordinate where y = x² and y = 5x meet.", "answer": "5", "solution": "x² = 5x, so x(x − 5) = 0. The positive root is 5.", "topic": "nli"}, {"id": "VM-Y10-NLI-098", "skill": "Quadratic range", "difficulty": "hard", "question": "For y = 20 − 2x² with −3 ≤ x ≤ 2, find the minimum and maximum outputs.", "answer": "Minimum 2; maximum 20", "solution": "Maximum at x = 0; largest absolute input is −3, giving 20 − 18 = 2.", "topic": "nli"}, {"id": "VM-Y10-NLI-099", "skill": "Parabola direction", "difficulty": "easy", "question": "Does y = −3x² + 8 open upwards or downwards?", "answer": "Downwards", "solution": "The coefficient of x² is negative.", "topic": "nli"}, {"id": "VM-Y10-NLI-100", "skill": "Exponential multiplier", "difficulty": "easy", "question": "A quantity follows Q = 50(0.9)^t. What fraction remains after each time step?", "answer": "9/10", "solution": "The multiplier is 0.9 = 9/10.", "topic": "nli"}, {"id": "VM-Y10-NLI-101", "skill": "Quadratic roots", "difficulty": "medium", "question": "Find the x-intercepts of y = x² − 49.", "answer": "(−7,0) and (7,0)", "solution": "Set y = 0, so x² = 49.", "topic": "nli"}, {"id": "VM-Y10-NLI-103", "skill": "Quadratic comparison", "difficulty": "hard", "question": "Find all real x for which x² is less than 6x.", "answer": "0 < x < 6", "solution": "x(x − 6) < 0 between its roots.", "topic": "nli"}, {"id": "VM-Y10-NLI-104", "skill": "Exponential recovery", "difficulty": "hard", "question": "An exponential model Q = ab^t gives Q = 18 at t = 1 and Q = 72 at t = 3. Find positive a and b.", "answer": "a = 9, b = 2", "solution": "Divide to obtain b² = 4, then 18 = 2a.", "topic": "nli"}, {"id": "VM-Y10-NLI-105", "skill": "Quadratic output", "difficulty": "easy", "question": "What is the minimum value of y = (x + 4)² + 3?", "answer": "3", "solution": "A square is nonnegative and equals zero at x = −4.", "topic": "nli"}, {"id": "VM-Y10-NLI-107", "skill": "Quadratic symmetry", "difficulty": "medium", "question": "The graph y = x² − 8x + 11 has equal outputs at x = 1 and x = k, with k not 1. Find k.", "answer": "7", "solution": "The axis is x = 4; 1 and 7 are equally distant from it.", "topic": "nli"}, {"id": "VM-Y10-NLI-108", "skill": "Growth comparison", "difficulty": "medium", "question": "A sequence begins at 5 and triples each step. Another begins at 45 and increases by 10 each step. Which is larger after three steps? Count three transitions after the initial value.", "answer": "Tripling sequence", "solution": "5 × 27 = 135; 45 + 30 = 75.", "topic": "nli"}, {"id": "VM-Y10-NLI-110", "skill": "Quadratic parameters", "difficulty": "hard", "question": "A parabola has vertex (2, −5) and passes through (4, 7). Find its equation in vertex form.", "answer": "y = 3(x − 2)² − 5", "solution": "7 = 4a − 5, hence a = 3.", "topic": "nli"}, {"id": "VM-Y10-NLI-111", "skill": "Quadratic minimum", "difficulty": "easy", "question": "What is the smallest value of y = x² + 9 for real x?", "answer": "9", "solution": "x² is nonnegative and equals zero at x = 0.", "topic": "nli"}, {"id": "VM-Y10-NLI-113", "skill": "Parabola symmetry", "difficulty": "medium", "question": "The graph y = (x − 4)² + 2 contains (1,11). Find the other point with y = 11.", "answer": "(7,11)", "solution": "The axis is x = 4; reflect x = 1 across it.", "topic": "nli"}, {"id": "VM-Y10-NLI-114", "skill": "Exponential ratio", "difficulty": "medium", "question": "A geometric growth model has values 80 at t = 2 and 180 at t = 4. Find the positive growth multiplier per step.", "answer": "1.5", "solution": "Multiplier squared = 180 ÷ 80 = 2.25; square root = 1.5.", "topic": "nli"}, {"id": "VM-Y10-NLI-115", "skill": "Intersection", "difficulty": "hard", "question": "Find both intersections of y = x² − 4 and y = 3x.", "answer": "(−1,−3) and (4,12)", "solution": "x² − 3x − 4 = (x − 4)(x + 1) = 0; substitute into y = 3x.", "topic": "nli"}, {"id": "VM-Y10-NLI-117", "skill": "Quadratic symmetry", "difficulty": "easy", "question": "The graph y = (x − 4)² has a point at (6, 4). Give its reflected point across the axis of symmetry.", "answer": "(2, 4)", "solution": "The axis is x = 4; reflect 6 to 2.", "topic": "nli"}, {"id": "VM-Y10-NLI-118", "skill": "Exponential multiplier", "difficulty": "easy", "question": "A sequence begins 80, 40, 20, 10. What multiplier generates each next term?", "answer": "0.5", "solution": "Each term is half its predecessor.", "topic": "nli"}, {"id": "VM-Y10-NLI-120", "skill": "Parabola intercepts", "difficulty": "medium", "question": "A parabola y = x² + c crosses the x-axis at x = −6. Find c and the other intercept.", "answer": "c = −36; (6, 0)", "solution": "0 = 36 + c; symmetry gives the other intercept.", "topic": "nli"}, {"id": "VM-Y10-NLI-121", "skill": "Model comparison", "difficulty": "hard", "question": "For positive x, determine when y = x² exceeds y = 9x.", "answer": "x > 9", "solution": "x² > 9x; divide by positive x to obtain x > 9.", "topic": "nli"}, {"id": "VM-Y10-NLI-122", "skill": "Exponential recovery", "difficulty": "hard", "question": "An exponential model y = ab^x has y = 45 at x = 1 and y = 135 at x = 2. Find a and b.", "answer": "a = 15, b = 3", "solution": "Divide successive values to get b = 3; 45 ÷ 3 = 15.", "topic": "nli"}, {"id": "VM-Y10-NLI-123", "skill": "Quadratic symmetry", "difficulty": "easy", "question": "The graph y = (x − 6)² + 2 has a minimum. State its x-coordinate.", "answer": "6", "solution": "The squared term is zero at x = 6.", "topic": "nli"}, {"id": "VM-Y10-NLI-125", "skill": "Exponential model", "difficulty": "medium", "question": "A culture triples every hour. It contains 810 cells after 3 hours. Find its initial population.", "answer": "30", "solution": "Divide 810 by 3³ = 27.", "topic": "nli"}, {"id": "VM-Y10-NLI-126", "skill": "Quadratic comparison", "difficulty": "hard", "question": "For which real x is x² + 5 equal to 6x?", "answer": "1 and 5", "solution": "Rearrange to x² − 6x + 5 = 0; factor (x − 1)(x − 5).", "topic": "nli"}, {"id": "VM-Y10-NLI-127", "skill": "Quadratic modelling", "difficulty": "hard", "question": "A braking model is d = 0.01v², where d is in metres and v is in km/h. Find the positive speed when d = 36 m.", "answer": "60 km/h", "solution": "36 = 0.01v², so v² = 3600 and v = 60.", "topic": "nli"}, {"id": "VM-Y10-NLI-128", "skill": "Quadratic modelling", "difficulty": "challenge", "question": "A rectangular garden has perimeter 44 m. Its area is 96 m². Find its dimensions using a quadratic model.", "answer": "6 m by 16 m", "solution": "Let width x; length 22 − x. x(22 − x) = 96 gives (x − 6)(x − 16) = 0.", "topic": "nli"}, {"id": "VM-Y10-NLI-129", "skill": "Quadratic graphs", "difficulty": "easy", "question": "State the minimum value of y = (x + 7)² − 4.", "answer": "−4", "solution": "The squared term is nonnegative and equals zero at x=−7.", "topic": "nli"}, {"id": "VM-Y10-NLI-130", "skill": "Exponential models", "difficulty": "easy", "question": "A culture triples every hour. It begins with 14 cells. How many after two hours?", "answer": "126", "solution": "14 × 3² = 126.", "topic": "nli"}, {"id": "VM-Y10-NLI-132", "skill": "Quadratic graphs", "difficulty": "medium", "question": "Find the axis of symmetry of y = (x − 8)(x + 2).", "answer": "x = 3", "solution": "Roots are 8 and −2; their average is 3.", "topic": "nli"}, {"id": "VM-Y10-NLI-133", "skill": "Exponential models", "difficulty": "medium", "question": "A quantity follows Q = 240(0.75)^t. State its percentage decrease each period.", "answer": "25%", "solution": "1 − 0.75 = 0.25.", "topic": "nli"}, {"id": "VM-Y10-NLI-134", "skill": "Quadratic modelling", "difficulty": "medium", "question": "A square garden has side length x metres. Its area is A = x². How much larger is the area when x increases from 4 to 6?", "answer": "20 m²", "solution": "6² − 4² = 36 − 16 = 20 m².", "topic": "nli"}, {"id": "VM-Y10-NLI-135", "skill": "Quadratic models", "difficulty": "medium", "question": "A ball follows h = 18t − 3t². Find its height at t = 4. Height h is in metres and time t is in seconds.", "answer": "24 m", "solution": "18×4 − 3×16 = 24.", "topic": "nli"}, {"id": "VM-Y10-NLI-136", "skill": "Graphical intersections", "difficulty": "medium", "question": "A parabola y = x² − 4 intersects the horizontal line y = 5. Find both intersection points.", "answer": "(−3, 5) and (3, 5)", "solution": "x² − 4 = 5, so x² = 9 and x = ±3. Both points have y = 5.", "topic": "nli"}, {"id": "VM-Y10-NLI-137", "skill": "Quadratic models", "difficulty": "hard", "question": "A rectangle has perimeter 44 cm. Express area in terms of width w and find the maximum area.", "answer": "A = 22w − w²; 121 cm²", "solution": "Length=22−w. Complete square: A=121−(w−11)².", "topic": "nli"}, {"id": "VM-Y10-NLI-138", "skill": "Exponential models", "difficulty": "hard", "question": "A machine retains 80% of its value annually. After two years it is worth $3840. Find its initial value.", "answer": "$6000", "solution": "3840 ÷ 0.8² = 6000.", "topic": "nli"}, {"id": "VM-Y10-NLI-139", "skill": "Quadratic graphs", "difficulty": "hard", "question": "A parabola has vertex (2, −3) and passes through (5, 15). Find its equation.", "answer": "y = 2(x − 2)² − 3", "solution": "15 = 9a − 3, hence a=2.", "topic": "nli"}, {"id": "VM-Y10-NLI-140", "skill": "Non-linear reasoning", "difficulty": "challenge", "question": "A positive quantity grows continuously according to Q = 2^t. A second quantity follows R = 8(1/2)^t, where t is measured in days. After how many days are they equal?", "answer": "1.5 days", "solution": "2^t = 8(1/2)^t, so 2^(2t)=2³ and t=1.5.", "topic": "nli"}, {"skill": "Parabola", "difficulty": "easy", "question": "Which direction does y = −2x² open?", "answer": "Downward", "solution": "The coefficient of x² is negative.", "id": "VM-Y10-NLI-R01", "topic": "nli"}, {"skill": "Exponential", "difficulty": "easy", "question": "Find y when x = 0 in y = 7 × 2ˣ.", "answer": "7", "solution": "Any positive base raised to zero equals 1.", "id": "VM-Y10-NLI-R02", "topic": "nli"}, {"skill": "Symmetry", "difficulty": "easy", "question": "Give the axis of symmetry of y = 4x² + 6.", "answer": "x = 0", "solution": "Opposite inputs have equal outputs.", "id": "VM-Y10-NLI-R03", "topic": "nli"}, {"skill": "Graph comparison", "difficulty": "medium", "question": "Compare the widths of y = x² and y = 0.25x².", "answer": "The second is wider", "solution": "At the same nonzero x its height is one quarter as large.", "id": "VM-Y10-NLI-R04", "topic": "nli"}, {"skill": "Exponential asymptote", "difficulty": "medium", "question": "Does y = 5 × (0.2)ˣ ever reach zero? Explain.", "answer": "No", "solution": "Every finite power of a positive base is positive; the curve approaches zero.", "id": "VM-Y10-NLI-R05", "topic": "nli"}, {"skill": "Graph intersection", "difficulty": "hard", "question": "Find the intersections of y = x² and y = 3x + 4 by checking integer inputs from −2 to 5.", "answer": "(−1,1) and (4,16)", "solution": "At −1 both outputs are 1; at 4 both are 16. Plot both curves to confirm.", "id": "VM-Y10-NLI-R06", "topic": "nli"}, {"skill": "Model comparison", "difficulty": "hard", "question": "At x = 0,1,2,3 compare y = 2ˣ and y = x². When is the quadratic larger?", "answer": "x = 3 only", "solution": "Outputs are 1,2,4,8 and 0,1,4,9 respectively.", "id": "VM-Y10-NLI-R07", "topic": "nli"}, {"skill": "Quadratic symmetry", "difficulty": "hard", "question": "A parabola y = ax² + c passes through (−3,20) and (0,2). Find its output at x = 3 and x = 1.", "answer": "20 and 4", "solution": "Symmetry gives 20; 9a + 2 = 20 so a = 2.", "id": "VM-Y10-NLI-R08", "topic": "nli"}, {"skill": "Exponential models", "difficulty": "hard", "question": "A population triples every hour. At hour 2 it is 450. Find its initial size and hour 4 size.", "answer": "50; 4050", "solution": "Divide 450 by 9 to go back two hours; multiply by 9 to go forward two.", "id": "VM-Y10-NLI-R09", "topic": "nli"}, {"id": "VM-Y10-PRO-001", "skill": "Independence", "difficulty": "easy", "question": "A fair coin is tossed twice. Does the first result affect the probability of heads on the second toss?", "answer": "No", "solution": "Independent tosses each have probability 1/2 of heads.", "topic": "pro"}, {"id": "VM-Y10-PRO-002", "skill": "Outcomes", "difficulty": "easy", "question": "List all ordered outcomes of two coin tosses.", "answer": "HH, HT, TH, TT", "solution": "Each first outcome can be followed by H or T.", "topic": "pro"}, {"id": "VM-Y10-PRO-003", "skill": "Independent events", "difficulty": "medium", "question": "A fair die and fair coin are used. Find the probability of rolling a 6 and tossing tails.", "answer": "1/12", "solution": "Multiply 1/6 by 1/2.", "topic": "pro"}, {"id": "VM-Y10-PRO-004", "skill": "Dependent events", "difficulty": "medium", "question": "A bag has 3 red and 2 blue counters. Draw two without replacement. Find probability both are red.", "answer": "3/10", "solution": "Multiply 3/5 by 2/4.", "topic": "pro"}, {"id": "VM-Y10-PRO-005", "skill": "Complement", "difficulty": "hard", "question": "A fair die is rolled three times. Find probability of at least one six.", "answer": "91/216", "solution": "Subtract probability of no six: 1 − (5/6)^3 = 91/216.", "topic": "pro"}, {"id": "VM-Y10-PRO-006", "skill": "Simulation", "difficulty": "hard", "question": "Describe a fair-die simulation of a player winning with probability 1/3, and how to estimate the chance of two consecutive wins.", "answer": "Use 1 or 2 as a win. Repeat independent pairs of rolls and divide the number of pairs with two wins by the total number of pairs.", "solution": "Count pairs with two wins and divide by the total number of pairs; theoretical probability is 1/9.", "topic": "pro"}, {"id": "VM-Y10-PRO-007", "skill": "Replacement", "difficulty": "medium", "question": "A bag contains 4 green and 6 yellow counters. Two are drawn with replacement. Find probability both are green.", "answer": "4/25", "solution": "(4/10)² = 16/100.", "topic": "pro"}, {"id": "VM-Y10-PRO-008", "skill": "Conditional reasoning", "difficulty": "medium", "question": "A standard deck is shuffled. One ace is removed. What is the probability the next card is an ace?", "answer": "3/51 = 1/17", "solution": "Three aces remain among 51 cards.", "topic": "pro"}, {"id": "VM-Y10-PRO-009", "skill": "Exactly one", "difficulty": "medium", "question": "Two fair coins are tossed. Find probability of exactly one head.", "answer": "1/2", "solution": "HT and TH are two of four equally likely outcomes.", "topic": "pro"}, {"id": "VM-Y10-PRO-010", "skill": "Unequal outcomes", "difficulty": "hard", "question": "A spinner has red probability 0.2 and blue probability 0.8. It is spun twice independently. Find probability of different colours.", "answer": "0.32", "solution": "0.2×0.8 + 0.8×0.2.", "topic": "pro"}, {"id": "VM-Y10-PRO-011", "skill": "Error analysis", "difficulty": "medium", "question": "A student says the probability of two sixes on two fair dice is 1/6 + 1/6. Correct the calculation.", "answer": "1/36", "solution": "Both independent events must occur, so multiply.", "topic": "pro"}, {"id": "VM-Y10-PRO-012", "skill": "Simulation design", "difficulty": "medium", "question": "Use random digits 0–9 to simulate a success probability of 0.7.", "answer": "Assign 0–6 to success and 7–9 to failure.", "solution": "Seven of ten equally likely digits represent success.", "topic": "pro"}, {"id": "VM-Y10-PRO-013", "skill": "Experimental probability", "difficulty": "easy", "question": "A simulation produces 47 successes in 200 trials. Estimate success probability.", "answer": "0.235", "solution": "47 ÷ 200.", "topic": "pro"}, {"id": "VM-Y10-PRO-014", "skill": "Tree reasoning", "difficulty": "hard", "question": "A bag has 2 red and 3 blue counters. Draw two without replacement. Find probability of one of each colour.", "answer": "3/5", "solution": "2/5×3/4 + 3/5×2/4 = 3/5.", "topic": "pro"}, {"id": "VM-Y10-PRO-015", "skill": "Independence test", "difficulty": "hard", "question": "P(A)=0.4, P(B)=0.5 and P(A and B)=0.1. Are A and B independent?", "answer": "No", "solution": "Independence requires 0.4×0.5 = 0.2, not 0.1.", "topic": "pro"}, {"id": "VM-Y10-PRO-016", "skill": "Complement", "difficulty": "medium", "question": "A machine independently produces a defective item with probability 0.02. Find probability neither of two items is defective.", "answer": "0.9604", "solution": "0.98² = 0.9604.", "topic": "pro"}, {"id": "VM-Y10-PRO-017", "skill": "Tree interpretation", "difficulty": "hard", "question": "A bag has 3 red and 1 blue counter. Two draws are made without replacement. Give the probability of red then blue and blue then red.", "answer": "1/4 each", "solution": "3/4 × 1/3 = 1/4; 1/4 × 3/3 = 1/4.", "topic": "pro"}, {"id": "VM-Y10-PRO-018", "skill": "Game fairness", "difficulty": "hard", "question": "A game pays a win if two fair dice show the same number. Is winning more likely than losing?", "answer": "No", "solution": "There are 6 matching outcomes out of 36; win probability 1/6.", "topic": "pro"}, {"id": "VM-Y10-PRO-020", "skill": "Simulation critique", "difficulty": "hard", "question": "A student uses a fair coin to simulate an event with probability 0.3 by treating heads as success. Explain why this fails.", "answer": "Heads has probability 0.5, not 0.3", "solution": "Use ten equally likely digits and designate three as successes instead.", "topic": "pro"}, {"id": "VM-Y10-PRO-021", "skill": "Reverse probability", "difficulty": "hard", "question": "Two independent attempts each have success probability p. The probability both succeed is 0.49. Find p.", "answer": "0.7", "solution": "p² = 0.49; probability is nonnegative.", "topic": "pro"}, {"id": "VM-Y10-PRO-022", "skill": "Experimental reasoning", "difficulty": "hard", "question": "Two groups simulate the same random experiment, using 20 and 2000 trials. Which estimate is generally more stable?", "answer": "The 2000-trial estimate", "solution": "Larger samples generally reduce random sampling variability, though accuracy is not guaranteed.", "topic": "pro"}, {"id": "VM-Y10-PRO-023", "skill": "Outcome listing", "difficulty": "easy", "question": "A coin is tossed and a spinner labelled A, B, C is spun. List all ordered outcomes.", "answer": "HA, HB, HC, TA, TB, TC", "solution": "Pair each of two coin outcomes with each of three spinner outcomes.", "topic": "pro"}, {"id": "VM-Y10-PRO-024", "skill": "Replacement comparison", "difficulty": "medium", "question": "A bag contains 3 red and 2 blue counters. Compare the probability of blue on the second draw after a red first draw, with and without replacement.", "answer": "2/5 with; 1/2 without", "solution": "Replacement restores five counters; otherwise four remain including two blue.", "topic": "pro"}, {"id": "VM-Y10-PRO-025", "skill": "Tree completion", "difficulty": "medium", "question": "The first branch of a tree has probability 0.3. Its two second-stage branches have probabilities 0.4 and an unknown value. Find the unknown and the probability of following the 0.3 then unknown branch.", "answer": "0.6; 0.18", "solution": "Second-stage probabilities sum to 1; multiply 0.3 × 0.6.", "topic": "pro"}, {"id": "VM-Y10-PRO-026", "skill": "Simulation mapping", "difficulty": "hard", "question": "Design a fair six-sided die simulation of an event with probability 1/3.", "answer": "Treat 1 or 2 as success", "solution": "Two of six equally likely faces represent success.", "topic": "pro"}, {"id": "VM-Y10-PRO-027", "skill": "Dependence reasoning", "difficulty": "challenge", "question": "Two cards are drawn without replacement from a deck. Does the second card necessarily have a different colour from the first? Explain.", "answer": "No", "solution": "Without replacement changes conditional probabilities but does not force opposite colours.", "topic": "pro"}, {"id": "VM-Y10-PRO-028", "skill": "Simulation interpretation", "difficulty": "hard", "question": "A simulation gives 47 successes in 100 trials for an event with theoretical probability 0.5. Does this alone prove the simulation is faulty?", "answer": "No", "solution": "Random variation can produce 47 rather than exactly 50 successes.", "topic": "pro"}, {"id": "VM-Y10-PRO-029", "skill": "Complement", "difficulty": "easy", "question": "The probability of rain is 0.35. What is the probability of no rain?", "answer": "0.65", "solution": "1 − 0.35 = 0.65.", "topic": "pro"}, {"id": "VM-Y10-PRO-030", "skill": "Replacement", "difficulty": "easy", "question": "A marble is drawn from a bag and returned before a second draw. Does the first draw change the bag composition for the second draw?", "answer": "No", "solution": "Replacement restores the original composition.", "topic": "pro"}, {"id": "VM-Y10-PRO-031", "skill": "Fair game", "difficulty": "challenge", "question": "A fair six-sided die is rolled. A player receives $12 for a six and nothing otherwise. What entry fee makes the expected net gain zero?", "answer": "$2", "solution": "Expected payout = 12 × 1/6 = 2.", "topic": "pro"}, {"id": "VM-Y10-PRO-032", "skill": "Dependence reasoning", "difficulty": "challenge", "question": "A bag contains two red and two blue counters. Two are drawn without replacement. Are the events first red and second red independent?", "answer": "No", "solution": "P(second red) = 1/2, but P(second red given first red) = 1/3.", "topic": "pro"}, {"id": "VM-Y10-PRO-033", "skill": "Tree labels", "difficulty": "easy", "question": "A tree diagram for tossing a fair coin twice starts with H and T branches. What probabilities belong on the second-stage branches?", "answer": "1/2 on each branch", "solution": "The second fair toss is independent of the first.", "topic": "pro"}, {"id": "VM-Y10-PRO-034", "skill": "Outcome grid", "difficulty": "medium", "question": "Construct a 3 by 3 outcome grid for two independent draws with replacement from cards numbered 1, 2, 3. Find the probability that the sum is 4.", "answer": "1/3", "solution": "Favourable ordered pairs are (1,3), (2,2), (3,1), out of nine equally likely pairs.", "topic": "pro"}, {"id": "VM-Y10-PRO-035", "skill": "Simulation design", "difficulty": "hard", "question": "A spinner has outcomes A, B and C with probabilities 0.2, 0.3 and 0.5. Assign digits 0–9 to simulate one spin using a uniform random digit.", "answer": "A: 0–1; B: 2–4; C: 5–9 (one valid mapping)", "solution": "Assign 2, 3 and 5 of the ten equally likely digits respectively.", "topic": "pro"}, {"id": "VM-Y10-PRO-036", "skill": "Tree comparison", "difficulty": "challenge", "question": "A bag contains two red and three blue counters. Compare the probability of drawing two different colours with and without replacement.", "answer": "12/25 with replacement; 3/5 without", "solution": "With: 2(2/5)(3/5)=12/25. Without: (2/5)(3/4)+(3/5)(2/4)=3/5.", "topic": "pro"}, {"id": "VM-Y10-PRO-037", "skill": "Quality control", "difficulty": "medium", "question": "Two independent components each have a 0.1 probability of failure. Find the probability that at least one fails.", "answer": "0.19", "solution": "Complement: probability neither fails = 0.9² = 0.81; subtract from 1.", "topic": "pro"}, {"id": "VM-Y10-PRO-038", "skill": "Ticket decision", "difficulty": "hard", "question": "A box contains 3 winning and 7 losing tickets. Two tickets are drawn without replacement. Find the probability of winning exactly once.", "answer": "7/15", "solution": "Win then lose: 3/10 × 7/9. Lose then win: 7/10 × 3/9. Sum = 42/90 = 7/15.", "topic": "pro"}, {"id": "VM-Y10-PRO-039", "skill": "Expected comparison", "difficulty": "hard", "question": "Game A wins on a six from a fair die. Game B wins if two fair coins both show heads. Which game should win more often over 120 plays, and by how many expected wins?", "answer": "Game B; 10 more", "solution": "A: 120/6 = 20. B: 120/4 = 30. Difference = 10; actual results may vary.", "topic": "pro"}, {"id": "VM-Y10-PRO-041", "skill": "Certain event", "difficulty": "easy", "question": "A bag contains only red and blue counters. What is the probability of drawing either a red or a blue counter?", "answer": "1", "solution": "Every possible draw belongs to the stated event.", "topic": "pro"}, {"id": "VM-Y10-PRO-042", "skill": "Outcome distinction", "difficulty": "easy", "question": "A coin is tossed twice. Are HT and TH the same ordered outcome?", "answer": "No", "solution": "The first and second tosses occur in different orders.", "topic": "pro"}, {"id": "VM-Y10-PRO-043", "skill": "Conditional denominator", "difficulty": "medium", "question": "A bag contains 5 green and 3 yellow counters. One green counter is removed. What is the probability that the next counter is yellow?", "answer": "3/7", "solution": "Seven counters remain, including all three yellow counters.", "topic": "pro"}, {"id": "VM-Y10-PRO-044", "skill": "Simulation tally", "difficulty": "medium", "question": "A simulation produces 46 successes and 54 failures. How many additional successes, with no additional failures, would make the experimental success proportion exactly one half?", "answer": "8", "solution": "The success and failure counts must be equal: 54 − 46 = 8.", "topic": "pro"}, {"id": "VM-Y10-PRO-045", "skill": "Complement", "difficulty": "easy", "question": "A machine has a 0.08 probability of rejecting a correctly made item. What is the probability it does not reject that item?", "answer": "0.92", "solution": "Complement = 1 − 0.08.", "topic": "pro"}, {"id": "VM-Y10-PRO-046", "skill": "Independent events", "difficulty": "medium", "question": "A fair coin and a fair six-sided die are used. Find the probability of tails and a die result greater than 4.", "answer": "1/6", "solution": "Multiply 1/2 by 2/6 to obtain 1/6.", "topic": "pro"}, {"id": "VM-Y10-PRO-047", "skill": "Independent events", "difficulty": "hard", "question": "Two independent fair dice are rolled. Find the probability that the first shows 6 and the total is at least 10.", "answer": "\\(\\frac{1}{12}\\)", "solution": "First die must show 6; second must show 4, 5 or 6. Multiply: \\(\\frac16\\times\\frac36=\\frac1{12}\\).", "topic": "pro"}, {"id": "VM-Y10-PRO-048", "skill": "Simulation investigation", "difficulty": "challenge", "question": "A game is won if at least one of two independent fair coin tosses is heads. A simulation counts only HH as a win. Explain the bias and give the theoretical win probability.", "answer": "It underestimates wins; 3/4", "solution": "HH, HT and TH all win; only TT loses. Each outcome has probability 1/4.", "topic": "pro"}, {"id": "VM-Y10-PRO-049", "skill": "Impossible event", "difficulty": "easy", "question": "A standard six-sided die is rolled twice. What is the probability that the sum is 13?", "answer": "0", "solution": "The largest possible sum is 12.", "topic": "pro"}, {"id": "VM-Y10-PRO-051", "skill": "Unequal branches", "difficulty": "hard", "question": "A fair coin chooses bag A or B. A contains 1 red and 3 blue counters; B contains 3 red and 1 blue. One counter is drawn. Find the probability it is red.", "answer": "1/2", "solution": "Add the two red paths: (1/2)(1/4) + (1/2)(3/4) = 1/2.", "topic": "pro"}, {"id": "VM-Y10-PRO-052", "skill": "Independence counterexample", "difficulty": "challenge", "question": "A fair die is rolled. Event A is rolling an even number; B is rolling a number greater than 3. Both have probability 1/2. Are they independent?", "answer": "No", "solution": "Their intersection is {4,6}, with probability 1/3, not the product 1/4.", "topic": "pro"}, {"id": "VM-Y10-PRO-054", "skill": "At least one success", "difficulty": "medium", "question": "A fair coin is tossed three times. Find the probability of at least one tail.", "answer": "7/8", "solution": "The complement is three heads, with probability (1/2)³=1/8. Subtract from 1.", "topic": "pro"}, {"id": "VM-Y10-PRO-055", "skill": "Unequal spinner", "difficulty": "hard", "question": "A spinner lands on red with probability 0.3. It is spun twice independently. Find the probability of exactly one red.", "answer": "0.42", "solution": "Red then not red or not red then red: 2×0.3×0.7=0.42.", "topic": "pro"}, {"id": "VM-Y10-PRO-056", "skill": "Dependence reasoning", "difficulty": "challenge", "question": "A bag contains two red and one blue counter. Two counters are drawn without replacement. Explain why the colour of the second draw depends on the first.", "answer": "The first draw changes the colour proportions.", "solution": "After red, the probability of blue is \\(\\frac12\\); after blue, it is 0. The second-stage probabilities depend on the first result.", "topic": "pro"}, {"id": "VM-Y10-PRO-057", "skill": "Sample space", "difficulty": "easy", "question": "A coin is tossed and a spinner labelled A, B is spun. List all ordered outcomes.", "answer": "HA, HB, TA, TB", "solution": "Pair each coin outcome H or T with each spinner outcome A or B.", "topic": "pro"}, {"id": "VM-Y10-PRO-058", "skill": "Two-stage complement", "difficulty": "medium", "question": "A fair coin is tossed and a fair die rolled independently. Find the probability that neither a head nor a six occurs.", "answer": "5/12", "solution": "P(tail and not six) = 1/2 × 5/6 = 5/12.", "topic": "pro"}, {"id": "VM-Y10-PRO-060", "skill": "Simulation validity", "difficulty": "challenge", "question": "A student simulates two independent fair coin tosses using one fair coin toss, recording HH for heads and TT for tails. Explain why the simulation is invalid and give a valid alternative.", "answer": "It excludes HT and TH; toss the coin twice independently.", "solution": "The intended four ordered outcomes each have probability 1/4. The proposed simulation gives only HH and TT, each with probability 1/2.", "topic": "pro"}, {"id": "VM-Y10-PRO-061", "skill": "Outcome recording", "difficulty": "easy", "question": "A coin is tossed twice. If only the number of heads is recorded, do HT and TH give different recorded results?", "answer": "No", "solution": "Both outcomes contain exactly one head.", "topic": "pro"}, {"id": "VM-Y10-PRO-062", "skill": "Unequal branch probability", "difficulty": "medium", "question": "A bag contains 3 red and 2 blue counters. Two are drawn without replacement. Find the probability the second is blue given the first is red.", "answer": "1/2", "solution": "After removing a red counter, 2 of the remaining 4 counters are blue.", "topic": "pro"}, {"id": "VM-Y10-PRO-063", "skill": "Simulation coding", "difficulty": "hard", "question": "A fair six-sided die is used to simulate a 1/3 chance of rain on each of three independent days. Describe how to estimate the chance of rain on exactly two days.", "answer": "Assign 1–2 to rain; roll three times per trial and count trials with exactly two rain outcomes.", "solution": "Repeat many trials independently. Divide the number of qualifying trials by the total number of trials.", "topic": "pro"}, {"id": "VM-Y10-PRO-065", "skill": "Impossible outcome", "difficulty": "easy", "question": "A standard six-sided die is rolled once. Can the result be both odd and divisible by 2?", "answer": "No", "solution": "Odd integers are not divisible by 2, so the intersection is empty.", "topic": "pro"}, {"id": "VM-Y10-PRO-066", "skill": "Complement of repeated event", "difficulty": "medium", "question": "A fair six-sided die is rolled twice independently. Find the probability that neither roll is a six.", "answer": "25/36", "solution": "Each roll has probability 5/6 of not being six; multiply to obtain 25/36.", "topic": "pro"}, {"id": "VM-Y10-PRO-068", "skill": "Simulation mapping critique", "difficulty": "challenge", "question": "A game has three equally likely outcomes. A student simulates it using a fair die: 1 or 2 means A, 3 means B, and 4, 5 or 6 means C. Explain the bias and repair the mapping.", "answer": "The probabilities are 2/6, 1/6 and 3/6; assign two faces to each outcome.", "solution": "For example A: 1–2, B: 3–4, C: 5–6. Each then has probability 1/3.", "topic": "pro"}, {"id": "VM-Y10-PRO-069", "skill": "Sample space size", "difficulty": "easy", "question": "A spinner has three labelled sectors and a coin has two faces. How many ordered spinner–coin outcomes are possible?", "answer": "6", "solution": "3 × 2 = 6.", "topic": "pro"}, {"id": "VM-Y10-PRO-070", "skill": "Without replacement", "difficulty": "medium", "question": "A bag contains 4 red and 2 blue counters. Two are drawn without replacement. Find the probability that both are blue.", "answer": "1/15", "solution": "P = 2/6 × 1/5 = 1/15.", "topic": "pro"}, {"id": "VM-Y10-PRO-072", "skill": "Simulation design", "difficulty": "challenge", "question": "A game succeeds with probability 0.3. A student simulates it using a fair six-sided die, assigning exactly two faces to success. Is this an exact model? Propose an exact alternative.", "answer": "No; use ten equally likely outcomes with three successes", "solution": "Two die faces give 1/3, not 0.3. Three of ten equally likely outcomes give 3/10.", "topic": "pro"}, {"id": "VM-Y10-PRO-073", "skill": "Complement", "difficulty": "easy", "question": "The probability that a bus arrives on time is 0.72. Find the probability it does not arrive on time.", "answer": "0.28", "solution": "1 − 0.72 = 0.28.", "topic": "pro"}, {"id": "VM-Y10-PRO-074", "skill": "Independent events", "difficulty": "medium", "question": "A fair coin is tossed and a fair eight-sided die numbered 1 to 8 is rolled independently. Find the probability of tails and a multiple of 3.", "answer": "1/8", "solution": "Multiples are 3 and 6. Multiply 1/2 by 2/8 = 1/8.", "topic": "pro"}, {"id": "VM-Y10-PRO-075", "skill": "Relative frequency", "difficulty": "medium", "question": "A simulation produces 37 successes in 125 trials. Estimate the probability of success as a percentage.", "answer": "29.6%", "solution": "37 ÷ 125 × 100 = 29.6.", "topic": "pro"}, {"id": "VM-Y10-PRO-077", "skill": "Certain event", "difficulty": "easy", "question": "A bag contains only red and blue counters. What is the probability of drawing a green counter?", "answer": "0", "solution": "There are no green counters.", "topic": "pro"}, {"id": "VM-Y10-PRO-078", "skill": "Independent events", "difficulty": "medium", "question": "Two independent fair coins are tossed. Find the probability that the second result matches the first.", "answer": "1/2", "solution": "For either first result, exactly one of two equally likely second results matches.", "topic": "pro"}, {"id": "VM-Y10-PRO-079", "skill": "Without replacement", "difficulty": "medium", "question": "A box contains 4 black and 6 white beads. Two are drawn without replacement. Find the probability both are black.", "answer": "2/15", "solution": "Multiply 4/10 by 3/9 = 12/90 = 2/15.", "topic": "pro"}, {"id": "VM-Y10-PRO-080", "skill": "Complement strategy", "difficulty": "hard", "question": "Three independent fair die rolls are made. Find the probability that at least one roll is even and at least one is odd.", "answer": "3/4", "solution": "Exclude all even and all odd: 1 − 2(1/2)³ = 3/4.", "topic": "pro"}, {"id": "VM-Y10-PRO-081", "skill": "Impossible event", "difficulty": "easy", "question": "A standard six-sided die is rolled once. What is the probability of obtaining a multiple of 7?", "answer": "0", "solution": "No face from 1 to 6 is a multiple of 7.", "topic": "pro"}, {"id": "VM-Y10-PRO-082", "skill": "Ordered outcomes", "difficulty": "medium", "question": "A fair coin is tossed and a fair four-sided die numbered 1 to 4 is rolled. Find the probability of tails and an even number.", "answer": "1/4", "solution": "Two favourable outcomes out of eight equally likely outcomes.", "topic": "pro"}, {"id": "VM-Y10-PRO-083", "skill": "Complement frequency", "difficulty": "medium", "question": "In 250 trials an event occurs 85 times. Estimate the probability that it does not occur.", "answer": "0.66", "solution": "Non-occurrences = 165; 165 ÷ 250 = 0.66.", "topic": "pro"}, {"skill": "Complement", "difficulty": "easy", "question": "A weather model assigns probability 0.37 to rain tomorrow. Find the probability of no rain.", "answer": "0.63", "solution": "Complement = 1 − 0.37.", "id": "VM-Y10-PRO-085", "topic": "pro"}, {"skill": "Independent trials", "difficulty": "medium", "question": "An independent fair coin and fair die are used. Find the probability of heads and a prime number on the die.", "answer": "1/4", "solution": "Prime outcomes are 2, 3, 5; multiply 1/2 by 3/6.", "id": "VM-Y10-PRO-086", "topic": "pro"}, {"skill": "Without replacement", "difficulty": "hard", "question": "A box contains four red and three blue tokens. Two are drawn without replacement. Find the probability that the colours differ.", "answer": "4/7", "solution": "P(RB or BR) = (4/7)(3/6) + (3/7)(4/6) = 4/7.", "id": "VM-Y10-PRO-087", "topic": "pro"}, {"id": "VM-Y10-PRO-089", "skill": "Impossible event", "difficulty": "easy", "question": "A standard six-sided die is rolled. Find the probability of obtaining a negative number.", "answer": "0", "solution": "No face has a negative number.", "topic": "pro"}, {"id": "VM-Y10-PRO-090", "skill": "Complement of repeated trials", "difficulty": "medium", "question": "A fair die is rolled twice. Find the probability that at least one roll is a six.", "answer": "11/36", "solution": "P(no six) = (5/6)² = 25/36; subtract from 1.", "topic": "pro"}, {"id": "VM-Y10-PRO-092", "skill": "Mixture probability", "difficulty": "hard", "question": "A fair coin selects bag A or B. Bag A has 3 red and 1 blue counter; bag B has 1 red and 4 blue counters. Find the probability of red.", "answer": "19/40", "solution": "Add the disjoint paths: (1/2)(3/4) + (1/2)(1/5) = 19/40.", "topic": "pro"}, {"id": "VM-Y10-PRO-093", "skill": "Complement", "difficulty": "easy", "question": "The probability that a parcel arrives late is 0.17. Find the probability it is not late.", "answer": "0.83", "solution": "1 − 0.17 = 0.83.", "topic": "pro"}, {"id": "VM-Y10-PRO-095", "skill": "Experimental probability", "difficulty": "medium", "question": "A spinner lands on blue 27 times in 90 spins. Estimate the number of blue results in another 200 spins.", "answer": "60", "solution": "Relative frequency = 27 ÷ 90 = 0.3; 200 × 0.3 = 60.", "topic": "pro"}, {"id": "VM-Y10-PRO-097", "skill": "Conditional probability", "difficulty": "hard", "question": "A bag contains 4 red and 6 green counters. Two are drawn without replacement. Given the first is green, find the probability the second is red.", "answer": "4/9", "solution": "After removing a green counter, 4 red remain among 9 counters.", "topic": "pro"}, {"id": "VM-Y10-PRO-098", "skill": "At least one", "difficulty": "hard", "question": "Three independent sensors each work with probability 0.8. Find the probability that at least one works.", "answer": "0.992", "solution": "Subtract probability all fail: 1 − 0.2³ = 0.992.", "topic": "pro"}, {"id": "VM-Y10-PRO-099", "skill": "Complement", "difficulty": "easy", "question": "An event and its complement have equal probabilities. Find the probability of the event.", "answer": "1/2", "solution": "Their probabilities sum to 1 and are equal.", "topic": "pro"}, {"id": "VM-Y10-PRO-100", "skill": "Equally likely outcomes", "difficulty": "easy", "question": "A fair eight-sided die is numbered 1 to 8. Find the probability of a multiple of 3.", "answer": "1/4", "solution": "Two favourable outcomes, 3 and 6, out of eight.", "topic": "pro"}, {"id": "VM-Y10-PRO-101", "skill": "Independent events", "difficulty": "medium", "question": "A fair coin and a fair six-sided die are used. Find the probability of tails and an even number.", "answer": "1/4", "solution": "Multiply 1/2 by 3/6.", "topic": "pro"}, {"id": "VM-Y10-PRO-102", "skill": "Without replacement", "difficulty": "medium", "question": "A bag contains 3 red and 5 blue tokens. Two are drawn without replacement. Find the probability of blue then red.", "answer": "15/56", "solution": "Multiply 5/8 by 3/7.", "topic": "pro"}, {"id": "VM-Y10-PRO-104", "skill": "Reverse probability", "difficulty": "hard", "question": "A bag contains only red and blue counters. Two draws with replacement give probability 0.49 of two red counters. If there are 30 counters, how many are red?", "answer": "21", "solution": "Red probability is √0.49 = 0.7; 30 × 0.7 = 21.", "topic": "pro"}, {"id": "VM-Y10-PRO-105", "skill": "Complement", "difficulty": "easy", "question": "A spinner has probability 0.18 of landing on yellow. Find the probability of not yellow.", "answer": "0.82", "solution": "1 − 0.18 = 0.82.", "topic": "pro"}, {"id": "VM-Y10-PRO-106", "skill": "Independent events", "difficulty": "easy", "question": "A fair coin is tossed twice independently. Does the first toss change the probability of heads on the second?", "answer": "No", "solution": "The probability of heads remains one half regardless of the first toss.", "topic": "pro"}, {"id": "VM-Y10-PRO-107", "skill": "Sample space", "difficulty": "medium", "question": "A fair coin and a fair four-sided die numbered 1 to 4 are used. Find the probability of heads and a number greater than 2.", "answer": "1/4", "solution": "Independent probability = 1/2 × 2/4.", "topic": "pro"}, {"id": "VM-Y10-PRO-108", "skill": "Experimental frequency", "difficulty": "medium", "question": "A machine produces 18 defective items in a sample of 600. Estimate the number defective in a future batch of 1500.", "answer": "45", "solution": "Estimated rate = 18/600 = 0.03; multiply by 1500.", "topic": "pro"}, {"id": "VM-Y10-PRO-110", "skill": "Dependent events", "difficulty": "hard", "question": "A box has 5 red and 3 green balls. Two are drawn without replacement. Given the first is green, find the probability that the second is a different colour.", "answer": "5/7", "solution": "After removing one green, 5 red remain among 7 balls.", "topic": "pro"}, {"id": "VM-Y10-PRO-111", "skill": "Complement", "difficulty": "easy", "question": "A forecast gives a 25% chance of rain. Express the probability of no rain as a fraction in simplest form.", "answer": "3/4", "solution": "100% − 25% = 75% = 3/4.", "topic": "pro"}, {"id": "VM-Y10-PRO-112", "skill": "Sample space", "difficulty": "easy", "question": "A spinner has four labelled outcomes and a coin has two. How many ordered outcome pairs are possible?", "answer": "8", "solution": "4 × 2 = 8.", "topic": "pro"}, {"id": "VM-Y10-PRO-114", "skill": "Expected frequency", "difficulty": "medium", "question": "A biased spinner lands on blue with probability 0.35. Find the expected number of blue results in 240 spins.", "answer": "84", "solution": "240 × 0.35 = 84.", "topic": "pro"}, {"id": "VM-Y10-PRO-115", "skill": "Without replacement", "difficulty": "hard", "question": "A bag contains 5 red and 3 yellow counters. Two are drawn without replacement. Find the probability of exactly one yellow.", "answer": "15/28", "solution": "RY or YR: 5/8 × 3/7 + 3/8 × 5/7 = 30/56 = 15/28.", "topic": "pro"}, {"id": "VM-Y10-PRO-116", "skill": "Without replacement", "difficulty": "hard", "question": "A box contains 17 red, 12 blue and 1 green counter. Two counters are drawn without replacement. Find the probability both are blue.", "answer": "\\(\\frac{22}{145}\\)", "solution": "\\(\\frac{12}{30}\\times\\frac{11}{29}=\\frac{22}{145}\\).", "topic": "pro"}, {"id": "VM-Y10-PRO-117", "skill": "Complement", "difficulty": "easy", "question": "The probability that a parcel arrives on time is 0.82. A report claims the probability it is late is 0.28. Can both be correct if these are complementary events?", "answer": "No", "solution": "Complementary probabilities must sum to 1; 0.82 + 0.28 = 1.10.", "topic": "pro"}, {"id": "VM-Y10-PRO-118", "skill": "Sample space", "difficulty": "easy", "question": "A spinner has four labels and a second spinner has three labels. How many ordered outcomes are possible?", "answer": "12", "solution": "Each of four first outcomes can be paired with three second outcomes.", "topic": "pro"}, {"id": "VM-Y10-PRO-119", "skill": "Without replacement", "difficulty": "medium", "question": "A bag contains 3 red and 7 blue beads. Two are drawn without replacement. Find the probability both are red.", "answer": "1/15", "solution": "3/10 × 2/9 = 1/15.", "topic": "pro"}, {"id": "VM-Y10-PRO-122", "skill": "Complement across trials", "difficulty": "hard", "question": "A fair four-sided die numbered 1 to 4 is rolled three times. Find the probability of at least one 4. Assume independent rolls.", "answer": "37/64", "solution": "1 − (3/4)³ = 37/64.", "topic": "pro"}, {"id": "VM-Y10-PRO-123", "skill": "Complement", "difficulty": "easy", "question": "The probability of a bus arriving late is 0.17. Find the probability it does not arrive late.", "answer": "0.83", "solution": "1 − 0.17 = 0.83.", "topic": "pro"}, {"id": "VM-Y10-PRO-124", "skill": "Sample space", "difficulty": "medium", "question": "A fair die and a fair coin are used together. Find the probability of an odd number and tails. Assume independent outcomes.", "answer": "1/4", "solution": "Three of six die outcomes are odd; multiply 1/2 by 1/2.", "topic": "pro"}, {"id": "VM-Y10-PRO-125", "skill": "Relative frequency", "difficulty": "medium", "question": "A machine produces 7 faulty items in a sample of 280. Estimate the number of faulty items in the next 800 at the same rate.", "answer": "20", "solution": "Estimated probability = 7/280 = 0.025; multiply by 800.", "topic": "pro"}, {"id": "VM-Y10-PRO-126", "skill": "Without replacement", "difficulty": "hard", "question": "A box contains 3 red, 4 blue and 5 yellow counters. Two are drawn without replacement. Find the probability neither is yellow.", "answer": "7/22", "solution": "7/12 × 6/11 = 42/132 = 7/22.", "topic": "pro"}, {"id": "VM-Y10-PRO-128", "skill": "Reverse probability", "difficulty": "challenge", "question": "A bag contains 5 green counters and some orange counters. Two counters are drawn without replacement. The probability both are green is 2/9. How many orange counters are in the bag?", "answer": "5", "solution": "Let total n. 20/[n(n − 1)] = 2/9, so n(n − 1) = 90 and n = 10. Orange = 5.", "topic": "pro"}, {"id": "VM-Y10-PRO-129", "skill": "Complement", "difficulty": "easy", "question": "A weather model gives probability 0.37 of rain. Find probability of no rain.", "answer": "0.63", "solution": "1−0.37=0.63.", "topic": "pro"}, {"id": "VM-Y10-PRO-130", "skill": "Sample space", "difficulty": "easy", "question": "A fair spinner has eight equal sectors numbered 1 to 8. Find probability of a multiple of 3.", "answer": "1/4", "solution": "Favourable sectors 3 and 6; 2/8.", "topic": "pro"}, {"id": "VM-Y10-PRO-131", "skill": "Relative frequency", "difficulty": "easy", "question": "A machine produced 9 faulty items out of 150. Estimate probability of a faulty item.", "answer": "0.06", "solution": "9/150=0.06.", "topic": "pro"}, {"id": "VM-Y10-PRO-132", "skill": "Independent events", "difficulty": "medium", "question": "A fair coin and fair six-sided die are used. Find probability of tails and a prime number. Assume independent outcomes.", "answer": "1/4", "solution": "Prime faces 2,3,5; multiply 1/2 by 3/6.", "topic": "pro"}, {"id": "VM-Y10-PRO-133", "skill": "Without replacement", "difficulty": "medium", "question": "A bag contains 5 red and 3 blue counters. Two are drawn without replacement. Find probability both are blue.", "answer": "3/28", "solution": "3/8 × 2/7 = 6/56.", "topic": "pro"}, {"id": "VM-Y10-PRO-136", "skill": "Expected frequency", "difficulty": "medium", "question": "A biased spinner lands on yellow with probability 0.28. In 350 spins, find expected yellow outcomes.", "answer": "98", "solution": "350×0.28=98.", "topic": "pro"}, {"id": "VM-Y10-PRO-137", "skill": "Compound events", "difficulty": "hard", "question": "Two fair dice are rolled. Find probability their sum is 9 or their faces are equal. Assume independent dice.", "answer": "5/18", "solution": "Four outcomes sum to 9 and six doubles; disjoint, 10/36.", "topic": "pro"}, {"id": "VM-Y10-PRO-138", "skill": "Without replacement", "difficulty": "hard", "question": "A box has 4 green and 6 orange balls. Draw two without replacement. Find probability of one of each colour.", "answer": "8/15", "solution": "4/10×6/9 + 6/10×4/9 =48/90.", "topic": "pro"}, {"id": "VM-Y10-PRO-140", "skill": "Probability reasoning", "difficulty": "challenge", "question": "A bag contains 3 red counters and n blue counters. Two counters are drawn without replacement. Probability both are red is 1/15. Find n.", "answer": "7", "solution": "6/((n+3)(n+2))=1/15, so consecutive factors multiply to 90: 10 and 9. Thus n=7.", "topic": "pro"}, {"skill": "Sample space", "difficulty": "easy", "question": "A coin and a spinner labelled 1, 2, 3 are used. How many ordered outcomes?", "answer": "6", "solution": "2 × 3 = 6.", "id": "VM-Y10-PRO-R01", "topic": "pro"}, {"skill": "Relative frequency", "difficulty": "easy", "question": "A button works on 47 of 50 trials. Estimate its success probability.", "answer": "0.94", "solution": "47 ÷ 50 = 0.94.", "id": "VM-Y10-PRO-R02", "topic": "pro"}, {"skill": "Tree labels", "difficulty": "medium", "question": "A bag contains 4 red and 3 blue counters. After drawing a red without replacement, label both next branches.", "answer": "Red 1/2; blue 1/2", "solution": "Three of each remain among six.", "id": "VM-Y10-PRO-R03", "topic": "pro"}, {"skill": "Simulation mapping", "difficulty": "medium", "question": "Use digits 0–9 to simulate an event with probability 0.3. Give a mapping. Use uniformly random digits.", "answer": "0,1,2 = success; 3–9 = failure", "solution": "Three of ten equally likely digits represent success.", "id": "VM-Y10-PRO-R04", "topic": "pro"}, {"skill": "Outcome grid", "difficulty": "medium", "question": "Two fair dice are rolled. How many ordered outcomes have sum 5?", "answer": "4", "solution": "(1,4), (2,3), (3,2), (4,1).", "id": "VM-Y10-PRO-R05", "topic": "pro"}, {"skill": "Expected frequency", "difficulty": "medium", "question": "A spinner lands on green with probability 0.35. Predict green results in 240 spins.", "answer": "84", "solution": "240 × 0.35 = 84.", "id": "VM-Y10-PRO-R06", "topic": "pro"}, {"skill": "Replacement comparison", "difficulty": "medium", "question": "A bag has 2 gold and 8 silver tokens. Is a second gold more likely after a first gold with or without replacement?", "answer": "With replacement", "solution": "With replacement 2/10; without 1/9.", "id": "VM-Y10-PRO-R07", "topic": "pro"}, {"skill": "Simulation critique", "difficulty": "medium", "question": "A student simulates a fair coin using digits 1–9, with odd digits heads. Explain the bias. Assume the digits are uniformly random.", "answer": "Heads is more likely", "solution": "Five odd and four even digits give unequal probabilities.", "id": "VM-Y10-PRO-R08", "topic": "pro"}, {"skill": "Experimental reasoning", "difficulty": "medium", "question": "Two groups record 8 successes in 20 and 44 in 100. Find the combined relative frequency.", "answer": "13/30", "solution": "52 successes in 120 trials; simplify.", "id": "VM-Y10-PRO-R09", "topic": "pro"}, {"skill": "Tree reasoning", "difficulty": "medium", "question": "A fair coin is tossed twice. Explain why exactly one head has two paths.", "answer": "HT and TH", "solution": "The order distinguishes the two outcomes.", "id": "VM-Y10-PRO-R10", "topic": "pro"}, {"skill": "Without replacement", "difficulty": "hard", "question": "Three of 8 books are mysteries. Two are selected without replacement. Find the probability neither is a mystery.", "answer": "5/14", "solution": "5/8 × 4/7 = 20/56.", "id": "VM-Y10-PRO-R11", "topic": "pro"}, {"skill": "Independent events", "difficulty": "hard", "question": "Two independent alarms fail with probabilities 0.1 and 0.2. Find the probability exactly one fails.", "answer": "0.26", "solution": "0.1 × 0.8 + 0.9 × 0.2 = 0.26.", "id": "VM-Y10-PRO-R12", "topic": "pro"}, {"skill": "Sample space", "difficulty": "hard", "question": "Two fair dice are rolled. Find the probability their product is odd. Assume independent dice.", "answer": "1/4", "solution": "Both must be odd: 3/6 × 3/6.", "id": "VM-Y10-PRO-R13", "topic": "pro"}, {"skill": "Game fairness", "difficulty": "hard", "question": "A game pays a point if two fair coins match. Otherwise the opponent gets a point. Is it fair? Assume independent coin tosses.", "answer": "Yes", "solution": "HH and TT are two of four equally likely outcomes.", "id": "VM-Y10-PRO-R14", "topic": "pro"}, {"skill": "Simulation design", "difficulty": "hard", "question": "Design a two-digit simulation for two independent events each with probability 0.4. Use independent, uniformly random digits.", "answer": "Use each digit independently; 0–3 means success", "solution": "Each digit has four success values; pairs model two independent trials.", "id": "VM-Y10-PRO-R15", "topic": "pro"}, {"skill": "Unequal branches", "difficulty": "hard", "question": "Choose a fair coin or a fair six-sided die with equal chance. Win on heads or rolling 6. Find win probability.", "answer": "1/3", "solution": "1/2 × 1/2 + 1/2 × 1/6 = 1/3.", "id": "VM-Y10-PRO-R16", "topic": "pro"}, {"skill": "Without replacement", "difficulty": "hard", "question": "A box contains 5 working and 2 faulty bulbs. Select two without replacement. Find the probability exactly one is faulty.", "answer": "10/21", "solution": "2/7 × 5/6 + 5/7 × 2/6 = 20/42.", "id": "VM-Y10-PRO-R17", "topic": "pro"}, {"skill": "Experimental probability", "difficulty": "hard", "question": "A simulation gives 36 wins in 120 trials. The theoretical probability is 1/4. How many more wins occurred than expected?", "answer": "6", "solution": "Expected 120 ÷ 4 = 30; difference 6.", "id": "VM-Y10-PRO-R18", "topic": "pro"}, {"skill": "Tree interpretation", "difficulty": "hard", "question": "A spinner gives A with probability 0.6. If A occurs, toss a fair coin; otherwise stop. Find the probability of stopping without tossing.", "answer": "0.4", "solution": "The stop branch is the complement of A.", "id": "VM-Y10-PRO-R19", "topic": "pro"}, {"skill": "Complement strategy", "difficulty": "hard", "question": "A fair die is rolled three times. Find the probability of at least one six. Assume independent rolls.", "answer": "91/216", "solution": "Subtract (5/6)³ from 1.", "id": "VM-Y10-PRO-R20", "topic": "pro"}, {"skill": "Probability reasoning", "difficulty": "challenge", "question": "A bag has 3 red and 2 blue tokens. Draw two without replacement. Compare the chance of matching colours with replacement.", "answer": "Without: 2/5; with: 13/25", "solution": "Without: (3×2+2×1)/(5×4)=2/5. With: (9+4)/25.", "id": "VM-Y10-PRO-R21", "topic": "pro"}, {"skill": "Reverse probability", "difficulty": "challenge", "question": "A bag has 10 counters. Two draws with replacement give two red with probability 0.49. How many red counters?", "answer": "7", "solution": "The single-draw probability is 0.7 because 0.7²=0.49.", "id": "VM-Y10-PRO-R22", "topic": "pro"}, {"skill": "Simulation validity", "difficulty": "challenge", "question": "A program chooses one random digit and uses it for both simulated fair coin tosses (even = heads). Explain why it fails. Assume the digit is uniformly random.", "answer": "The tosses are perfectly dependent", "solution": "Only HH and TT occur; independent tosses also allow HT and TH.", "id": "VM-Y10-PRO-R23", "topic": "pro"}, {"id": "VM-Y10-TRG-001", "skill": "Angles", "difficulty": "easy", "question": "An observer looks down from a balcony at a car. From which reference line is the angle of depression measured?", "answer": "Horizontal through the observer", "solution": "Depression is measured downward from the horizontal.", "topic": "trg"}, {"id": "VM-Y10-TRG-002", "skill": "Elevation", "difficulty": "medium", "question": "A tree casts a 12 m shadow when the sun is 35° above the horizontal. Find its height to 0.1 m. Assume a vertical tree and level ground.", "answer": "8.4 m", "solution": "Height = 12 tan 35° ≈ 8.4.", "topic": "trg"}, {"id": "VM-Y10-TRG-003", "skill": "Depression", "difficulty": "medium", "question": "A cliff is 40 m high. A boat is seen at a depression angle of 25°. Find its horizontal distance to the nearest metre. The observer is at the top of the cliff; the height is measured above the water.", "answer": "86 m", "solution": "Distance = 40 ÷ tan 25° ≈ 85.8.", "topic": "trg"}, {"id": "VM-Y10-TRG-004", "skill": "Bearings", "difficulty": "easy", "question": "Convert S 35° E to a true bearing.", "answer": "145°", "solution": "Measure clockwise from north: 180° − 35°.", "topic": "trg"}, {"id": "VM-Y10-TRG-005", "skill": "Navigation", "difficulty": "hard", "question": "A walker travels 6 km east then 8 km north. Find the true bearing of the finish from the start to the nearest degree.", "answer": "037°", "solution": "Angle east of north = arctan(6/8) ≈ 36.87°.", "topic": "trg"}, {"id": "VM-Y10-TRG-006", "skill": "Reverse bearing", "difficulty": "medium", "question": "A boat is on bearing 240° from a pier. Find the bearing of the pier from the boat.", "answer": "060°", "solution": "Reverse direction differs by 180°.", "topic": "trg"}, {"id": "VM-Y10-TRG-007", "skill": "Compass", "difficulty": "easy", "question": "Express true bearing 315° as a compass bearing.", "answer": "N 45° W", "solution": "315° is 45° west of north.", "topic": "trg"}, {"id": "VM-Y10-TRG-008", "skill": "Reference angles", "difficulty": "medium", "question": "A person on a tower sees a boat at a depression angle of 18°. What is the boat’s angle of elevation to the person?", "answer": "18°", "solution": "The horizontal reference lines are parallel; alternate interior angles are equal.", "topic": "trg"}, {"id": "VM-Y10-TRG-009", "skill": "Components", "difficulty": "medium", "question": "A boat travels 10 km on bearing 060°. Find its northward displacement.", "answer": "5 km", "solution": "10 cos 60° = 5.", "topic": "trg"}, {"id": "VM-Y10-TRG-010", "skill": "Ramp", "difficulty": "medium", "question": "A ramp rises 0.9 m over a horizontal distance of 12 m. Find its inclination to the nearest degree.", "answer": "4°", "solution": "tan θ = 0.9/12; θ ≈ 4.29°.", "topic": "trg"}, {"id": "VM-Y10-TRG-011", "skill": "Eye height", "difficulty": "hard", "question": "From 20 m away, a surveyor whose eye height is 1.6 m measures an elevation angle of 45° to a roof. Find roof height. Assume level ground and a horizontal distance.", "answer": "21.6 m", "solution": "20 tan 45° + 1.6 = 21.6.", "topic": "trg"}, {"id": "VM-Y10-TRG-012", "skill": "Error analysis", "difficulty": "medium", "question": "A student uses sin 30° = height/20 for a hill with horizontal run 20 m and inclination 30°. What ratio should be used?", "answer": "tan 30° = height/20", "solution": "The known side is adjacent, not the hypotenuse.", "topic": "trg"}, {"id": "VM-Y10-TRG-013", "skill": "Navigation", "difficulty": "hard", "question": "A drone flies 12 km south then 5 km west. Find its straight-line distance from its start and true bearing to the nearest degree.", "answer": "13 km; 203°", "solution": "Pythagoras gives 13; bearing = 180° + arctan(5/12) ≈ 203°.", "topic": "trg"}, {"id": "VM-Y10-TRG-014", "skill": "Comparison", "difficulty": "medium", "question": "Two observers at equal eye height stand on level ground at different distances from the same tower. Who measures the larger elevation angle?", "answer": "The closer observer.", "solution": "For fixed vertical rise, tan θ increases as horizontal distance decreases.", "topic": "trg"}, {"id": "VM-Y10-TRG-015", "skill": "Reverse reasoning", "difficulty": "medium", "question": "A cable is 15 m long and inclined at 30° to level ground. Find its vertical rise.", "answer": "7.5 m", "solution": "15 sin 30° = 7.5.", "topic": "trg"}, {"id": "VM-Y10-TRG-016", "skill": "Bearing change", "difficulty": "medium", "question": "A ship heading 350° turns clockwise through 35°. Give its new true bearing.", "answer": "025°", "solution": "350 + 35 − 360 = 25.", "topic": "trg"}, {"id": "VM-Y10-TRG-017", "skill": "Two-leg navigation", "difficulty": "hard", "question": "A hiker walks 4 km north then 4 km on bearing 090°. Find the direct distance and bearing home.", "answer": "4√2 km; 225°", "solution": "The displacement is northeast with equal components; the reverse direction is southwest.", "topic": "trg"}, {"id": "VM-Y10-TRG-018", "skill": "Height comparison", "difficulty": "hard", "question": "From the same point on level ground 30 m away, the angles of elevation to two roofs are 45° and 30°. Find their height difference to 0.1 m. Both roofs are 30 m away horizontally.", "answer": "12.7 m", "solution": "Difference = 30(tan 45° − tan 30°) ≈ 12.7.", "topic": "trg"}, {"id": "VM-Y10-TRG-019", "skill": "Diagram interpretation", "difficulty": "medium", "question": "Draw a north arrow at A and a ray AB on bearing 120°. Label the acute angle between AB and east.", "answer": "30°", "solution": "East is 090°; the ray is 30° south of east.", "topic": "trg"}, {"id": "VM-Y10-TRG-020", "skill": "Safety constraint", "difficulty": "hard", "question": "A ramp must rise 0.6 m at no more than 5° to the horizontal. Find the minimum horizontal run to 0.01 m, rounding upwards.", "answer": "6.86 m", "solution": "Run ≥ 0.6 ÷ tan 5° ≈ 6.858 m; round upwards.", "topic": "trg"}, {"id": "VM-Y10-TRG-021", "skill": "Unknown angle", "difficulty": "hard", "question": "A kite is 18 m vertically above its anchor and the taut string is 30 m long. Find its elevation angle to the nearest degree.", "answer": "37°", "solution": "sin θ = 18/30; θ ≈ 36.87°.", "topic": "trg"}, {"id": "VM-Y10-TRG-022", "skill": "Reasoning", "difficulty": "hard", "question": "Can an angle of depression of 0° describe a target below the observer?", "answer": "No", "solution": "A zero angle is horizontal, so a target strictly below requires a positive depression angle.", "topic": "trg"}, {"id": "VM-Y10-TRG-023", "skill": "Bearing notation", "difficulty": "easy", "question": "Express south 25° east as a true bearing.", "answer": "155°", "solution": "Measure clockwise from north: 180° − 25°.", "topic": "trg"}, {"id": "VM-Y10-TRG-024", "skill": "Angle identification", "difficulty": "easy", "question": "A person on a balcony looks down at a car. Is the angle from their horizontal line of sight an elevation or depression?", "answer": "Depression", "solution": "The sightline is below the horizontal.", "topic": "trg"}, {"id": "VM-Y10-TRG-025", "skill": "Horizontal distance", "difficulty": "medium", "question": "A drone is 60 m above level ground. Its angle of depression to a marker is 45°. Find the horizontal distance.", "answer": "60 m", "solution": "tan 45° = 60/d = 1.", "topic": "trg"}, {"id": "VM-Y10-TRG-026", "skill": "Bearing interpretation", "difficulty": "medium", "question": "A boat travels 10 km on bearing 090°, then 24 km on bearing 180°. Find its distance from the start.", "answer": "26 km", "solution": "The legs are perpendicular; √(100 + 576) = 26.", "topic": "trg"}, {"id": "VM-Y10-TRG-027", "skill": "Height reasoning", "difficulty": "hard", "question": "Two observers stand on the same side of a tower on level ground. One measures 30° elevation and the other 60°. Who is closer, assuming equal eye heights?", "answer": "The 60° observer", "solution": "For fixed vertical rise, horizontal distance = rise ÷ tan(angle).", "topic": "trg"}, {"id": "VM-Y10-TRG-028", "skill": "Insufficient information", "difficulty": "challenge", "question": "A lookout records a 20° angle of depression to a ship. Can its horizontal distance be determined from this angle alone?", "answer": "No", "solution": "The vertical separation or another length is needed.", "topic": "trg"}, {"id": "VM-Y10-TRG-029", "skill": "Bearing convention", "difficulty": "easy", "question": "A cyclist travels due west. Write the three-digit true bearing.", "answer": "270°", "solution": "True bearings are measured clockwise from north.", "topic": "trg"}, {"id": "VM-Y10-TRG-030", "skill": "Angle interpretation", "difficulty": "easy", "question": "A person looks horizontally and then raises their gaze by 18°. What is the angle of elevation?", "answer": "18°", "solution": "Elevation is measured upwards from the horizontal.", "topic": "trg"}, {"id": "VM-Y10-TRG-031", "skill": "Height difference", "difficulty": "challenge", "question": "Two observation platforms are vertically aligned, 12 m apart. Their angles of depression to the same ground marker are 45° and 30°. Find the horizontal distance to the marker, to one decimal place.", "answer": "28.4 m", "solution": "Let distance be d. Then d(tan 45° − tan 30°) = 12, so d ≈ 28.4.", "topic": "trg"}, {"id": "VM-Y10-TRG-032", "skill": "Bearing reversal", "difficulty": "challenge", "question": "A boat travels from A to B on a bearing of 035°. A second boat travels from B to A. Explain why its bearing is not 325°.", "answer": "215°: reverse direction by adding 180°, rather than reflecting across north.", "solution": "Reverse direction requires adding 180°, not reflecting across north.", "topic": "trg"}, {"id": "VM-Y10-TRG-033", "skill": "Diagram labelling", "difficulty": "easy", "question": "Sketch a vertical pole and a horizontal ground line. A cable runs from the pole top to a ground peg. Relative to the angle at the peg, which side is opposite?", "answer": "The vertical pole", "solution": "The opposite side does not touch the angle at the peg.", "topic": "trg"}, {"id": "VM-Y10-TRG-034", "skill": "Bearing sketch", "difficulty": "medium", "question": "A boat travels 10 km on a true bearing of 060°. Find its eastward and northward displacements to two decimal places.", "answer": "8.66 km east, 5.00 km north", "solution": "East = 10 sin 60°; north = 10 cos 60°.", "topic": "trg"}, {"id": "VM-Y10-TRG-035", "skill": "Observation points", "difficulty": "hard", "question": "Two observers stand on the same straight level path on opposite sides of a tower, 60 m apart. Both see its top at 45°. Find the tower height, ignoring eye height.", "answer": "30 m", "solution": "Each horizontal distance equals the height because tan 45° = 1. Their sum is 60 m.", "topic": "trg"}, {"id": "VM-Y10-TRG-036", "skill": "Clearance", "difficulty": "challenge", "question": "A straight cable rises from ground level at 30° to the horizontal. A 4 m tall obstacle is 6 m horizontally from the start. Does the cable clear it?", "answer": "No", "solution": "Cable height there is 6 tan 30° ≈ 3.46 m, below 4 m.", "topic": "trg"}, {"id": "VM-Y10-TRG-037", "skill": "Survey decision", "difficulty": "hard", "question": "A surveyor stands 24 m from a vertical wall. The angle to its top is 35° and the instrument is 1.6 m above level ground. Is the wall taller than 18 m?", "answer": "Yes, about 18.4 m", "solution": "Height = 24 tan 35° + 1.6 ≈ 18.405 m.", "topic": "trg"}, {"id": "VM-Y10-TRG-038", "skill": "Cable allowance", "difficulty": "medium", "question": "A cable runs from the top of a 9 m pole to a ground anchor, making 60° with horizontal ground. Is 11 m of cable sufficient if 0.8 m extra is needed for fittings?", "answer": "No", "solution": "Sloping length = 9 ÷ sin 60° ≈ 10.39 m. Total ≈ 11.19 m.", "topic": "trg"}, {"id": "VM-Y10-TRG-039", "skill": "Navigation recovery", "difficulty": "hard", "question": "A rescue boat is 9 km north and 12 km west of its base. Find the distance and true bearing of the base from the boat, to the nearest degree.", "answer": "15 km, 127°", "solution": "Distance = √(9² + 12²) = 15. The return direction is southeast; bearing = 180° − tan⁻¹(12/9) ≈ 127°.", "topic": "trg"}, {"id": "VM-Y10-TRG-040", "skill": "Observation comparison", "difficulty": "challenge", "question": "Two observers stand on opposite sides of a tower on level ground, 60 m apart. Their elevation angles are 45° and 30°. Find the tower height, ignoring eye height. The observers and tower base lie on one straight line.", "answer": "Approximately 22.0 m", "solution": "Let height be h. Distances are h/tan 45° and h/tan 30°. Thus h(1 + √3) = 60, giving h ≈ 21.96.", "topic": "trg"}, {"id": "VM-Y10-TRG-041", "skill": "Bearing direction", "difficulty": "easy", "question": "A compass shows 000°. What direction is opposite this bearing? Give a true bearing.", "answer": "180°", "solution": "The opposite direction is half a revolution from north.", "topic": "trg"}, {"id": "VM-Y10-TRG-042", "skill": "Angle complement", "difficulty": "easy", "question": "A sight line makes an angle of 32° above horizontal. What angle does it make with the upward vertical?", "answer": "58°", "solution": "Horizontal and vertical are perpendicular; 90° − 32° = 58°.", "topic": "trg"}, {"id": "VM-Y10-TRG-043", "skill": "Instrument placement", "difficulty": "medium", "question": "A surveyor stands 18 m from a wall. The instrument is 1.4 m above level ground and sights the top at 45°. Find the wall height. The wall is vertical and the distance is horizontal.", "answer": "19.4 m", "solution": "The rise above the instrument is 18 tan 45° = 18 m. Add 1.4 m.", "topic": "trg"}, {"id": "VM-Y10-TRG-044", "skill": "Bearing sector", "difficulty": "medium", "question": "A ship turns anticlockwise through 75° from bearing 040°. Find its new bearing.", "answer": "325°", "solution": "40 − 75 = −35; add 360 to obtain 325°.", "topic": "trg"}, {"id": "VM-Y10-TRG-045", "skill": "Angle interpretation", "difficulty": "easy", "question": "An angle of depression is 27°. What angle does the sightline make with a downward vertical line?", "answer": "63°", "solution": "Horizontal and vertical are perpendicular, so 90 − 27 = 63°.", "topic": "trg"}, {"id": "VM-Y10-TRG-046", "skill": "Bearing reversal", "difficulty": "medium", "question": "A boat travels from A to B on a bearing of 072°. Find the bearing from B to A.", "answer": "252°", "solution": "Add 180° to reverse the direction.", "topic": "trg"}, {"id": "VM-Y10-TRG-047", "skill": "Surveying", "difficulty": "hard", "question": "Two markers are 30 m apart on level ground on the same side of a tower. Their angles of elevation are 45° and approximately 26.565°. Find the tower height to the nearest metre. The markers and tower base lie on one straight line.", "answer": "30 m", "solution": "Let the nearer distance be d. Height = d tan 45° = d; also approximately (d+30) × 0.5. Hence d ≈ 30.", "topic": "trg"}, {"id": "VM-Y10-TRG-048", "skill": "Measurement sensitivity", "difficulty": "challenge", "question": "A tree is 20 m horizontally from an observer whose eye height is 1.5 m. Compare height estimates using angles of elevation 30° and 31°, to the nearest 0.1 m.", "answer": "13.0 m and 13.5 m", "solution": "Use h = 1.5 + 20 tan θ; the estimates are approximately 13.047 and 13.517 m.", "topic": "trg"}, {"id": "VM-Y10-TRG-049", "skill": "Bearing quadrant", "difficulty": "easy", "question": "A rescue vessel travels on a true bearing of 225°. Which compass direction is this?", "answer": "South-west", "solution": "225° is halfway between south (180°) and west (270°).", "topic": "trg"}, {"id": "VM-Y10-TRG-050", "skill": "Instrument correction", "difficulty": "medium", "question": "A clinometer reads 35° but has a known positive error of 2°. A wall is 10 m away horizontally. Find the height above the instrument to one decimal place.", "answer": "6.5 m", "solution": "Correct angle = 33°. Height = 10 tan(33°) ≈ 6.49 m.", "topic": "trg"}, {"id": "VM-Y10-TRG-051", "skill": "Equal slopes", "difficulty": "hard", "question": "Two straight ramps rise at the same angle. Ramp A has twice the horizontal run of ramp B. Compare their vertical rises.", "answer": "A rises twice as far", "solution": "Rise = run × tan(angle). The tangent is constant, so doubling run doubles rise.", "topic": "trg"}, {"id": "VM-Y10-TRG-052", "skill": "Navigation constraint", "difficulty": "challenge", "question": "A walker must travel 6 km due east overall using a single straight path on bearing 060°, followed by a due-south leg. Find both leg lengths to two decimal places.", "answer": "6.93 km then 3.46 km", "solution": "First leg L satisfies L sin(60°) = 6. Its north component is L cos(60°), which the south leg cancels.", "topic": "trg"}, {"id": "VM-Y10-TRG-053", "skill": "Bearing from west", "difficulty": "easy", "question": "A walker heads 20° north of west. Write the true bearing.", "answer": "290°", "solution": "West is 270°. Turning towards north adds 20°.", "topic": "trg"}, {"id": "VM-Y10-TRG-054", "skill": "Slope distance", "difficulty": "medium", "question": "A straight hillside path is 80 m long and inclined at 15° to the horizontal. Find its vertical rise to the nearest metre.", "answer": "21 m", "solution": "Rise = 80 sin 15° ≈ 20.71 m.", "topic": "trg"}, {"id": "VM-Y10-TRG-055", "skill": "Opposite observers", "difficulty": "hard", "question": "Two observers on level ground are 90 m apart with a vertical tower between them. Their angles of elevation are 45° and 45°. Find the tower height, ignoring eye height. The observers and tower base lie on one straight line.", "answer": "45 m", "solution": "Both horizontal distances equal the height since tan 45°=1. Their sum is 90 m.", "topic": "trg"}, {"id": "VM-Y10-TRG-056", "skill": "Bearing cancellation", "difficulty": "challenge", "question": "A boat travels 10 km on bearing 030° then 10 km on bearing 150°. Find its displacement from the start.", "answer": "10 km east, bearing 090°.", "solution": "North components 10 cos 30° and 10 cos 150° cancel. East components are both 5 km.", "topic": "trg"}, {"id": "VM-Y10-TRG-057", "skill": "Bearing reference", "difficulty": "easy", "question": "A boat travels due south. What three-digit bearing describes its direction?", "answer": "180°", "solution": "Bearings are measured clockwise from north; south is a half-turn.", "topic": "trg"}, {"id": "VM-Y10-TRG-058", "skill": "Slope interpretation", "difficulty": "medium", "question": "A path rises 1 m for every 4 m of horizontal travel. Find its angle to the horizontal to the nearest degree.", "answer": "14°", "solution": "tan θ = 1/4; θ = arctan(0.25) ≈ 14.04°.", "topic": "trg"}, {"id": "VM-Y10-TRG-059", "skill": "Bearing and displacement", "difficulty": "hard", "question": "A walker travels 10 km on bearing 060°. Find the eastward displacement to two decimal places.", "answer": "8.66 km", "solution": "The angle from north is 60°, so eastward displacement = 10 sin 60°.", "topic": "trg"}, {"id": "VM-Y10-TRG-060", "skill": "Survey feasibility", "difficulty": "challenge", "question": "A vertical mast stands on level ground. From a point 12 m away its top is seen at 45° elevation. A second observer at ground level claims a 60° elevation from 15 m away. Can both observations be correct? Both observations are at ground level and distances are horizontal.", "answer": "No", "solution": "First observation gives height 12 tan 45° = 12 m. Second gives 15 tan 60° ≈ 25.98 m; heights disagree.", "topic": "trg"}, {"id": "VM-Y10-TRG-061", "skill": "Bearing conversion", "difficulty": "easy", "question": "A compass direction is N 15° W. Write its true bearing.", "answer": "345°", "solution": "Measure clockwise from north: 360 − 15 = 345°.", "topic": "trg"}, {"id": "VM-Y10-TRG-062", "skill": "Sightline", "difficulty": "medium", "question": "A camera is 1.8 m above level ground. It looks down at a marker 6 m horizontally away. Find the angle of depression to the nearest degree.", "answer": "17°", "solution": "tan θ = 1.8 ÷ 6 = 0.3; inverse tangent gives 16.7°.", "topic": "trg"}, {"id": "VM-Y10-TRG-063", "skill": "Survey obstruction", "difficulty": "hard", "question": "A surveyor stands 30 m from a vertical wall and measures an elevation angle of 40° to its top. A fence halfway to the wall is 10 m high. The instrument is 1.5 m above level ground. Does the sightline clear the fence?", "answer": "Yes, by about 4.1 m", "solution": "At 15 m the sightline height is 1.5 + 15 tan 40° ≈ 14.09 m. Subtract 10 m.", "topic": "trg"}, {"id": "VM-Y10-TRG-064", "skill": "Navigation consistency", "difficulty": "challenge", "question": "A walker travels 5 km on bearing 090°, then 5 km on bearing 330°. Can the walker be due north of the start? Explain.", "answer": "No", "solution": "The second leg has westward component 5 sin 30° = 2.5 km. The net eastward displacement is 2.5 km, not zero.", "topic": "trg"}, {"id": "VM-Y10-TRG-065", "skill": "Bearing cardinal reference", "difficulty": "easy", "question": "A vessel travels on a bearing of 270°. Which cardinal direction is it travelling?", "answer": "West.", "solution": "True bearings are measured clockwise from north; west is 270°.", "topic": "trg"}, {"id": "VM-Y10-TRG-066", "skill": "Sightline length", "difficulty": "medium", "question": "A drone is 40 m vertically above level ground. Its angle of elevation from an observer at ground level is 30°. Find the straight-line distance to the drone.", "answer": "80 m", "solution": "sin 30° = 40/d, so d = 40/0.5 = 80.", "topic": "trg"}, {"id": "VM-Y10-TRG-067", "skill": "Bearing components", "difficulty": "hard", "question": "A walker travels 200 m on a bearing of 150°. Find the eastward and southward displacements to the nearest metre.", "answer": "100 m east; 173 m south.", "solution": "The direction is 30° east of south. East = 200 sin 30°; south = 200 cos 30°.", "topic": "trg"}, {"id": "VM-Y10-TRG-068", "skill": "Observation separation", "difficulty": "challenge", "question": "Two observers on level ground are due east of a tower, 30 m apart. The nearer observer sees the top at 45° and the farther at 30°. Find the tower height to one decimal place, ignoring eye height. Assume the tower is vertical.", "answer": "41.0 m", "solution": "Let height and nearer distance be h since tan 45° = 1. Then tan 30° = h/(h+30), giving h = 30/(√3−1) ≈ 41.0.", "topic": "trg"}, {"id": "VM-Y10-TRG-069", "skill": "Bearing reversal", "difficulty": "easy", "question": "A walker travels due west from a campsite. Give the true bearing back to the campsite.", "answer": "090°", "solution": "The return direction is due east.", "topic": "trg"}, {"id": "VM-Y10-TRG-070", "skill": "Horizontal distance", "difficulty": "medium", "question": "A kite string is 30 m long and makes an angle of 40° with level ground. Assuming a straight taut string, find its horizontal projection to one decimal place.", "answer": "23.0 m", "solution": "Horizontal projection = 30 cos 40° ≈ 23.0.", "topic": "trg"}, {"id": "VM-Y10-TRG-071", "skill": "Eye height correction", "difficulty": "hard", "question": "A surveyor 1.6 m tall stands 20 m from a vertical pole. The angle of elevation from eye level is 35°. Find the pole height to one decimal place.", "answer": "15.6 m", "solution": "Height = 1.6 + 20 tan 35° ≈ 15.6.", "topic": "trg"}, {"id": "VM-Y10-TRG-072", "skill": "Bearing feasibility", "difficulty": "challenge", "question": "A boat travels 8 km on bearing 060°, then 8 km on bearing 300°. Is its final position due north of its start? Find the displacement.", "answer": "Yes; 8 km north", "solution": "East and west components cancel. North components each equal 8 cos 60° = 4 km.", "topic": "trg"}, {"id": "VM-Y10-TRG-073", "skill": "Angle identification", "difficulty": "easy", "question": "A person on a balcony looks down at a parked car. Is the angle measured down from the horizontal an elevation or depression angle?", "answer": "Depression", "solution": "The line of sight is below the horizontal.", "topic": "trg"}, {"id": "VM-Y10-TRG-074", "skill": "Bearing interpretation", "difficulty": "medium", "question": "A boat travels on bearing 135°. State its compass direction and the angle east of south.", "answer": "South-east; 45°", "solution": "135° is halfway between east (090°) and south (180°).", "topic": "trg"}, {"id": "VM-Y10-TRG-075", "skill": "Slope ratio", "difficulty": "medium", "question": "A ramp has an inclination of 8° and a horizontal run of 5 m. Find its rise to two decimal places.", "answer": "0.70 m", "solution": "Rise = 5 tan 8° ≈ 0.7027 m.", "topic": "trg"}, {"id": "VM-Y10-TRG-076", "skill": "Height difference", "difficulty": "hard", "question": "Two vertical poles stand 18 m apart on level ground. From the top of the shorter pole, the angle of elevation to the taller pole is 28°. If the shorter pole is 4 m high, find the taller height to one decimal place.", "answer": "13.6 m", "solution": "4 + 18 tan 28° ≈ 13.6.", "topic": "trg"}, {"id": "VM-Y10-TRG-077", "skill": "Bearing notation", "difficulty": "easy", "question": "A walker heads 20° west of north. Write the three-digit true bearing.", "answer": "340°", "solution": "Measure clockwise from north: 360° − 20°.", "topic": "trg"}, {"id": "VM-Y10-TRG-078", "skill": "Inclination comparison", "difficulty": "medium", "question": "Ramp A rises 1 m over 8 m horizontally; ramp B rises 2 m over 15 m horizontally. Which is steeper?", "answer": "Ramp B", "solution": "Compare tangents: 1/8 = 0.125 and 2/15 ≈ 0.133.", "topic": "trg"}, {"id": "VM-Y10-TRG-079", "skill": "Horizontal distance", "difficulty": "medium", "question": "A kite is 30 m vertically above level ground. Its angle of elevation from an observer at ground level is 45°. Find the horizontal distance.", "answer": "30 m", "solution": "tan 45° = 1, so opposite and adjacent lengths are equal.", "topic": "trg"}, {"id": "VM-Y10-TRG-080", "skill": "Surveying", "difficulty": "hard", "question": "From a point on level ground 20 m from a wall, the angle of elevation to its top is 45°. An observer moves 15 m directly away. Find the new angle to the nearest degree. Both observations are at ground level; movement is directly away from the wall base.", "answer": "30°", "solution": "The wall is 20 m high. The new angle is arctan(20/35) ≈ 29.74°.", "topic": "trg"}, {"id": "VM-Y10-TRG-081", "skill": "Bearing quadrant", "difficulty": "easy", "question": "Is bearing 225° closer to south or west, or equally close?", "answer": "Equally close", "solution": "225° is halfway between 180° and 270°.", "topic": "trg"}, {"id": "VM-Y10-TRG-082", "skill": "Inclined distance", "difficulty": "medium", "question": "A conveyor is 10 m long and inclined at 30° to the horizontal. How much height does it gain?", "answer": "5 m", "solution": "Vertical rise = 10 sin 30° = 5.", "topic": "trg"}, {"id": "VM-Y10-TRG-083", "skill": "Angle of depression", "difficulty": "medium", "question": "A camera is 8 m above level ground and observes a marker 8 m horizontally away. Find the angle of depression.", "answer": "45°", "solution": "tan θ = 8 ÷ 8 = 1, so θ = 45°.", "topic": "trg"}, {"id": "VM-Y10-TRG-084", "skill": "Two-stage navigation", "difficulty": "hard", "question": "A hiker must return directly to camp, which is 5 km east and 12 km south of her location. Find the distance and bearing to the nearest degree.", "answer": "13 km, 157°", "solution": "Distance = √(25 + 144) = 13; bearing = 180° − tan⁻¹(5/12) ≈ 157°.", "topic": "trg"}, {"skill": "Bearing interpretation", "difficulty": "easy", "question": "Which cardinal direction is 90° clockwise from a bearing of 270°?", "answer": "North", "solution": "270 + 90 = 360°, equivalent to 000°.", "id": "VM-Y10-TRG-085", "topic": "trg"}, {"skill": "Elevation measurement", "difficulty": "medium", "question": "A camera is mounted 1.2 m above level ground, 16 m from a wall. Its angle of elevation to the roof is 45°. Find the roof height.", "answer": "17.2 m", "solution": "Rise = 16 tan 45° = 16; add 1.2.", "id": "VM-Y10-TRG-086", "topic": "trg"}, {"skill": "Bearing components", "difficulty": "medium", "question": "A boat travels 20 km on a bearing of 120°. Find its southward displacement.", "answer": "10 km", "solution": "The direction is 60° east of south, so southward displacement = 20 cos 60° = 10.", "id": "VM-Y10-TRG-087", "topic": "trg"}, {"skill": "Two observations", "difficulty": "hard", "question": "Two observers stand on opposite sides of a vertical mast on level ground, 30 m apart. Their elevation angles to the top are 45° and 60°. Find the mast height, ignoring eye height. The observers and mast base lie on one straight line.", "answer": "Approximately 19.02 m", "solution": "If height is h, horizontal distances are h and h ÷ tan 60°. Their sum is 30, so h = 30 ÷ (1 + 1/√3) ≈ 19.02.", "id": "VM-Y10-TRG-088", "topic": "trg"}, {"id": "VM-Y10-TRG-089", "skill": "Depression interpretation", "difficulty": "easy", "question": "A lookout measures an angle of depression of 18° to a boat. What is the angle between the boat’s horizontal line and its line of sight to the lookout?", "answer": "18°", "solution": "The horizontal lines are parallel, giving equal alternate angles.", "topic": "trg"}, {"id": "VM-Y10-TRG-090", "skill": "Bearing reversal", "difficulty": "medium", "question": "A walker travels from P to Q on bearing 347°. Give the bearing of P from Q.", "answer": "167°", "solution": "Subtract 180° from 347°.", "topic": "trg"}, {"id": "VM-Y10-TRG-091", "skill": "Slope comparison", "difficulty": "medium", "question": "Two paths rise 3 m. Their horizontal runs are 8 m and 12 m. Which has the greater angle of elevation?", "answer": "The 8 m path", "solution": "The tangent ratios are 3/8 and 3/12; the larger ratio gives the larger acute angle.", "topic": "trg"}, {"id": "VM-Y10-TRG-092", "skill": "Survey baseline", "difficulty": "hard", "question": "A surveyor stands 20 m west of a pole and measures its elevation as 30°. A second surveyor stands 20 m north of the first. Find the second elevation angle to the nearest degree, ignoring eye height.", "answer": "22°", "solution": "Height = 20 tan 30°. Second horizontal distance = √800. Angle = arctan(20 tan 30° ÷ √800) ≈ 22.2°.", "topic": "trg"}, {"id": "VM-Y10-TRG-093", "skill": "Ratio identification", "difficulty": "easy", "question": "In a right triangle, the side opposite angle θ is 7 cm and the hypotenuse is 25 cm. State sin θ.", "answer": "7/25", "solution": "Sine is opposite divided by hypotenuse.", "topic": "trg"}, {"id": "VM-Y10-TRG-094", "skill": "Complementary angles", "difficulty": "medium", "question": "A right triangle has an acute angle of 38°. Express cos 38° as the sine of another acute angle.", "answer": "sin 52°", "solution": "The acute angles sum to 90°, and complementary sine and cosine are equal.", "topic": "trg"}, {"id": "VM-Y10-TRG-095", "skill": "Bearing interpretation", "difficulty": "medium", "question": "A boat travels on bearing 240°. What acute angle does its course make with due west?", "answer": "30°", "solution": "West is bearing 270°; difference is 30°.", "topic": "trg"}, {"id": "VM-Y10-TRG-096", "skill": "Slope comparison", "difficulty": "medium", "question": "Ramp A rises 0.8 m over a horizontal 5 m. Ramp B rises 1.2 m over a horizontal 8 m. Which is steeper?", "answer": "Ramp A", "solution": "Compare tangent ratios: 0.16 > 0.15.", "topic": "trg"}, {"id": "VM-Y10-TRG-097", "skill": "Elevation constraint", "difficulty": "hard", "question": "A camera is 1.5 m above level ground and 12 m horizontally from a vertical wall. Its upward viewing angle is 35°. Find the height of the point viewed, to 2 decimal places.", "answer": "9.90 m", "solution": "1.5 + 12 tan 35° ≈ 9.9025.", "topic": "trg"}, {"id": "VM-Y10-TRG-098", "skill": "Two legs bearing", "difficulty": "hard", "question": "A walker travels 6 km due east then 8 km due south. Find the bearing of the final position from the start, to the nearest degree.", "answer": "143°", "solution": "Angle east of south = arctan(6/8) ≈ 36.87°; bearing = 180° − 36.87°.", "topic": "trg"}, {"id": "VM-Y10-TRG-099", "skill": "Bearing reversal", "difficulty": "easy", "question": "A boat travels on bearing 125°. What bearing takes it directly back?", "answer": "305°", "solution": "Add 180°.", "topic": "trg"}, {"id": "VM-Y10-TRG-100", "skill": "Ratio selection", "difficulty": "easy", "question": "Which trigonometric ratio relates the adjacent side and hypotenuse?", "answer": "Cosine", "solution": "cos θ = adjacent ÷ hypotenuse.", "topic": "trg"}, {"id": "VM-Y10-TRG-101", "skill": "Angle of depression", "difficulty": "medium", "question": "A lookout is 24 m above level ground. A marker is 32 m horizontally away. Find the angle of depression to the nearest degree.", "answer": "37°", "solution": "tan θ = 24/32; θ ≈ 36.87°.", "topic": "trg"}, {"id": "VM-Y10-TRG-102", "skill": "Inclined distance", "difficulty": "medium", "question": "A 15 m cable makes a 30° angle with horizontal ground. Find its vertical rise.", "answer": "7.5 m", "solution": "15 sin 30° = 7.5.", "topic": "trg"}, {"id": "VM-Y10-TRG-103", "skill": "Two slopes", "difficulty": "hard", "question": "A path rises 12 m over 40 m horizontally, then falls 5 m over 20 m horizontally. Find the angle of the straight line joining its endpoints to the horizontal, nearest degree. Both horizontal legs continue in the same direction.", "answer": "7°", "solution": "Net rise 7 m, run 60 m; arctan(7/60) ≈ 6.65°.", "topic": "trg"}, {"id": "VM-Y10-TRG-104", "skill": "Bearing components", "difficulty": "hard", "question": "A walker travels 10 km on bearing 060°, then 5 km due south. How far east of the start is the walker, to two decimals?", "answer": "8.66 km", "solution": "East displacement is 10 sin 60°; the south leg adds none.", "topic": "trg"}, {"id": "VM-Y10-TRG-105", "skill": "Ratio selection", "difficulty": "easy", "question": "In a right triangle, sin θ = 3/5. Which side is represented by the 5 in this ratio?", "answer": "Hypotenuse", "solution": "Sine is opposite divided by hypotenuse.", "topic": "trg"}, {"id": "VM-Y10-TRG-106", "skill": "Bearing reversal", "difficulty": "easy", "question": "A boat travels on bearing 215°. State the bearing of its return along the same path.", "answer": "035°", "solution": "Subtract 180°.", "topic": "trg"}, {"id": "VM-Y10-TRG-107", "skill": "Angle comparison", "difficulty": "medium", "question": "Two right triangles have opposite-to-adjacent ratios 0.6 and 0.9. Which has the larger acute angle?", "answer": "The second", "solution": "Tangent increases with acute angle.", "topic": "trg"}, {"id": "VM-Y10-TRG-108", "skill": "Depression", "difficulty": "medium", "question": "From a platform 18 m above level ground, the angle of depression to a marker is 45°. Find its horizontal distance.", "answer": "18 m", "solution": "tan 45° = 18/d = 1.", "topic": "trg"}, {"id": "VM-Y10-TRG-109", "skill": "Surveying", "difficulty": "hard", "question": "Two observers stand on opposite sides of a vertical pole on level ground. Their distances from its base are 12 m and 16 m. The first measures an elevation of 45°. Find the second elevation to the nearest degree. Both angles are measured at ground level.", "answer": "37°", "solution": "Height = 12 tan 45° = 12; arctan(12/16) ≈ 36.87°.", "topic": "trg"}, {"id": "VM-Y10-TRG-110", "skill": "Slope constraint", "difficulty": "hard", "question": "A ramp must rise 0.9 m with an inclination no greater than 6°. Find the minimum horizontal run to two decimal places, rounding up to ensure compliance.", "answer": "8.57 m", "solution": "Run ≥ 0.9/tan 6° ≈ 8.5629 m.", "topic": "trg"}, {"id": "VM-Y10-TRG-111", "skill": "Bearing reversal", "difficulty": "easy", "question": "A boat travels on bearing 065°. What is the reverse bearing?", "answer": "245°", "solution": "Add 180°.", "topic": "trg"}, {"id": "VM-Y10-TRG-112", "skill": "Ratio selection", "difficulty": "easy", "question": "Which ratio can be calculated from the adjacent side and hypotenuse without finding the opposite side?", "answer": "Cosine", "solution": "Cosine = adjacent/hypotenuse.", "topic": "trg"}, {"id": "VM-Y10-TRG-113", "skill": "Angle of depression", "difficulty": "medium", "question": "From a platform 18 m high, the angle of depression to a marker on level ground is 30°. Find horizontal distance to the nearest tenth.", "answer": "31.2 m", "solution": "Distance = 18 ÷ tan 30° ≈ 31.2.", "topic": "trg"}, {"id": "VM-Y10-TRG-114", "skill": "Slope angle", "difficulty": "medium", "question": "A path rises 7 m over a horizontal distance of 40 m. Find its inclination to the nearest degree.", "answer": "10°", "solution": "θ = arctan(7/40) ≈ 9.93°.", "topic": "trg"}, {"id": "VM-Y10-TRG-115", "skill": "Two elevations", "difficulty": "hard", "question": "Two observers stand 20 m and 35 m from the base of a vertical tower on level ground. The nearer observer measures an elevation of 45°. Find the farther observer's elevation to the nearest degree. Both angles are measured at ground level.", "answer": "30°", "solution": "Height = 20 tan 45° = 20; arctan(20/35) ≈ 29.7°.", "topic": "trg"}, {"id": "VM-Y10-TRG-116", "skill": "Bearing components", "difficulty": "hard", "question": "A walker travels 50 m on bearing 120°. Find the eastward and southward displacements to the nearest tenth.", "answer": "43.3 m east, 25.0 m south", "solution": "East = 50 sin 120°; south = −50 cos 120°.", "topic": "trg"}, {"id": "VM-Y10-TRG-117", "skill": "Bearing conversion", "difficulty": "easy", "question": "A boat travels 35° south of east. Give its three-digit bearing.", "answer": "125°", "solution": "East is 090°; add 35°.", "topic": "trg"}, {"id": "VM-Y10-TRG-118", "skill": "Angle of depression", "difficulty": "medium", "question": "A drone is 30 m above level ground. Its angle of depression to a marker is 45°. Find the horizontal distance.", "answer": "30 m", "solution": "tan 45° = 30/d = 1, so d = 30.", "topic": "trg"}, {"id": "VM-Y10-TRG-119", "skill": "Right triangle ratio", "difficulty": "medium", "question": "A right triangle has hypotenuse 26 cm and side adjacent to angle θ of 10 cm. Find cos θ as a simplified fraction.", "answer": "5/13", "solution": "cos θ = 10/26 = 5/13.", "topic": "trg"}, {"id": "VM-Y10-TRG-120", "skill": "Two observation points", "difficulty": "hard", "question": "A vertical pole is viewed from two points on the same straight level path through the base, on one side of the pole, with angles measured from ground level. The angles of elevation are 45° and 30°. The points are 12 m apart. Find the pole height to one decimal place.", "answer": "16.4 m", "solution": "Let height h equal the nearer distance. Then tan 30° = h/(h + 12), so h = 12/(√3 − 1) ≈ 16.4.", "topic": "trg"}, {"id": "VM-Y10-VOL-001", "skill": "Composite prism", "difficulty": "medium", "question": "A 5 m long prism has an L-shaped cross-section formed from a 4 m by 3 m rectangle minus a 2 m by 1 m rectangle. Find volume.", "answer": "50 m³", "solution": "Cross-section = 12 − 2 = 10; multiply by 5.", "topic": "vol"}, {"id": "VM-Y10-VOL-002", "skill": "Semicircle", "difficulty": "medium", "question": "A semicircular tunnel has radius 3 m and length 20 m. Find its volume exactly.", "answer": "90π m³", "solution": "Half-circle area = 9π/2; multiply by 20.", "topic": "vol"}, {"id": "VM-Y10-VOL-003", "skill": "Sector", "difficulty": "medium", "question": "A prism has a 60° sector cross-section of radius 6 cm and length 10 cm. Find volume exactly.", "answer": "60π cm³", "solution": "Sector area = (60/360)π×36 = 6π.", "topic": "vol"}, {"id": "VM-Y10-VOL-004", "skill": "Composite solid", "difficulty": "hard", "question": "A cylinder of radius 2 cm and height 5 cm sits on a 6 cm cube without overlap. Find total volume exactly.", "answer": "216 + 20π cm³", "solution": "Add cube volume 216 and cylinder volume π×4×5.", "topic": "vol"}, {"id": "VM-Y10-VOL-005", "skill": "Capacity", "difficulty": "easy", "question": "A tank holds 0.75 m³ of water. Express this in litres.", "answer": "750 L", "solution": "1 m³ = 1000 L.", "topic": "vol"}, {"id": "VM-Y10-VOL-006", "skill": "Reverse volume", "difficulty": "hard", "question": "A uniform prism has volume 360 cm³ and length 15 cm. Its trapezoidal cross-section has parallel sides 4 cm and 8 cm. Find its perpendicular height.", "answer": "4 cm", "solution": "Area = 360/15 = 24; 24 = (4+8)h/2.", "topic": "vol"}, {"id": "VM-Y10-VOL-007", "skill": "Units", "difficulty": "easy", "question": "Convert 2500 cm³ to litres.", "answer": "2.5 L", "solution": "1000 cm³ = 1 L.", "topic": "vol"}, {"id": "VM-Y10-VOL-008", "skill": "Displacement", "difficulty": "medium", "question": "Water in a measuring cylinder rises from 120 mL to 175 mL when a stone is submerged. Find stone volume. The stone is fully submerged and no water overflows.", "answer": "55 cm³", "solution": "175 − 120 = 55 mL = 55 cm³.", "topic": "vol"}, {"id": "VM-Y10-VOL-009", "skill": "Hollow cylinder", "difficulty": "hard", "question": "A pipe is 30 cm long with outer radius 5 cm and inner radius 4 cm. Find the volume of its material exactly. The inner and outer cylinders are concentric.", "answer": "270π cm³", "solution": "π(25 − 16)×30.", "topic": "vol"}, {"id": "VM-Y10-VOL-010", "skill": "Partial filling", "difficulty": "medium", "question": "A rectangular tank has base 80 cm by 50 cm. How high does 60 L of water rise?", "answer": "15 cm", "solution": "60000 ÷ 4000 = 15.", "topic": "vol"}, {"id": "VM-Y10-VOL-011", "skill": "Scaling", "difficulty": "medium", "question": "A solid is enlarged by scale factor 2.5. Find its volume scale factor.", "answer": "15.625", "solution": "2.5³ = 15.625.", "topic": "vol"}, {"id": "VM-Y10-VOL-012", "skill": "Comparison", "difficulty": "hard", "question": "Two cylinders have equal height. One has twice the radius of the other. Compare their volumes.", "answer": "The larger has four times the volume.", "solution": "Volume is proportional to radius squared for fixed height.", "topic": "vol"}, {"id": "VM-Y10-VOL-013", "skill": "Error analysis", "difficulty": "medium", "question": "A student calculates cylinder volume using πdh, where d is diameter. Explain the error.", "answer": "This is curved surface area, not volume.", "solution": "Volume is π(d/2)²h.", "topic": "vol"}, {"id": "VM-Y10-VOL-014", "skill": "Reverse cylinder", "difficulty": "medium", "question": "A cylinder has volume 100π cm³ and height 4 cm. Find radius.", "answer": "5 cm", "solution": "r² = 100/4 = 25.", "topic": "vol"}, {"id": "VM-Y10-VOL-015", "skill": "Composite removal", "difficulty": "hard", "question": "A 10 cm cube has a cylindrical hole of radius 2 cm drilled straight through its full height. Find remaining volume exactly. The hole is perpendicular to the top and bottom faces and lies entirely within the cube cross-section.", "answer": "1000 − 40π cm³", "solution": "Subtract π×2²×10 from 10³.", "topic": "vol"}, {"id": "VM-Y10-VOL-016", "skill": "Rate", "difficulty": "medium", "question": "A 240 L tank is one quarter full. Water enters at 12 L/min. How long until full?", "answer": "15 minutes", "solution": "Remaining volume = 180 L; 180 ÷ 12 = 15.", "topic": "vol"}, {"id": "VM-Y10-VOL-017", "skill": "Design comparison", "difficulty": "hard", "question": "Two tanks have the same 120 L capacity. One has a base area of 0.4 m² and the other 0.6 m². Compare water depths when full. Both tanks have constant horizontal cross-sectional areas.", "answer": "0.3 m and 0.2 m", "solution": "120 L = 0.12 m³; divide by each base area.", "topic": "vol"}, {"id": "VM-Y10-VOL-018", "skill": "Partial filling", "difficulty": "hard", "question": "A horizontal prism has a rectangular cross-section 40 cm wide and 30 cm high and length 1 m. Find water volume when depth is 12 cm.", "answer": "48 L", "solution": "40 × 12 × 100 = 48000 cm³ = 48 L.", "topic": "vol"}, {"id": "VM-Y10-VOL-019", "skill": "Sector reasoning", "difficulty": "hard", "question": "Two equal-length prisms have sector cross-sections of the same radius, with angles 45° and 120°. Find their volume ratio.", "answer": "3:8", "solution": "Volume is proportional to sector angle; simplify 45:120.", "topic": "vol"}, {"id": "VM-Y10-VOL-020", "skill": "Packaging", "difficulty": "hard", "question": "A carton measures 30 by 20 by 12 cm internally. How many 5 cm cubes fit in an axis-aligned grid?", "answer": "48", "solution": "Fit 6 along length, 4 along width and 2 along height; multiply.", "topic": "vol"}, {"id": "VM-Y10-VOL-021", "skill": "Overflow", "difficulty": "hard", "question": "A full tank overflows when a fully submerged waterproof block of dimensions 8 by 5 by 3 cm is inserted. How much water spills?", "answer": "120 mL", "solution": "Displaced volume equals block volume, 120 cm³.", "topic": "vol"}, {"id": "VM-Y10-VOL-022", "skill": "Model critique", "difficulty": "hard", "question": "Two prisms have equal cross-sectional perimeter and length. Must their volumes match?", "answer": "No", "solution": "A 1 by 5 rectangle and 3 by 3 square both have perimeter 12 but areas 5 and 9.", "topic": "vol"}, {"id": "VM-Y10-VOL-023", "skill": "Quadrant prism", "difficulty": "medium", "question": "A prism has a quadrant cross-section of radius 4 cm and length 10 cm. Find its exact volume.", "answer": "40π cm³", "solution": "Cross-section = π × 16 ÷ 4 = 4π; multiply by 10.", "topic": "vol"}, {"id": "VM-Y10-VOL-024", "skill": "Capacity conversion", "difficulty": "easy", "question": "A tank contains 180 L. Express this volume in cubic metres.", "answer": "0.18 m³", "solution": "Divide litres by 1000.", "topic": "vol"}, {"id": "VM-Y10-VOL-025", "skill": "Cross-section comparison", "difficulty": "hard", "question": "Two prisms have the same volume and one has twice the cross-sectional area of the other. Compare their lengths.", "answer": "The larger cross-section prism is half as long", "solution": "V = A × length, so length is inversely proportional to A for fixed V.", "topic": "vol"}, {"id": "VM-Y10-VOL-026", "skill": "Composite cross-section", "difficulty": "medium", "question": "A shed cross-section is a 6 m by 3 m rectangle topped by a triangle of base 6 m and height 2 m. The shed is 5 m long. Find its volume.", "answer": "120 m³", "solution": "Cross-section = 18 + 6 = 24; multiply by 5.", "topic": "vol"}, {"id": "VM-Y10-VOL-027", "skill": "Composite cylinder", "difficulty": "hard", "question": "A solid consists of a 10 cm cube with a cylinder of radius 2 cm and height 5 cm attached externally. Find its exact volume.", "answer": "1000 + 20π cm³", "solution": "Add cube volume and cylinder volume; they do not overlap.", "topic": "vol"}, {"id": "VM-Y10-VOL-028", "skill": "Design reasoning", "difficulty": "challenge", "question": "A manufacturer doubles the length of a prism but keeps its cross-section unchanged. A student says its capacity increases eightfold. Explain.", "answer": "Capacity doubles", "solution": "Only one dimension changes; volume = cross-sectional area × length.", "topic": "vol"}, {"id": "VM-Y10-VOL-029", "skill": "Capacity", "difficulty": "easy", "question": "Which is greater, 1.2 L or 1150 cm³, and by how much in mL?", "answer": "1.2 L by 50 mL", "solution": "1.2 L = 1200 mL and 1150 cm³ = 1150 mL.", "topic": "vol"}, {"id": "VM-Y10-VOL-030", "skill": "Cross-section", "difficulty": "easy", "question": "A prism has constant cross-sectional area 18 cm² and length 5 cm. Find its volume.", "answer": "90 cm³", "solution": "Multiply cross-sectional area by length.", "topic": "vol"}, {"id": "VM-Y10-VOL-031", "skill": "Displacement", "difficulty": "challenge", "question": "A solid is fully submerged in a rectangular tank with base 40 cm by 25 cm. The water rises 1.8 cm without overflowing. Find the solid volume.", "answer": "1800 cm³", "solution": "Displaced volume = 40 × 25 × 1.8.", "topic": "vol"}, {"id": "VM-Y10-VOL-032", "skill": "Equal volumes", "difficulty": "challenge", "question": "Two cylinders have equal volumes. The second has three times the radius of the first. Express its height in terms of the first height h.", "answer": "h/9", "solution": "The base area increases by a factor of 9, so height must be divided by 9.", "topic": "vol"}, {"id": "VM-Y10-VOL-033", "skill": "Cross-section reading", "difficulty": "easy", "question": "A prism has volume 96 cm³ and length 8 cm. Find its constant cross-sectional area.", "answer": "12 cm²", "solution": "Divide volume by length: 96 ÷ 8.", "topic": "vol"}, {"id": "VM-Y10-VOL-034", "skill": "Channel capacity", "difficulty": "medium", "question": "A straight channel has a trapezoidal cross-section with parallel sides 30 cm and 50 cm and perpendicular height 20 cm. It is 2 m long. Find its capacity in litres. The channel has constant cross-section and is filled to the top.", "answer": "160 L", "solution": "Area = (30 + 50) × 20 ÷ 2 = 800 cm². Volume = 800 × 200 = 160000 cm³ = 160 L.", "topic": "vol"}, {"id": "VM-Y10-VOL-035", "skill": "Water level", "difficulty": "hard", "question": "A rectangular tank with base 50 cm by 40 cm contains water 15 cm deep. A fully submerged solid raises the level to 18 cm. Find the solid volume. No water overflows.", "answer": "6000 cm³", "solution": "Displaced volume = 50 × 40 × (18 − 15).", "topic": "vol"}, {"id": "VM-Y10-VOL-036", "skill": "Design constraint", "difficulty": "challenge", "question": "A closed rectangular container must hold 12 L. Its square base has side 20 cm. A shelf allows a maximum height of 25 cm. Can it fit? Ignore wall thickness.", "answer": "No", "solution": "12 L = 12000 cm³. Required height = 12000 ÷ 400 = 30 cm, exceeding 25 cm.", "topic": "vol"}, {"id": "VM-Y10-VOL-037", "skill": "Delivery capacity", "difficulty": "medium", "question": "A rectangular tank has internal dimensions 1.2 m by 0.8 m by 0.5 m. It is filled to 75% capacity. How many litres are inside?", "answer": "360 L", "solution": "Capacity = 0.48 m³ = 480 L; 0.75 × 480 = 360.", "topic": "vol"}, {"id": "VM-Y10-VOL-038", "skill": "Material yield", "difficulty": "hard", "question": "A 20 cm cube of clay is reshaped into cylinders of radius 4 cm and height 10 cm. How many complete cylinders can be made without waste between mouldings?", "answer": "15", "solution": "Clay volume = 8000 cm³. Each cylinder uses 160π cm³. 8000/(160π) ≈ 15.92; round down.", "topic": "vol"}, {"id": "VM-Y10-VOL-039", "skill": "Drainage decision", "difficulty": "hard", "question": "A cylindrical tank of radius 1 m loses 300 L each hour. How far does its water level fall in two hours? The cylinder is upright and contains sufficient water.", "answer": "About 19.1 cm", "solution": "Lost volume = 0.6 m³. Height change = 0.6/π m ≈ 0.191 m.", "topic": "vol"}, {"id": "VM-Y10-VOL-040", "skill": "Cross-section design", "difficulty": "challenge", "question": "A 5 m long prism has a trapezoidal cross-section with parallel sides 0.6 m and 1.4 m. What perpendicular cross-section height gives capacity 4000 L?", "answer": "0.8 m", "solution": "4000 L = 4 m³; cross-sectional area = 4/5 = 0.8 m². Trapezium area = (0.6 + 1.4)h/2 = h.", "topic": "vol"}, {"id": "VM-Y10-VOL-041", "skill": "Prism recognition", "difficulty": "easy", "question": "A solid has identical triangular cross-sections throughout its 12 cm length. What type of solid is it?", "answer": "Triangular prism", "solution": "A prism has a constant cross-section along its length.", "topic": "vol"}, {"id": "VM-Y10-VOL-042", "skill": "Volume units", "difficulty": "easy", "question": "Which unit is appropriate for the volume of a small wooden block: cm, cm² or cm³?", "answer": "cm³", "solution": "Volume measures three-dimensional space.", "topic": "vol"}, {"id": "VM-Y10-VOL-043", "skill": "Missing cross-section", "difficulty": "medium", "question": "A prism has volume 420 cm³ and length 15 cm. Find its cross-sectional area.", "answer": "28 cm²", "solution": "Area = volume ÷ length = 420 ÷ 15.", "topic": "vol"}, {"id": "VM-Y10-VOL-044", "skill": "Capacity allowance", "difficulty": "medium", "question": "A rectangular tank has internal dimensions 50 cm by 40 cm by 30 cm. It must remain 5 cm below the rim. How many litres can it hold under this rule? The vertical height is 30 cm.", "answer": "50 L", "solution": "Water depth is 25 cm. Volume = 50 × 40 × 25 = 50,000 cm³ = 50 L.", "topic": "vol"}, {"id": "VM-Y10-VOL-045", "skill": "Capacity conversion", "difficulty": "easy", "question": "A container holds 3500 cm³. Express its capacity in litres.", "answer": "3.5 L", "solution": "1000 cm³ = 1 L.", "topic": "vol"}, {"id": "VM-Y10-VOL-046", "skill": "Prism orientation", "difficulty": "medium", "question": "A triangular prism has cross-sectional area 24 cm² and length 15 cm. Does standing it on a triangular end change its volume? Give the volume.", "answer": "No; 360 cm³", "solution": "Orientation does not change volume; 24 × 15 = 360.", "topic": "vol"}, {"id": "VM-Y10-VOL-047", "skill": "Displacement", "difficulty": "hard", "question": "A rectangular tank has base 40 cm by 25 cm. A fully submerged solid raises the water level by 1.8 cm without overflow. Find the solid volume.", "answer": "1800 cm³", "solution": "Displaced volume = 40 × 25 × 1.8.", "topic": "vol"}, {"id": "VM-Y10-VOL-048", "skill": "Capacity investigation", "difficulty": "challenge", "question": "A cylinder and a rectangular prism have equal heights of 10 cm. The cylinder radius is 3 cm and the prism base is a square. Find the square side length for equal volumes, to two decimal places.", "answer": "5.32 cm", "solution": "Equal heights imply equal base areas: s² = 9π, so s = 3√π ≈ 5.32.", "topic": "vol"}, {"id": "VM-Y10-VOL-049", "skill": "Capacity units", "difficulty": "easy", "question": "A measuring jug holds 750 cm³. How many millilitres is this?", "answer": "750 mL", "solution": "One cubic centimetre equals one millilitre.", "topic": "vol"}, {"id": "VM-Y10-VOL-050", "skill": "Uniform section", "difficulty": "medium", "question": "A 12 m long prism has volume 30 m³. A 3 m long piece is cut off perpendicular to its length. Find the remaining volume.", "answer": "22.5 m³", "solution": "The remaining length is 9 m, or three quarters of the original. Volume = 30 × 0.75.", "topic": "vol"}, {"id": "VM-Y10-VOL-051", "skill": "Wall thickness", "difficulty": "hard", "question": "An open rectangular tank has external dimensions 50 cm by 40 cm by 30 cm. Its walls and base are 2 cm thick. Find its internal capacity in litres. The external vertical height is 30 cm.", "answer": "46.368 L", "solution": "Internal dimensions are 46 cm, 36 cm and 28 cm. Product = 46368 cm³; divide by 1000.", "topic": "vol"}, {"id": "VM-Y10-VOL-052", "skill": "Equal capacity design", "difficulty": "challenge", "question": "A cylindrical tank has radius r and height h. A replacement has radius 25% larger. By what percentage must its height decrease to keep capacity unchanged?", "answer": "36%", "solution": "Area multiplier = 1.25² = 1.5625. Height multiplier = 1 ÷ 1.5625 = 0.64.", "topic": "vol"}, {"id": "VM-Y10-VOL-053", "skill": "Capacity difference", "difficulty": "easy", "question": "A jug holds 2.4 L and contains 1750 mL. How much more can it hold?", "answer": "650 mL", "solution": "2400−1750=650.", "topic": "vol"}, {"id": "VM-Y10-VOL-054", "skill": "Triangular channel", "difficulty": "medium", "question": "A straight trough has a triangular cross-section of base 60 cm and height 40 cm. Its length is 2 m. Find its capacity in litres.", "answer": "240 L", "solution": "Cross-section = ½×60×40=1200 cm². Volume = 1200×200=240000 cm³ = 240 L.", "topic": "vol"}, {"id": "VM-Y10-VOL-055", "skill": "Immersion height", "difficulty": "hard", "question": "A fully submerged solid displaces 900 cm³ of water in a rectangular tank with base 30 cm by 20 cm. Find the rise in water level. No water overflows.", "answer": "1.5 cm", "solution": "Rise = displaced volume ÷ base area = 900÷600.", "topic": "vol"}, {"id": "VM-Y10-VOL-056", "skill": "Equal cross-sections", "difficulty": "challenge", "question": "A prism has a semicircular cross-section of radius 6 cm. A second prism of the same length has a rectangular cross-section of width 9 cm. Find its height for equal volumes.", "answer": "2π cm", "solution": "Equal lengths require equal cross-sectional areas. 9h = ½π×36 = 18π.", "topic": "vol"}, {"id": "VM-Y10-VOL-057", "skill": "Capacity comparison", "difficulty": "easy", "question": "A container holds 0.75 L. Is this enough for 800 mL of water?", "answer": "No; short by 50 mL", "solution": "0.75 L = 750 mL, which is 50 mL less than 800 mL.", "topic": "vol"}, {"id": "VM-Y10-VOL-058", "skill": "Prism cross-section from slices", "difficulty": "medium", "question": "A uniform prism has volume 360 cm³. A slice 2 cm thick has volume 48 cm³. Find the prism length.", "answer": "15 cm", "solution": "Cross-sectional area = 48 ÷ 2 = 24 cm². Length = 360 ÷ 24 = 15 cm.", "topic": "vol"}, {"id": "VM-Y10-VOL-059", "skill": "Water transfer", "difficulty": "hard", "question": "A rectangular tank with base 40 cm by 25 cm contains water 12 cm deep. All water is transferred to a tank with base 30 cm by 20 cm. Find the new depth. The receiving tank is rectangular and has sufficient capacity.", "answer": "20 cm", "solution": "Volume = 40 × 25 × 12 = 12000 cm³. Divide by 600 cm².", "topic": "vol"}, {"id": "VM-Y10-VOL-060", "skill": "Composite prism design", "difficulty": "challenge", "question": "A 20 cm long prism has a cross-section made of a rectangle 8 cm wide and 5 cm high topped by a triangle of base 8 cm. Find the triangle height if the volume is 1120 cm³.", "answer": "4 cm", "solution": "Required cross-section = 1120 ÷ 20 = 56 cm². Triangle area = 56 − 40 = 16, so height = 2 × 16 ÷ 8.", "topic": "vol"}, {"id": "VM-Y10-VOL-061", "skill": "Capacity meaning", "difficulty": "easy", "question": "A container has internal volume 0.008 m³. Express its capacity in litres.", "answer": "8 L", "solution": "One cubic metre equals 1000 L; multiply 0.008 by 1000.", "topic": "vol"}, {"id": "VM-Y10-VOL-062", "skill": "Cross-section reconstruction", "difficulty": "medium", "question": "A uniform prism is 25 cm long and holds 1.5 L. Find its cross-sectional area.", "answer": "60 cm²", "solution": "1.5 L = 1500 cm³. Divide by 25.", "topic": "vol"}, {"id": "VM-Y10-VOL-063", "skill": "Partitioned tank", "difficulty": "hard", "question": "A rectangular tank has internal dimensions 80 cm by 40 cm by 50 cm. A solid partition 2 cm thick spans its full width and height. Find the remaining total capacity. The partition is perpendicular to the length.", "answer": "156 L", "solution": "Available length is 78 cm. Volume = 78 × 40 × 50 = 156000 cm³ = 156 L.", "topic": "vol"}, {"id": "VM-Y10-VOL-064", "skill": "Capacity versus height", "difficulty": "challenge", "question": "Two upright containers have the same capacity and height. Must they have equal cross-sectional areas at every height? Explain using a prism and a non-prismatic container.", "answer": "No", "solution": "A prism has constant cross-sectional area. A tapered container can have smaller sections near its base and larger ones near its top while retaining the same total volume.", "topic": "vol"}, {"id": "VM-Y10-VOL-065", "skill": "Capacity comparison", "difficulty": "easy", "question": "Which holds more: a 750 mL bottle or a container of volume 800 cm³?", "answer": "The 800 cm³ container.", "solution": "1 cm³ = 1 mL, so 800 mL exceeds 750 mL.", "topic": "vol"}, {"id": "VM-Y10-VOL-066", "skill": "Uniform cross-section", "difficulty": "medium", "question": "A straight prism has volume 1.8 m³ and length 3 m. Find its cross-sectional area in cm².", "answer": "6000 cm²", "solution": "Area = 1.8/3 = 0.6 m² = 6000 cm².", "topic": "vol"}, {"id": "VM-Y10-VOL-067", "skill": "Composite channel", "difficulty": "hard", "question": "A 5 m long channel has a trapezoidal cross-section with parallel sides 0.4 m and 0.8 m and perpendicular height 0.3 m. Find its full capacity in litres.", "answer": "900 L", "solution": "Cross-sectional area = (0.4+0.8) × 0.3/2 = 0.18 m². Volume = 0.9 m³ = 900 L.", "topic": "vol"}, {"id": "VM-Y10-VOL-068", "skill": "Capacity trade-off", "difficulty": "challenge", "question": "A rectangular tank has internal base 60 cm by 40 cm. A solid block with volume 3600 cm³ rests fully submerged inside it. How much higher is the water level than it would be without the block, assuming no overflow?", "answer": "1.5 cm", "solution": "Displaced volume = base area × rise. Rise = 3600/(60×40) = 1.5.", "topic": "vol"}, {"id": "VM-Y10-VOL-069", "skill": "Volume units", "difficulty": "easy", "question": "A solid has volume 0.04 m³. Express this volume in litres.", "answer": "40 L", "solution": "One cubic metre equals 1000 L, so 0.04 × 1000 = 40 L.", "topic": "vol"}, {"id": "VM-Y10-VOL-070", "skill": "Triangular channel", "difficulty": "medium", "question": "A straight channel has triangular cross-section with base 40 cm and perpendicular height 15 cm. It is 2 m long. Find its full capacity in litres.", "answer": "60 L", "solution": "Cross-section = 300 cm²; length = 200 cm; volume = 60000 cm³ = 60 L.", "topic": "vol"}, {"id": "VM-Y10-VOL-071", "skill": "Hollow prism", "difficulty": "hard", "question": "A 1 m long square tube has outer side 12 cm and inner side 10 cm. Find the volume of material in cm³.", "answer": "4400 cm³", "solution": "Material cross-section = 144 − 100 = 44 cm²; multiply by 100 cm.", "topic": "vol"}, {"id": "VM-Y10-VOL-072", "skill": "Equal capacity design", "difficulty": "challenge", "question": "A cylinder and a rectangular prism have equal heights and equal volumes. The cylinder radius is 6 cm. If the prism base width is 9 cm, find its base length exactly.", "answer": "4π cm", "solution": "Equal volumes and heights imply equal base areas: 9L = 36π, so L = 4π.", "topic": "vol"}, {"id": "VM-Y10-VOL-073", "skill": "Capacity conversion", "difficulty": "easy", "question": "A 600 mL jug is half full. Express the liquid volume in cubic centimetres.", "answer": "300 cm³", "solution": "Half of 600 is 300; 1 mL = 1 cm³.", "topic": "vol"}, {"id": "VM-Y10-VOL-074", "skill": "Partial fill", "difficulty": "medium", "question": "A horizontal rectangular tank has a base of 80 cm by 25 cm. It contains 30 L of water. Find the water depth.", "answer": "15 cm", "solution": "30000 ÷ (80 × 25) = 15.", "topic": "vol"}, {"id": "VM-Y10-VOL-075", "skill": "Sector prism", "difficulty": "medium", "question": "A prism has a quarter-circle cross-section of radius 8 cm and length 15 cm. Find its volume exactly.", "answer": "240π cm³", "solution": "Cross-section = π × 8² ÷ 4 = 16π; multiply by 15.", "topic": "vol"}, {"id": "VM-Y10-VOL-076", "skill": "Capacity constraint", "difficulty": "hard", "question": "A cylindrical container of internal radius 5 cm must hold at least 600 mL. What is the smallest whole-centimetre internal height?", "answer": "8 cm", "solution": "Required height = 600 ÷ (25π) ≈ 7.64 cm; round up.", "topic": "vol"}, {"id": "VM-Y10-VOL-077", "skill": "Capacity conversion", "difficulty": "easy", "question": "A container holds 2.4 L. Express its capacity in cubic centimetres.", "answer": "2400 cm³", "solution": "One litre equals 1000 cm³.", "topic": "vol"}, {"id": "VM-Y10-VOL-078", "skill": "Cross-section", "difficulty": "medium", "question": "A prism of length 25 cm has a trapezoidal cross-section with parallel sides 4 cm and 10 cm and perpendicular height 6 cm. Find its volume.", "answer": "1050 cm³", "solution": "Cross-sectional area = (4 + 10) × 6 ÷ 2 = 42; multiply by 25.", "topic": "vol"}, {"id": "VM-Y10-VOL-079", "skill": "Volume ratio", "difficulty": "medium", "question": "Two cylinders have the same height. One has three times the radius of the other. Compare their volumes.", "answer": "9:1, larger to smaller", "solution": "Volume is proportional to radius squared at fixed height.", "topic": "vol"}, {"id": "VM-Y10-VOL-080", "skill": "Water level", "difficulty": "hard", "question": "A rectangular tank with base 50 cm by 40 cm contains water 12 cm deep. A fully submerged solid displaces 3000 cm³. Find the new depth, assuming no overflow.", "answer": "13.5 cm", "solution": "The rise is 3000 ÷ 2000 = 1.5 cm.", "topic": "vol"}, {"id": "VM-Y10-VOL-081", "skill": "Cross-section units", "difficulty": "easy", "question": "A prism has cross-sectional area 12 cm² and length 7 cm. State its volume with units.", "answer": "84 cm³", "solution": "12 × 7 = 84 cubic centimetres.", "topic": "vol"}, {"id": "VM-Y10-VOL-082", "skill": "Capacity shortfall", "difficulty": "medium", "question": "A rectangular tank has internal dimensions 50 cm by 40 cm by 30 cm. How many more litres are needed if it currently contains 42 L?", "answer": "18 L", "solution": "Capacity = 60000 cm³ = 60 L; 60 − 42 = 18.", "topic": "vol"}, {"id": "VM-Y10-VOL-083", "skill": "Half-cylinder", "difficulty": "medium", "question": "A trough is a half-cylinder with radius 20 cm and length 100 cm. Find its capacity in litres to one decimal place.", "answer": "62.8 L", "solution": "Volume = π × 20² × 100 ÷ 2 = 20000π cm³ = 20π L.", "topic": "vol"}, {"id": "VM-Y10-VOL-084", "skill": "Stepped cross-section", "difficulty": "hard", "question": "A prism 5 m long has an L-shaped cross-section formed by removing a 1 m by 2 m rectangle from a 4 m by 3 m rectangle. Find its volume and the percentage removed relative to the full rectangular prism.", "answer": "50 m³; 16⅔%", "solution": "Remaining area = 12 − 2 = 10; volume = 50. Removed fraction = 2 ÷ 12 = 1/6.", "topic": "vol"}, {"skill": "Capacity units", "difficulty": "easy", "question": "A vessel holds 900 cm³. Express its capacity in litres.", "answer": "0.9 L", "solution": "900 cm³ = 900 mL = 0.9 L.", "id": "VM-Y10-VOL-085", "topic": "vol"}, {"skill": "Prism cross-section", "difficulty": "medium", "question": "A trough has a trapezoidal cross-section with parallel sides 30 cm and 50 cm, perpendicular height 20 cm, and length 120 cm. Find its capacity in litres.", "answer": "96 L", "solution": "Cross-section = (30 + 50) × 20 ÷ 2 = 800 cm²; volume = 96000 cm³.", "id": "VM-Y10-VOL-086", "topic": "vol"}, {"skill": "Partial filling", "difficulty": "hard", "question": "A horizontal rectangular tank has internal dimensions 80 cm by 40 cm by 50 cm. It contains 96 L. How far below the top is the water surface? The vertical height is 50 cm.", "answer": "20 cm", "solution": "Water depth = 96000 ÷ 3200 = 30 cm; remaining height = 20 cm.", "id": "VM-Y10-VOL-087", "topic": "vol"}, {"skill": "Material removal", "difficulty": "hard", "question": "A cylindrical hole of radius 2 cm is drilled completely through a 10 cm cube, perpendicular to a face. Find the remaining volume in terms of π. The hole lies entirely within the cube cross-section.", "answer": "(1000 − 40π) cm³", "solution": "Subtract cylinder volume π × 2² × 10 from 1000.", "id": "VM-Y10-VOL-088", "topic": "vol"}, {"id": "VM-Y10-VOL-089", "skill": "Volume scaling", "difficulty": "easy", "question": "A prism keeps the same cross-section but its length is halved. What happens to its volume?", "answer": "It halves", "solution": "Volume equals cross-sectional area multiplied by length.", "topic": "vol"}, {"id": "VM-Y10-VOL-090", "skill": "Sector prism", "difficulty": "medium", "question": "A solid has a quarter-circle cross-section of radius 6 cm and length 10 cm. Find its volume exactly. The cross-section is constant throughout the length.", "answer": "90π cm³", "solution": "Cross-section = π × 36 ÷ 4 = 9π; multiply by 10.", "topic": "vol"}, {"id": "VM-Y10-VOL-091", "skill": "Overflow", "difficulty": "hard", "question": "A full rectangular tank has a base of 40 cm by 30 cm. After 2 L is removed, a fully submerged solid of volume 2700 cm³ is inserted. How much water overflows?", "answer": "700 mL", "solution": "The available space is 2000 cm³; 2700 − 2000 = 700 cm³.", "topic": "vol"}, {"id": "VM-Y10-VOL-092", "skill": "Capacity redesign", "difficulty": "hard", "question": "A cylinder retains its volume when its height is doubled. By what factor must its radius change? Give an exact answer.", "answer": "1/√2", "solution": "Volume is proportional to r²h. Doubling h requires halving r², so radius is multiplied by 1/√2.", "topic": "vol"}, {"id": "VM-Y10-VOL-093", "skill": "Capacity conversion", "difficulty": "easy", "question": "A container holds 0.018 m³ of water. Express this in litres.", "answer": "18 L", "solution": "1 m³ = 1000 L.", "topic": "vol"}, {"id": "VM-Y10-VOL-094", "skill": "Displacement", "difficulty": "medium", "question": "A solid is fully submerged in a rectangular tank with base 30 cm by 20 cm. Water rises 2.5 cm without spilling. Find the solid volume.", "answer": "1500 cm³", "solution": "30 × 20 × 2.5 = 1500.", "topic": "vol"}, {"id": "VM-Y10-VOL-095", "skill": "Prism cross-section", "difficulty": "medium", "question": "A prism has volume 840 cm³ and length 14 cm. Find its constant cross-sectional area.", "answer": "60 cm²", "solution": "840 ÷ 14 = 60.", "topic": "vol"}, {"id": "VM-Y10-VOL-096", "skill": "Partial capacity", "difficulty": "medium", "question": "A horizontal rectangular trough is 2 m long, 0.5 m wide and 0.4 m deep. How many litres are in it when water is 0.15 m deep?", "answer": "150 L", "solution": "2 × 0.5 × 0.15 = 0.15 m³ = 150 L.", "topic": "vol"}, {"id": "VM-Y10-VOL-097", "skill": "Hollow cylinder", "difficulty": "hard", "question": "A cylindrical pipe is 20 cm long with outer radius 5 cm and inner radius 4 cm. Find the volume of material exactly.", "answer": "180π cm³", "solution": "π(5² − 4²) × 20 = 180π.", "topic": "vol"}, {"id": "VM-Y10-VOL-098", "skill": "Equal volume redesign", "difficulty": "hard", "question": "A rectangular tank with base 60 cm by 40 cm holds water 25 cm deep. All water is transferred to a tank with square base of side 50 cm. Find the new depth. The receiving tank is rectangular and has sufficient capacity.", "answer": "24 cm", "solution": "Volume = 60 × 40 × 25 = 60000; depth = 60000 ÷ 2500.", "topic": "vol"}, {"id": "VM-Y10-VOL-099", "skill": "Capacity comparison", "difficulty": "medium", "question": "A rectangular container measures 25 cm by 16 cm by 12 cm internally. Can it hold 5 L?", "answer": "No; capacity 4.8 L", "solution": "Volume = 4800 cm³ = 4.8 L.", "topic": "vol"}, {"id": "VM-Y10-VOL-100", "skill": "Cylinder redesign", "difficulty": "hard", "question": "A cylinder is redesigned with radius 20% smaller and unchanged volume. By what percentage must its height increase?", "answer": "56.25%", "solution": "New area factor is 0.8² = 0.64; height factor is 1/0.64 = 1.5625.", "topic": "vol"}];
